import{a as e}from"./jsx-runtime-Bzw2jH9X.js";var t=e({default:()=>n}),n=JSON.parse(`[{"id":"qx-c2-001","clusterId":"C","werkstueckRef":"C.4.3","stufe":1,"question":"Ein Gesundheitsportal wirbt: „Unser Immun-Tee stärkt Ihre Abwehr und macht eine Masernimpfung überflüssig.“ Welche Frage prüft diese Behauptung am besten?","options":["Kann ein Getränk, das die allgemeine Abwehr unterstützt, dem Körper die genaue Information über das Masernvirus liefern, die er zum Erkennen braucht?","Wie viele Menschen in meinem Umfeld trinken diesen Tee schon und fühlen sich seitdem gesünder und leistungsfähiger?","Ist der Tee aus pflanzlichen Zutaten hergestellt, die schon seit langer Zeit als bewährte Hausmittel verwendet werden?","Wirkt die Werbeaussage glaubwürdig, weil sie von einem Portal mit sehr vielen Besucherinnen und Besuchern stammt?"],"correctIndex":0,"explanation":"Die Behauptung verwechselt zwei Abwehrebenen. Die angeborene Abwehr ist schnell und grob: Sie springt auf typische Bausteine ganzer Erregergruppen an, erkennt aber nicht den einzelnen Erreger und merkt sich nichts. Die adaptive Abwehr mit B- und T-Zellen wird langsamer aktiviert, ist aber präzise und hinterlässt Gedächtniszellen, die jahrzehntelang im Körper patrouillieren. Für Masern braucht der Körper genau diese spezifische Information über den Erreger. Eine Impfung liefert sie in harmloser Form, ein allgemein „stärkendes“ Getränk kann das nicht. Die anderen Fragen prüfen Verbreitung, Tradition oder Reichweite der Quelle, aber nicht, ob die behauptete Ursache-Wirkung-Kette überhaupt möglich ist.","coreRule":"⚡ Wer eine Impfung ersetzen will, muss zeigen, wie die Maßnahme dem Körper die spezifische Information über genau diesen Erreger liefert. Allgemeine „Stärkung“ reicht dafür nicht.","beleg":"Werkstück C.4.3 (Kontext & Tiefe); Fn. gl-c-mustererkennung (Aster u. a. 2026, S. 169 und 181)","status":"entwurf","scenario":"","kurz":"Eine Impfung liefert dem Körper die spezifische Information über den Erreger, die für Masern nötig ist. Ein Tee, der die Abwehr allgemein „stärkt“, kann das nicht. Der Fehler liegt darin, schnelle, grobe Abwehr mit gezielter, gedächtnisbildender zu verwechseln.","prueffrage":"Welche Belege nennt das Portal dafür, dass Teetrinker ohne Impfung seltener an Masern erkranken?","rueckmeldung":[{"option":1,"text":"Wohlbefinden im Bekanntenkreis ist leicht zu beobachten und wirkt überzeugend. Es zeigt aber nicht, ob jemand vor Masern geschützt ist, und gerade das behauptet die Werbung. Gefühlte Fitness ersetzt keine spezifische Immunität."},{"option":2,"text":"Eine lange Tradition und pflanzliche Zutaten wirken vertrauenswürdig. Sie sagen aber nichts darüber, ob ein Getränk dem Körper den Erreger „vorstellen“ kann. Wie alt oder natürlich ein Mittel ist, beantwortet diese Frage nicht."},{"option":3,"text":"Ein Portal mit vielen Besuchern erreicht viele Menschen. Die Reichweite sagt aber nichts darüber, ob die Aussage stimmt. Entscheidend ist, ob die behauptete Wirkung überhaupt möglich ist, und das lässt sich an der Aussage selbst prüfen."}],"familie":"mechanismus-verlangen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"IQWiG, gesundheitsinformation.de: Wie funktioniert das Immunsystem?","oeffentlich":true,"url":"https://www.gesundheitsinformation.de/wie-funktioniert-das-immunsystem.html","abruf":"2026-10-12"},{"typ":"url","kurz":"WHO: How do vaccines work?","oeffentlich":true,"url":"https://www.who.int/news-room/feature-stories/detail/how-do-vaccines-work","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Aster u. a. (Hrsg.) 2026, Robbins, Cotran & Kumar Pathologic Basis of Disease, 11. Aufl., Elsevier","oeffentlich":false}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"c6acbfa5e8db883d"}},{"id":"qx-c2-002","clusterId":"C","werkstueckRef":"C.4.3","stufe":2,"question":"In einem Gespräch heißt es: „Gegen HIV hilft nur ein stärkeres Immunsystem, und das lässt sich über Ernährung und Lebensstil erreichen.“ Ein Arzt entgegnet, dass das Problem anderswo liegt. Welche Überlegung zeigt am besten, warum HIV die Abwehr als Ganzes zusammenbrechen lässt?","options":["Das Virus zerstört gerade die Helfer-T-Zellen, die die gezielte Abwehr koordinieren; ohne sie laufen B- und T-Zellen ins Leere, auch wenn andere Abwehrzellen da sind.","Das Virus verändert sich so schnell, dass die Helfer-T-Zellen es nicht mehr erkennen; sie bleiben zahlreich, koordinieren die Abwehr aber gegen das falsche Ziel.","Das Virus raubt dem Körper Kraft und Nährstoffe, sodass den Helfer-T-Zellen die Energie fehlt; deshalb schlagen Ernährung und Lebensstil direkt auf die Abwehr durch.","Das Virus zerstört gerade die B-Zellen, die die Antikörper bilden; ohne Antikörper fehlt der Abwehr der gezielte Schutz, selbst wenn die Helfer-T-Zellen vorhanden sind."],"correctIndex":0,"explanation":"HIV greift gezielt die Helfer-T-Zellen an, die „Kommandozentrale“ der adaptiven Immunantwort. Diese Zellen koordinieren die gesamte Operation, also auch die B-Zellen, die Antikörper bilden, und die Killer-T-Zellen. Fällt die Kommandozentrale aus, bricht das gesamte System zusammen. Ein gesunder Lebensstil unterstützt die Abwehr nur allgemein; er ersetzt aber keine spezifische Immunantwort. Dass sich das Virus rasch verändert, stimmt, doch im Fall sinkt die Zahl der Helfer-T-Zellen stark; sie bleiben nicht zahlreich. Dass das Virus Kraft raubt, klingt nach einem Ansatz für Ernährung, ändert aber nichts daran, dass die koordinierenden Zellen fehlen. Eine Zerstörung der B-Zellen würde Antikörper kosten, doch betroffen sind die Helfer-T-Zellen, und ohne sie fehlt das Kommando auch für die B-Zellen.","coreRule":"⚡ Ein System fällt nicht nur aus, wenn alles schwach ist, sondern auch, wenn sein zentraler Koordinator ausfällt. Bei HIV sind das die Helfer-T-Zellen.","beleg":"Werkstück C.4.3 (Anwendung & Relevanz, Bei AIDS & HIV)","status":"entwurf","scenario":"Bei einer HIV-Infektion sinkt die Zahl der Helfer-T-Zellen, die als Koordinatoren der gezielten (adaptiven) Abwehr arbeiten, über Jahre stark ab. Am Ende erkranken Betroffene an Infektionen, die ein gesundes Immunsystem problemlos beherrscht.","kurz":"HIV trifft die Helfer-T-Zellen, die B- und Killer-T-Zellen koordinieren; fehlt dieses Kommando, verpufft die gezielte Abwehr. Mehr Abwehrkraft hilft dann nicht, weil nicht Schwäche allgemein, sondern der Ausfall der Koordination das Problem ist.","prueffrage":"Was zeigen Blutwerte von Menschen mit HIV über die Jahre, und ändert eine gesunde Lebensweise etwas an diesem Verlauf?","rueckmeldung":[{"option":1,"text":"Dass sich das Virus rasch verändert, stimmt. Im geschilderten Fall sinkt aber die Zahl der Helfer-T-Zellen stark, sie bleiben nicht zahlreich. Der Zusammenbruch kommt vom Verlust dieser Zellen, nicht von einer falschen Zielerkennung."},{"option":2,"text":"Ernährung und Lebensstil stützen die Abwehr allgemein, das stimmt. Das Szenario nennt aber keinen Nährstoffraub, sondern den Verlust der Helfer-T-Zellen. Dieses fehlende Kommando lässt sich nicht durch bessere Versorgung ausgleichen."},{"option":3,"text":"Ohne Antikörper fehlte der Abwehr tatsächlich gezielter Schutz. Das Szenario nennt als Ziel aber die Helfer-T-Zellen, nicht die B-Zellen. Diese fallen erst indirekt aus, weil ihnen das Kommando fehlt."}],"familie":"mechanismus-verlangen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"MSD Manual (Consumer Version): Human Immunodeficiency Virus (HIV) Infection","oeffentlich":true,"url":"https://www.msdmanuals.com/home/infections/human-immunodeficiency-virus-hiv-infection/human-immunodeficiency-virus-hiv-infection","abruf":"2026-10-12"},{"typ":"url","kurz":"CDC: About HIV","oeffentlich":true,"url":"https://www.cdc.gov/hiv/about/index.html","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"304f3d4bae66dc1a"}},{"id":"qx-c2-003","clusterId":"C","werkstueckRef":"C.4.3","stufe":3,"question":"Was ist an diesem Argument fehlerhaft, und wo wird aus einer an sich vernünftigen Sorge um die eigene Abwehr ein Risiko?","scenario":"In einem Forum steht: „Impfungen überlasten das Immunsystem. Stärk lieber deine Abwehr mit gesunder Ernährung, viel Schlaf und einem Immun-Tee, dann brauchst du keine Impfung.“","options":["Allgemeine Stärkung ersetzt nicht die spezifische Information über einen bestimmten Erreger; riskant wird es, wenn das vage Stärken gegen die Impfung ausgespielt wird.","Impfungen ersetzen keine Hygiene und gesunde Lebensweise; riskant wird es, wenn man sich allein auf eine Impfung verlässt und Händewaschen oder Schlaf vernachlässigt.","Mehr Vitamine bedeuten nicht automatisch eine stärkere Abwehr; riskant wird es, wenn man Nahrungsergänzung hoch dosiert einnimmt, weil Überschüsse schaden können.","Der Impfschutz lässt bei manchen Krankheiten mit der Zeit nach; riskant wird es, wenn man Auffrischungen versäumt und sich dauerhaft geschützt glaubt."],"correctIndex":0,"explanation":"Ein gesunder Lebensstil unterstützt die allgemeine Funktion des Immunsystems, Ernährung und Schlaf sind also nicht wirkungslos. Aber weder Tee noch Schlaf noch Diät können ihm die spezifische Information geben, einen bestimmten Erreger wie Masern oder Tetanus zu erkennen. Genau das leistet eine Impfung: Sie zeigt dem Immunsystem ein harmloses Erkennungsmerkmal (ein Antigen), sodass es Gedächtniszellen aufbaut, ohne die echte Gefahr zu erleben. Der Überlastungs-Einwand trägt nicht, denn das Immunsystem begegnet täglich tausenden Antigenen. Die Sorge um die eigene Abwehr kippt dort ins Riskante, wo sie gegen die Impfung ausgespielt wird: Dann drohen vermeidbare Erkrankungen. Dass Impfungen keine Hygiene ersetzen, ist richtig, aber der Beitrag verlässt sich nicht auf die Spritze, sondern verwirft sie. Zu hohe Vitamindosen können schaden, doch von Nahrungsergänzung ist hier keine Rede. Und dass Impfschutz nachlassen kann, ist ein Grund für Auffrischungen, kein Fehler in diesem Argument.","coreRule":"⚡ Wer nur die allgemeine Abwehr stärkt, hat noch keine Information über den bestimmten Feind.","quote":"Die allgemeine Sorge um ein gesundes Immunsystem ist positiv.","quoteLabel":"Merksatz:","beleg":"Werkstück C.4.3 (Anwendung & Relevanz; Red Flags; Der Kipppunkt)","status":"entwurf","kurz":"Ernährung und Schlaf unterstützen die Abwehr allgemein, doch keine Diät kann ihr beibringen, einen bestimmten Erreger zu erkennen. Genau das leistet die Impfung. Riskant wird die Sorge, wenn man sie gegen die Impfung ausspielt.","prueffrage":"Welche Belege nennt der Forumsbeitrag für seine beiden Behauptungen?","rueckmeldung":[{"option":1,"text":"Dass Impfungen Hygiene und gesunde Lebensweise nicht ersetzen, stimmt. Der Beitrag verlässt sich aber gerade nicht auf die Spritze, sondern verwirft sie. Der Fehler liegt also in der Gegenrichtung."},{"option":2,"text":"Zu hohe Vitamindosen können tatsächlich schaden. Im Beitrag ist aber nur von Ernährung, Schlaf und Tee die Rede, nicht von hoch dosierten Präparaten. Die Aufgabe fragt nach dem Fehler in diesem Argument."},{"option":3,"text":"Bei manchen Krankheiten kann der Impfschutz mit der Zeit nachlassen, deshalb gibt es Auffrischungen. Das ist aber kein Fehler dieses Beitrags, der gar nicht impfen will, statt Auffrischungen zu versäumen."}],"familie":"mechanismus-verlangen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"WHO: How do vaccines work?","oeffentlich":true,"url":"https://www.who.int/news-room/feature-stories/detail/how-do-vaccines-work","abruf":"2026-10-12"},{"typ":"url","kurz":"Offit u. a. 2002, Addressing parents' concerns: do multiple vaccines overwhelm or weaken the infant's immune system?, Pediatrics 109(1) (PubMed-Abstract)","oeffentlich":true,"doi":"10.1542/peds.109.1.124","url":"https://pubmed.ncbi.nlm.nih.gov/11773551/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"60c6fda05289542f"}},{"id":"qx-c2-004","clusterId":"C","werkstueckRef":"C.4.3","stufe":4,"question":"Wie lässt sich Jenners Rolle angesichts dieser Hinweise am treffendsten beschreiben?","scenario":"Im Geschichtsunterricht heißt es: „Edward Jenner hat 1796 die Impfung erfunden.“ Du recherchierst nach und findest zwei Hinweise: Ein Bauer namens Benjamin Jesty hatte seine Familie schon 1774 mit Kuhpocken geimpft. Außerdem wurde in Europa seit Jahrzehnten mit echtem Pockenmaterial geimpft (Variolation), was gelegentlich selbst Pocken auslöste.","options":["Er ersetzte in der Variolation das Pockenmaterial durch Kuhpocken und bleibt deshalb der Erfinder der Impfung, auch wenn Jesty schon früher ähnlich vorging.","Er übernahm Jestys Kuhpocken-Impfung ohne eigene Prüfung in seine Schrift; sein Ruhm beruht vor allem auf der besseren Öffentlichkeitsarbeit.","Er prüfte das schon vor ihm angewandte Kuhpocken-Verfahren systematisch, veröffentlichte die Ergebnisse und trug wesentlich zu seiner Verbreitung bei.","Wer 1774 als Erster mit Kuhpocken impfte, ist nicht sicher geklärt; erst wenn feststeht, ob Jesty oder ein Variolator es tat, lässt sich Jenners Rolle beurteilen."],"correctIndex":2,"explanation":"Der Satz „X hat Y erfunden“ behauptet eine Priorität, und die lässt sich prüfen: Jesty impfte schon 1774 mit Kuhpocken, und die Variolation mit echtem Pockenmaterial war seit Jahrzehnten verbreitet. Damit fällt „erster Anwender“ weg. Jenners Leistung liegt in einem anderen Schritt: Er prüfte das Verfahren systematisch, veröffentlichte seine Ergebnisse 1798 und warb unermüdlich dafür; Antikörper und Gedächtniszellen kannte er nicht, diese Mechanismen wurden erst viel später verstanden. Bei Erfindungsgeschichten lohnt sich deshalb die Frage, was genau jemand getan hat: ausprobiert, belegt oder bekannt gemacht. Wer Jenner zum Erfinder macht, weil er Pockenmaterial durch Kuhpocken ersetzte, übersieht, dass Jesty schon vorher mit Kuhpocken impfte. Wer ihn zum bloßen Übernehmer macht, übersieht seine eigene Prüfung und Veröffentlichung, die eigene Leistungen sind. Und dass die Frage des ersten Impfers offen bleibt, hindert nicht daran, zu beurteilen, was Jenner nachweislich getan hat.","coreRule":"⚡ Bei Erfindungsmythen genau fragen, was jemand als Erster getan hat: Wer ein Verfahren zuerst benutzt, hat es noch nicht zuerst geprüft.","beleg":"Werkstück C.4.3 (Die Melkerinnen und die Pocken); Fn. gl-c-jenner (Jenner 1798; Riedel 2005, S. 22, 23 und 25)","status":"entwurf","kurz":"Der Satz „X hat Y erfunden“ behauptet eine Priorität, und die fällt hier weg: Jesty impfte schon 1774 mit Kuhpocken. Jenners Leistung ist ein anderer Schritt: Er prüfte das Verfahren systematisch, veröffentlichte es und verbreitete es.","prueffrage":"Was genau tat Jenner 1796 und in den Jahren danach, und was davon ist durch Quellen belegt?","rueckmeldung":[{"option":0,"text":"Kuhpocken statt Pockenmaterial zu verwenden, klingt nach einem neuen Verfahren, das den Erfinder-Titel rechtfertigt. Jesty impfte aber schon 1774 mit Kuhpocken; als erster Anwender fällt Jenner also weg. Seine Leistung liegt in einem anderen Schritt."},{"option":1,"text":"Jesty war tatsächlich früher, und Jenner machte das Verfahren bekannt. Daraus folgt aber nicht, dass er ungeprüft übernahm: Seine systematische Prüfung und die Veröffentlichung 1798 sind eigene Leistungen, die mehr sind als Öffentlichkeitsarbeit."},{"option":3,"text":"Offen ist tatsächlich, wer 1774 als Erster impfte. Das hindert aber nicht an einem Urteil über Jenner: Was er nachweislich tat, nämlich prüfen, veröffentlichen und werben, steht fest und ist von dieser Frage unabhängig."}],"familie":"zitat-am-original-pruefen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Riedel 2005, Edward Jenner and the History of Smallpox and Vaccination, Baylor Univ Med Cent Proc 18(1) (PMC1200696)","oeffentlich":true,"doi":"10.1080/08998280.2005.11928028","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Jenner 1798, An Inquiry into the Causes and Effects of the Variolæ Vaccinæ, London: Sampson Low","oeffentlich":false}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"7ed9ffbb0e67dd85"}},{"id":"qx-c2-005","clusterId":"C","werkstueckRef":"C.4.4","stufe":1,"question":"Welche Antwort prüft die Behauptung am besten, ein Mittel „heile Krebs“?","options":["Die Behauptung ist unplausibel, weil Krebs hunderte verschiedene Krankheiten mit je eigenen Mutationen umfasst, sodass ein einziges Mittel für alle kaum denkbar ist.","Die Behauptung ist unplausibel, weil natürliche Stoffe grundsätzlich zu schwach wirken, sodass nur im Labor entwickelte Wirkstoffe überhaupt gegen Krebs in Frage kommen.","Die Behauptung ist unplausibel, weil Krebszellen körpereigene Zellen sind, sodass ein Mittel, das sie trifft, kaum gesunde Zellen verschonen und deshalb nie heilen würde.","Die Behauptung ist unplausibel, weil Krebs meist erst nach der Streuung entdeckt wird, sodass ein einzelnes natürliches Mittel nie jeden Tumor im Körper erreichen könnte."],"correctIndex":0,"explanation":"Unter „Krebs“ fallen hunderte verschiedene Krankheiten. Lungenkrebs verhält sich völlig anders als Hautkrebs, und jeder Tumor hat eine eigene genetische Signatur, denn Krebs entsteht, wenn körpereigene Zellen durch Mutationen in ihrer DNA die Kontrolle über Wachstum und Teilung verlieren. Schon deshalb ist die Idee „eines“ Heilmittels für alle Krebsarten biologisch unplausibel; moderne Therapien zielen auf die spezifischen Mutationen des jeweiligen Tumors. Die Verschwörungserzählung ersetzt diese Überlegung durch eine bequeme Schuldzuweisung. Dass natürliche Stoffe zu schwach seien, ist falsch: Manche Krebsmedikamente stammen ursprünglich aus Pflanzen. Dass Krebszellen körpereigen sind, erklärt Nebenwirkungen mancher Chemotherapien, doch moderne Therapien zielen gerade auf Merkmale des Tumors und verschonen viele gesunde Zellen. Dass viele Tumoren spät auffallen, gilt nur für manche Krebsarten und erklärt nicht, warum ein Mittel für alle ausscheiden sollte.","coreRule":"⚡ Krebs ist keine einzelne Krankheit, sondern hunderte; ein einziges Wundermittel für alle ist biologisch unplausibel.","beleg":"Werkstück C.4.4 (Kernidee; Kontext & Tiefe; Red Flags)","status":"entwurf","scenario":"Ein Beitrag im Netz verspricht: „Dieses natürliche Mittel heilt Krebs, doch die Pharmaindustrie unterdrückt es.“ Du willst herausfinden, ob die Behauptung biologisch überhaupt plausibel ist.","kurz":"Unter „Krebs“ stecken hunderte verschiedene Krankheiten mit jeweils eigenen Mutationen. Ein einziges Heilmittel für alle ist deshalb biologisch unplausibel. Der Denkfehler: „Krebs“ wie eine einzige Krankheit zu behandeln.","prueffrage":"Gleichen sich Lungenkrebs und Hautkrebs in Ablauf und Behandlung, oder unterscheiden sie sich deutlich?","rueckmeldung":[{"option":1,"text":"Dass Pflanzenstoffe harmlos oder schwach seien, ist ein verbreitetes Vorurteil, das hier nicht trägt: Manche Krebsmedikamente stammen ursprünglich aus Pflanzen. Die Herkunft eines Stoffs sagt nichts darüber, ob er gegen Krebs wirkt."},{"option":2,"text":"Krebszellen sind tatsächlich körpereigen, und das erklärt Nebenwirkungen mancher Chemotherapien. Daraus folgt aber nicht, dass jedes Mittel gesunde Zellen mitschädigt: Moderne Therapien zielen auf Merkmale des Tumors und verschonen viele gesunde Zellen."},{"option":3,"text":"Manche Krebsarten fallen tatsächlich spät auf. Das gilt aber nicht für alle und sagt nichts darüber, warum ein Mittel für sämtliche Krebsarten ausscheiden sollte. Der eigentliche Knackpunkt liegt in der Vielfalt der Krankheiten, nicht im Zeitpunkt der Entdeckung."}],"familie":"genau-unterscheiden","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"National Cancer Institute: What Is Cancer?","oeffentlich":true,"url":"https://www.cancer.gov/about-cancer/understanding/what-is-cancer","abruf":"2026-10-12"},{"typ":"url","kurz":"Krebsinformationsdienst (DKFZ): Ernährungsmythen bei Krebs (2016)","oeffentlich":true,"url":"https://www.krebsinformationsdienst.de/aktuelles/detail/ernaehrungsmythen-bei-krebs","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"962d8547cc0c5384"}},{"id":"qx-c2-006","clusterId":"C","werkstueckRef":"C.4.4","stufe":2,"question":"Welcher Rat ist in dieser Lage am besten begründet?","scenario":"Die Mutter einer Bekannten hat eine Krebsdiagnose erhalten; die Ärzte raten, den Tumor in den nächsten zwei Wochen operativ zu entfernen. Im Netz hat die Bekannte gelesen, man könne einen Tumor mit zuckerfreier Kost „aushungern“ oder mit basischer Kost „entsäuern“. Sie überlegt, die Operation zu verschieben, und fragt dich um Rat.","options":["Rate ihr, zuerst die Diät zu testen: Tumorzellen verbrauchen viel Zucker, also schwächt eine zuckerfreie Kost den Tumor in drei Monaten so weit, dass die spätere Operation leichter wird.","Rate ihr, die Operation zu behalten und die Diät dazuzunehmen: Ernährung senkt das Krebsrisiko, also hindert die zuckerfreie Kost den Tumor bis zum Operationstermin am Weiterwachsen.","Rate ihr, die Operation nur um zwei Wochen zu verschieben: In dieser Zeit entsäuert basische Kost den Tumor, und ein entsäuerter Tumor lässt sich danach leichter und sicherer entfernen.","Rate ihr, die Operation nicht zu verschieben: Ernährung kann das Erkrankungsrisiko senken, doch keine Diät hungert einen bestehenden Tumor aus; sie kann die Behandlung nur begleiten."],"correctIndex":3,"explanation":"Eine gesunde Ernährung kann das Krebsrisiko senken, doch ein bereits bestehender, durch Mutationen veränderter Tumor lässt sich nicht gezielt „aushungern“ oder „entsäuern“: Krebszellen sind anpassungsfähige Überlebenskünstler und finden immer einen Weg, sich zu ernähren. Gefährlich wird ein solcher Ansatz, wenn er eine medizinische Behandlung ersetzt oder verzögert, denn bei Krebs entscheidet oft die Zeit zwischen heilbar und unheilbar; deshalb bleibt die Operation beim empfohlenen Termin, und die Ernährung kann sie höchstens begleiten. Ebenso verdächtig sind Theorien, die „den“ Krebs als eine einzige Krankheit mit einer einzigen Ursache und Heilung darstellen, und die Behauptung, Krebs werde durch „Übersäuerung“ verursacht, ist ein klares Warnsignal für Krebs-Unsinn. Der Zucker-Gedanke klingt einleuchtend, scheitert aber daran, dass sich der Tumor anpasst, und kostet drei Monate. Auch zwei Wochen Aufschub für basische Kost verschieben die Behandlung für einen Mechanismus, den es bei einem bestehenden Tumor nicht gibt. Und dass Ernährung das Erkrankungsrisiko senkt, betrifft die Entstehung von Krebs, nicht das Wachstum eines Tumors, der schon da ist.","coreRule":"⚡ Ernährung kann das Risiko beeinflussen, aber sie heilt keinen bestehenden, mutierten Tumor. Wer sie als Ersatz für eine Behandlung anbietet, gefährdet Leben.","beleg":"Werkstück C.4.4 (Anwendung & Relevanz, Gegen „Krebs-Diäten“ & „Entgiftungs“-Mythen; Red Flags)","status":"entwurf","kurz":"Ernährung kann das Erkrankungsrisiko senken, doch ein bestehender Tumor lässt sich nicht „aushungern“ oder „entsäuern“. Der Fehler wäre, von der Risikosenkung auf Heilung zu schließen und dafür Zeit zu verlieren, die bei Krebs oft entscheidet.","prueffrage":"Was genau müsste die Diät beim Tumor bewirken, und was spricht dafür, dass es das tut?","rueckmeldung":[{"option":0,"text":"Dass Tumorzellen viel Zucker verbrauchen, klingt nach einem schwachen Punkt. Doch sie passen sich an und finden andere Energiequellen, sodass nichts „ausgehungert“ wird. Drei Monate Aufschub aber sind ein echtes Risiko, denn bei Krebs entscheidet oft die Zeit."},{"option":1,"text":"Die Operation zu behalten ist richtig. Dass Ernährung das Risiko senkt, betrifft aber die Entstehung von Krebs, nicht das Wachstum eines Tumors, der schon da ist; eine Diät hält ihn bis zum Termin nicht auf."},{"option":2,"text":"Zwei Wochen wirken wie ein kleiner Preis. Der Termin liegt aber genau in diesem Zeitraum, und „Entsäuern“ gibt es bei einem bestehenden Tumor nicht; Übersäuerung als Krebsursache ist ein Warnsignal. So geht Zeit ohne Gegenwert verloren."}],"familie":"ergaenzen-oder-ersetzen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Krebsinformationsdienst (DKFZ): Diäten bei Krebs","oeffentlich":true,"url":"https://www.krebsinformationsdienst.de/ernaehrung-bei-krebs/krebsdiaeten","abruf":"2026-10-12"},{"typ":"url","kurz":"Krebsinformationsdienst (DKFZ): Ernährungsmythen bei Krebs (2016)","oeffentlich":true,"url":"https://www.krebsinformationsdienst.de/aktuelles/detail/ernaehrungsmythen-bei-krebs","abruf":"2026-10-12"},{"typ":"url","kurz":"Johnson u. a. 2018, Use of Alternative Medicine for Cancer and Its Impact on Survival, J Natl Cancer Inst 110(1) (PubMed-Abstract)","oeffentlich":true,"doi":"10.1093/jnci/djx145","url":"https://pubmed.ncbi.nlm.nih.gov/28922780/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"7724e76cc8ad3a8d"}},{"id":"qx-c2-007","clusterId":"C","werkstueckRef":"C.4.4","stufe":3,"question":"Warum ist genau dieser Vorschlag gefährlich, obwohl Ernährung und Entspannung an sich nützlich sein können?","options":["Weil Ernährung und Entspannung die Wirkung einer Chemotherapie grundsätzlich abschwächen, sobald beides zusammen angewandt wird.","Weil Maßnahmen, die Nebenwirkungen der Behandlung lindern, den Tumor angeblich weniger stark bekämpfen lassen.","Weil jede Gewohnheit, die länger als einige Monate durchgehalten wird, die Krebszellen zur Anpassung und Resistenz zwingt.","Weil das Programm die Therapie ersetzen soll und der Patient so wertvolle Zeit verliert."],"correctIndex":3,"explanation":"Der Fehler liegt nicht in der Begleitung, sondern im Ersatz. Ein gesunder Lebensstil und psychologische Unterstützung können eine Krebstherapie sinnvoll ergänzen. Gefährlich wird es, wenn sie an die Stelle der Behandlung treten: Keine Diät kann einen bereits existierenden, genetisch mutierten Tumor aushungern, und wer stattdessen wartet, verliert wertvolle Zeit. Bei Krebs ist Zeit oft ein entscheidender Faktor, eine Verzögerung kann den Unterschied zwischen heilbar und unheilbar bedeuten. Die anderen Begründungen erfinden Wirkungen, die es nicht gibt: Ergänzende Maßnahmen schwächen die Therapie nicht pauschal ab, und eine Linderung von Nebenwirkungen lässt den Tumor nicht unbehandelt wachsen. Ebenso wenig zwingt eine Gewohnheit die Krebszellen allein durch ihre Dauer zur Resistenz. Resistenzen entstehen durch Selektion: Zellen, die Therapien am besten widerstehen, überleben und vermehren sich.","coreRule":"⚡ Begleiten ist erlaubt, ersetzen ist der Kipppunkt – bei Krebs zählt jede Verzögerung.","beleg":"Werkstück C.4.4 (Der Kipppunkt; Red Flags)","status":"entwurf","scenario":"Ein Patient hat gerade die Diagnose Krebs erhalten. Die Ärztin empfiehlt eine Operation mit anschließender Chemotherapie. Eine Anbieterin von „ganzheitlicher Krebsberatung“ sagt zu ihm: „Mit meinem Ernährungs- und Entspannungsprogramm brauchst du die Operation und die Chemotherapie nicht. Warte erst einmal ab, wie es wirkt.“","quote":"","quoteLabel":"","kurz":"Gefährlich ist nicht das Programm selbst, sondern dass es die Behandlung ersetzen soll. Wer abwartet, statt sich behandeln zu lassen, verliert Zeit, und bei Krebs kann eine Verzögerung über heilbar oder unheilbar entscheiden.","prueffrage":"Was verspricht die Anbieterin genau, und auf welche Belege für die Wirkung ihres Programms bei Tumoren stützt sie sich?","rueckmeldung":[{"option":0,"text":"Die Sorge, Zusätzliches könne die Therapie stören, liegt nahe. Ernährung und Entspannung schwächen eine Chemotherapie aber nicht grundsätzlich ab; gefährlich ist hier, dass das Programm die Behandlung ersetzen soll."},{"option":1,"text":"Dass eine Behandlung nur wirkt, wenn sie spürbar zusetzt, liegt nahe, weil Wirkung und Nebenwirkungen bei der Chemotherapie oft zusammen auftreten. Den Tumor bekämpft aber die Therapie selbst, gelinderte Beschwerden schwächen sie nicht."},{"option":2,"text":"Resistenz ist ein reales Phänomen, deshalb wirkt „Anpassung“ plausibel. Sie entsteht aber durch Selektion unter Therapie, nicht durch lange durchgehaltene Gewohnheiten, und mit der Gefahr dieses Vorschlags hat das nichts zu tun."}],"familie":"ergaenzen-oder-ersetzen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Krebsinformationsdienst (DKFZ): Diäten bei Krebs","oeffentlich":true,"url":"https://www.krebsinformationsdienst.de/ernaehrung-bei-krebs/krebsdiaeten","abruf":"2026-10-12"},{"typ":"url","kurz":"Johnson u. a. 2018, Use of Alternative Medicine for Cancer and Its Impact on Survival, J Natl Cancer Inst 110(1) (PubMed-Abstract)","oeffentlich":true,"doi":"10.1093/jnci/djx145","url":"https://pubmed.ncbi.nlm.nih.gov/28922780/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Greaves & Maley 2012, Clonal evolution in cancer, Nature 481 (PMC3367003)","oeffentlich":true,"doi":"10.1038/nature10762","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"195f46467fe75f0b"}},{"id":"qx-c2-008","clusterId":"C","werkstueckRef":"C.4.4","stufe":4,"question":"Eine Patientin liest: „Der Tumor sprach auf die Chemotherapie zunächst gut an, ist nach einem Jahr aber trotz unveränderter Behandlung wieder gewachsen.“ Sie fragt, ob die Therapie von Anfang an gelogen war. Welche Erklärung ist die sparsamste?","options":["Unter der Therapie überleben vor allem die Zellen, die sie besser vertragen. Sie vermehren sich weiter, und der Tumor besteht nach und nach überwiegend aus ihren Nachkommen.","Die Chemotherapie hat in einer der vielen Tumorzellen eine neue Mutation ausgelöst. Aus dieser Zelle ist ein zweiter, unempfindlicher Tumor entstanden, der den ursprünglichen ersetzt.","Mit der Zeit baut der Körper das Medikament schneller ab. Bei unveränderter Dosis erreicht dann weniger Wirkstoff den Tumor, sodass die verbliebenen Zellen wieder wachsen können.","Der Tumor bildet mit der Zeit neue Blutgefäße und wird besser mit Nährstoffen versorgt. Dadurch wächst er wieder, obwohl die Therapie dieselben Zellen weiterhin trifft."],"correctIndex":0,"explanation":"Ein Tumor ist keine einheitliche Masse, sondern ein Gemisch aus Zellen mit leicht unterschiedlichen Mutationen, die um Platz und Nährstoffe konkurrieren. Eine Therapie wirkt wie ein Filter: Zellen, die sie schlechter vertragen, sterben, und die Zellen, die sie besser überstehen, vermehren sich weiter. Das ist natürliche Selektion im Kleinen, und sie erklärt den Rückfall ohne Zusatzannahmen; die Behandlung war also nicht „gelogen“, sie hat die empfindlichen Zellen tatsächlich getroffen. Dass die Chemotherapie eine neue Mutation auslöst und einen Zweittumor erzeugt, kommt vor, erklärt aber nicht, warum der behandelte Tumor wieder wächst, denn die Zellen verändern sich ohnehin bei jeder Teilung. Ein schnellerer Abbau des Medikaments braucht eine Zusatzannahme, die im Fall nicht vorkommt, während die Unterschiede zwischen den Zellen schon gegeben sind. Neue Blutgefäße ermöglichen Wachstum, setzen aber ebenfalls eine zusätzliche Veränderung voraus, die der Fall nicht nennt.","coreRule":"⚡ Ein Tumor ist Evolution im Kleinen: Was die Therapie überlebt, vermehrt sich – und der Rückfall ist dann kein Widerspruch, sondern genau das, was man erwarten muss.","beleg":"Werkstück C.4.4 (Kontext & Tiefe, Krebs ist Evolution im eigenen Körper)","status":"entwurf","scenario":"Ein erkennbarer Tumor besteht meist aus Milliarden Zellen, die sich bei jeder Teilung leicht verändern können. Eine Therapie tötet nicht alle diese Zellen gleich gut.","kurz":"Der Tumor ist ein Gemisch verschieden empfindlicher Zellen: Die Therapie tötet die empfindlichen, die besser vertragenden überleben und vermehren sich. Das erklärt den Rückfall ohne Zusatzannahme; die Behandlung hat also tatsächlich gewirkt.","prueffrage":"Sprechen die Zellen, die nach einem Jahr wachsen, noch genauso auf das Mittel an wie die Zellen zu Beginn?","rueckmeldung":[{"option":1,"text":"Dass eine Chemotherapie selbst neue Mutationen auslöst und einen Zweittumor erzeugt, kommt vor. Hier erklärt es aber nicht, warum der behandelte Tumor wieder wächst, denn die Zellen verändern sich ohnehin bei jeder Teilung."},{"option":2,"text":"Ein schnellerer Abbau des Medikaments wäre denkbar und würde das Wachstum erklären. Der Fall nennt davon aber nichts, während die Unterschiede zwischen den Zellen schon gegeben sind und ohne Zusatzannahme genügen."},{"option":3,"text":"Neue Blutgefäße können Wachstum tatsächlich fördern. Das wäre jedoch eine zusätzliche Veränderung, die der Fall nicht nennt. Außerdem trifft die Therapie nicht mehr dieselben Zellen wie am Anfang: Die empfindlichen sind weitgehend verschwunden."}],"familie":"auslese-statt-plan","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Greaves & Maley 2012, Clonal evolution in cancer, Nature 481 (PMC3367003)","oeffentlich":true,"doi":"10.1038/nature10762","abruf":"2026-10-12"},{"typ":"url","kurz":"National Cancer Institute: What Is Cancer?","oeffentlich":true,"url":"https://www.cancer.gov/about-cancer/understanding/what-is-cancer","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"6b3f963d9e85139c"}},{"id":"qx-c2-009","clusterId":"C","werkstueckRef":"C.4.5","stufe":1,"question":"Was ist an dem Schluss der Mitprobandin fehlerhaft, und was erklärt deine Beschwerden am besten?","scenario":"In einer Medikamentenstudie klärt dich eine Ärztin ausführlich über mögliche Nebenwirkungen des Prüfmittels auf. Kurz nach der Einnahme bekommst du Kopfschmerzen und Übelkeit. Später wird bekannt, dass du zur Placebo-Gruppe gehörtest und nur eine wirkstofffreie Tablette erhalten hast. Eine Mitprobandin sagt: „Dann hast du dir die Beschwerden nur eingebildet.“","options":["Der Schluss ist fehlerhaft: Aus „kein Wirkstoff“ folgt nicht „keine Wirkung“, denn auch ein Placebo kann Beschwerden lindern, weil es die Hoffnung auf Besserung weckt.","Der Schluss ist fehlerhaft: Aus „kein Wirkstoff“ folgt nicht „keine echten Beschwerden“, denn negative Erwartungen können reale körperliche Symptome auslösen.","Der Schluss ist fehlerhaft: Aus „kein Wirkstoff“ folgt nicht „eingebildet“, denn im Rückblick wirkt der Zusammenhang klarer, als er war (Rückschaufehler).","Der Schluss ist fehlerhaft: Aus „kein Wirkstoff“ folgt nicht „eingebildet“, denn wer sich in einer Studie beobachtet fühlt, verhält sich anders (Beobachtungseffekt)."],"correctIndex":1,"explanation":"Die Mitprobandin vermischt zwei Dinge: „ohne Wirkstoff“ und „ohne echte Wirkung“. Wer über mögliche Nebenwirkungen aufgeklärt wird, verspürt mit höherer Wahrscheinlichkeit genau diese, auch wenn er nur eine Scheinbehandlung bekommt; das heißt Nocebo-Effekt, das Gegenstück zum Placebo. Negative Erwartungen können zum Beispiel die Stressachse des Körpers anregen (vgl. Colloca & Barsky 2020, New England Journal of Medicine). Die Symptome sind also real; ihr Auslöser ist die Erwartung, nicht ein Wirkstoff.","coreRule":"⚡ Erwartung wirkt in beide Richtungen: Placebo bessert, Nocebo belastet. „Kein Wirkstoff“ heißt nicht „keine echten Symptome“.","beleg":"Werkstück C.4.5 (Kernidee; Kontext & Tiefe); Fn. gl-c-colloca (Colloca/Barsky 2020, NEJM 382, S. 554–561)","status":"entwurf","kurz":"Kein Wirkstoff heißt nicht, dass die Beschwerden unecht sind. Die Aufklärung über Nebenwirkungen kann genau diese Symptome auslösen (Nocebo-Effekt): Der Auslöser ist die Erwartung, die Symptome selbst sind real.","prueffrage":"Was hat die Ärztin vor der Einnahme erklärt, und welche Beschwerden traten kurz danach auf?","rueckmeldung":[{"option":0,"text":"Ein Placebo kann tatsächlich lindern, und „kein Wirkstoff, keine Wirkung“ ist wirklich ein Fehlschluss. Du hattest aber keine Besserung, sondern genau die angekündigten Beschwerden. Das erklärt Hoffnung nicht, wohl aber die negative Erwartung."},{"option":2,"text":"Im Rückblick wirken Zusammenhänge oft klarer, als sie waren, das ist ein echter Denkfehler. Er erklärt aber nicht, woher Kopfschmerzen und Übelkeit kommen, und trifft auch nicht den Fehler der Mitprobandin."},{"option":3,"text":"Wer sich beobachtet fühlt, verhält sich tatsächlich anders, und auch Messungen können sich verändern. Kopfschmerzen und Übelkeit bringt das Beobachtetwerden aber nicht hervor. Entscheidend war hier, was dir vorher über Nebenwirkungen gesagt wurde."}],"familie":"fair-testen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Häuser, Hansen & Enck 2012, Nocebo phenomena in medicine: their relevance in everyday clinical practice, Dtsch Arztebl Int 109(26) (PMC3401955)","oeffentlich":true,"doi":"10.3238/arztebl.2012.0459","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Colloca & Barsky 2020, Placebo and Nocebo Effects, New England Journal of Medicine 382(6)","oeffentlich":false,"doi":"10.1056/NEJMra1907805"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"78511838a6dbc944"}},{"id":"qx-c2-010","clusterId":"C","werkstueckRef":"C.4.5","stufe":2,"question":"Was folgt aus der Umfrage des Herstellers für seine Behauptung?","scenario":"Ein Hersteller wirbt: „Unsere blaue Tablette beruhigt nachweislich stärker als die rote.“ Als Beleg nennt er eine Umfrage, in der Testpersonen die blaue Tablette beruhigender fanden und sie sich nach der Einnahme ruhiger fühlten. Wirkstoff und Dosis beider Tabletten sind laut Hersteller identisch.","options":["Sie zeigt nur, dass die Farbe Erwartungen weckt und das Empfinden prägt; ob sie auch die tatsächliche Wirkung verändert, bleibt offen.","Sie zeigt nur, dass die blaue Tablette den Wirkstoff schneller freisetzt als die rote; ob die Beruhigung dadurch auch stärker ausfällt, bleibt offen.","Sie zeigt nur, dass die Farbe bei Beruhigungsmitteln die Wirkung verstärkt; ob das auch bei Schmerz- oder Herzmitteln gilt, bleibt offen.","Sie zeigt nur, dass die rote Tablette schwächer wirkt als die blaue; ob die blaue auch stärker beruhigt als ein Scheinpräparat, bleibt offen."],"correctIndex":0,"explanation":"Schon die Farbe einer Pille prägt die Erwartung: Blau und Grün verbinden Menschen eher mit einer beruhigenden Wirkung. Wer eine blaue Tablette für beruhigend hält und sie dann einnimmt, fühlt sich deshalb oft tatsächlich ruhiger. Das ist ein Erwartungseffekt, der durch Symbolik und Kontext entsteht. Die Umfrage erfasst nur das Empfinden der Testpersonen. Ob die Farbe auch die tatsächliche Wirkung verändert, ist weniger klar: In einem Überblick über zwölf Studien (de Craen u. a. 1996) fielen die Befunde zur Wirksamkeit uneinheitlich aus. Der Schluss von „fühlt sich beruhigender an“ auf „wirkt stärker“ ist deshalb nicht gedeckt. Eine schnellere Freisetzung des Wirkstoffs lässt sich aus Angaben zum Befinden nicht ableiten, und Wirkstoff und Dosis sind laut Hersteller identisch. Dass die Farbe bei Beruhigungsmitteln die Wirkung verstärkt, wäre ein Schluss von einem einzelnen Produkt auf eine ganze Arzneigruppe. Dass die rote Tablette schwächer wirkt, ist nicht gezeigt, denn gemessen wurde nur das Empfinden.","coreRule":"⚡ Wer nur das Empfinden nach einer Behandlung erfasst, misst auch die Erwartung mit. Ob ein Merkmal wie die Pillenfarbe die Wirkung selbst verändert, zeigt erst ein verblindeter Vergleich.","beleg":"Werkstück C.4.5 (Kontext & Tiefe, Die Symbolik); Fn. gl-c-pillenfarbe (de Craen u. a. 1996, BMJ 313, S. 1624–1626)","status":"entwurf","kurz":"Die Umfrage erfasst nur, wie sich die Testpersonen fühlten, und die Farbe weckt Erwartungen, die das Empfinden prägen. Ob die blaue Tablette auch tatsächlich stärker wirkt, bleibt offen; „fühlt sich beruhigender an“ ist nicht „wirkt stärker“.","prueffrage":"Wer hat in der Umfrage was angegeben, und gab es daneben eine Messung, die nicht von den Testpersonen selbst stammt?","rueckmeldung":[{"option":1,"text":"Eine schnellere Freisetzung würde einen Unterschied erklären, doch die Umfrage fragt nur nach dem Befinden. Darüber, wie schnell ein Wirkstoff freigesetzt wird, sagt sie nichts, und Wirkstoff und Dosis sind laut Hersteller gleich."},{"option":2,"text":"Hier steckt gleich zweierlei: Die Umfrage zeigt nur ein verändertes Empfinden, keine verstärkte Wirkung. Und selbst eine solche Wirkung bei einem Produkt ließe sich nicht auf Beruhigungsmittel insgesamt übertragen."},{"option":3,"text":"Dass ein Vergleich mit einem Scheinpräparat fehlt, stimmt. Falsch ist aber, dass die Umfrage die rote Tablette als schwächer zeigt: Gemessen wurde nur das Empfinden, nicht die Wirkung."}],"familie":"fair-testen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"de Craen u. a. 1996, Effect of colour of drugs: systematic review of perceived effect of drugs and of their effectiveness, BMJ 313 (PMC2359128)","oeffentlich":true,"doi":"10.1136/bmj.313.7072.1624","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"998fbd7245aec15c"}},{"id":"qx-c2-011","clusterId":"C","werkstueckRef":"C.4.5","stufe":3,"question":"In einem Vortrag heißt es: „Ein Patient mit orangengroßen Tumoren bekam eine Spritze mit einem angeblichen Wundermittel, die Tumoren verschwanden. Später erfuhr er, dass das Mittel wertlos sei, und der Krebs kam zurück. Glaube kann also Tumoren schmelzen lassen.“ Was ist der entscheidende Haken an diesem Beleg?","options":["Der Fall ist über siebzig Jahre alt; die Medizin hat sich seitdem so verändert, dass er sich nicht auf heutige Patienten übertragen lässt.","Die Schilderung stammt von einem beteiligten Arzt, der befangen ist; erst eine unabhängige Bestätigung durch Außenstehende würde den Fall belegen.","Die Größe der Tumoren wurde nur grob mit „orangengroß“ angegeben; mit genauen Messwerten wäre der Fall ein tragfähiger Beleg.","Es ist ein einzelner, erst später aufgeschriebener Bericht ohne Vergleichsgruppe, der Spontanverläufe und Erinnerungsfehler nicht ausschließt."],"correctIndex":3,"explanation":"Ein einzelner, nachträglich aufgeschriebener Fall ohne Vergleichsgruppe kann nicht zeigen, was die Ursache war. Spontane Verläufe, Fehldiagnosen und Erinnerungsfehler passen genauso zur Geschichte wie ein Erwartungseffekt, und ob sich alles so zugetragen hat, lässt sich gar nicht prüfen. Dazu kommt der Abgleich mit der Datenlage: Kontrollierte Studien finden Placebo-Wirkungen fast nur bei Beschwerden, die Patienten selbst einschätzen, etwa Schmerz oder Übelkeit. Die große Cochrane-Übersicht (Hróbjartsson und Gøtzsche, 2010) fand insgesamt keine wichtigen klinischen Wirkungen von Placebos „im Allgemeinen“. Dass Glaube einen Tumor auflöst, wäre deshalb eine außergewöhnliche Behauptung, für die ein Einzelfall als Beleg nicht reicht. Der Fall ist allerdings auch nicht „widerlegt“: Man kann ihn nicht prüfen, und genau das macht ihn als Beweis wertlos. Dass der Fall alt ist, schmälert seinen Wert nicht grundsätzlich; entscheidend ist, dass sich ein Einzelfall ohne Vergleich nicht prüfen lässt. Ein beteiligter Arzt kann befangen sein, doch auch mit unabhängiger Bestätigung bliebe es ein Einzelfall. Genauere Messwerte würden den Fall besser beschreiben, ihn aber nicht zum Beleg für eine Ursache machen.","coreRule":"⚡ Ein Einzelfall ohne Vergleich beweist keine Wirkung, auch kein Wunder.","beleg":"Werkstück C.4.5 (Die Operation ohne Skalpell; Kontext & Tiefe); Fn. gl-c-klopfer (Klopfer 1957, S. 337–339); Fn. gl-c-placebo-grenzen (Hróbjartsson/Gøtzsche 2010, Cochrane CD003974)","status":"entwurf","scenario":"Der Fall stammt aus den 1950er Jahren und wurde erst nachträglich aufgeschrieben, nach einer persönlichen Mitteilung eines der behandelnden Ärzte. Eine Vergleichsgruppe gab es nicht.","kurz":"Ein einzelner, nachträglich aufgeschriebener Fall ohne Vergleichsgruppe kann nicht zeigen, was die Tumoren schwinden ließ. Spontanverläufe oder Erinnerungsfehler passen genauso zur Geschichte wie ein Erwartungseffekt, und prüfen lässt sich nichts davon.","prueffrage":"Wann und von wem wurde der Fall aufgeschrieben, und lässt sich heute noch nachprüfen, was damals mit dem Patienten geschah?","rueckmeldung":[{"option":0,"text":"Dass der Fall alt ist, fällt sofort auf, schmälert seinen Wert aber nicht grundsätzlich. Der eigentliche Mangel bliebe auch bei einem Fall von gestern bestehen: Ein Einzelfall ohne Vergleich lässt sich nicht prüfen."},{"option":1,"text":"Dass ein beteiligter Arzt befangen sein kann, ist ein berechtigter Gedanke. Doch selbst eine unabhängige Bestätigung änderte nichts am Kern: Es bliebe ein Einzelfall ohne Vergleichsgruppe, der keine Ursache belegt."},{"option":2,"text":"Genauere Messwerte würden den Fall besser beschreiben, was nach einer Lösung klingt. Aber auch ein exakt vermessener Einzelfall zeigt nicht, was die Tumoren schwinden ließ, solange ein Vergleich fehlt."}],"familie":"was-waere-ohne","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Hróbjartsson & Gøtzsche 2010, Placebo interventions for all clinical conditions, Cochrane Database Syst Rev (PMC7156905)","oeffentlich":true,"doi":"10.1002/14651858.CD003974.pub3","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Klopfer 1957, Psychological variables in human cancer, Journal of Projective Techniques 21(4)","oeffentlich":false,"doi":"10.1080/08853126.1957.10380794"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"8b0e889723b0a7f5"}},{"id":"qx-c2-012","clusterId":"C","werkstueckRef":"C.4.5","stufe":4,"question":"Welche Schlussfolgerung ist aus diesem Befund am besten begründet?","scenario":"Eine Kollegin bekommt Kopfschmerzen, sobald sie glaubt, der WLAN-Router laufe – auch dann, wenn er ausgeschaltet ist. Eine große, im Auftrag der WHO erstellte Übersicht von 41 Experimenten kommt zu folgendem Ergebnis: Echte Funkfelder hatten keine oder nur kleine, nicht signifikante Wirkungen auf Beschwerden. Beschwerden traten aber häufiger auf, wenn den Versuchspersonen eine Strahlung angekündigt wurde. Das galt unabhängig davon, ob wirklich gesendet wurde.","options":["Die Funkstrahlung des Routers ist der naheliegende Auslöser, weil empfindliche Menschen auf schwache Felder reagieren, was in Mittelwerten untergeht.","Die Erwartung der Kollegin ist der naheliegende Auslöser, weil die Beschwerden dem geglaubten und nicht dem tatsächlichen Reiz folgen.","Eine dritte Größe wie langes Sitzen am Bildschirm ist der naheliegende Auslöser, weil sie Router-Nutzung und Kopfschmerzen gleichermaßen begünstigen kann.","Der Zufall ist der naheliegende Auslöser, weil Kopfschmerzen häufig sind und an manchen Tagen mit dem vermuteten Einschalten des Routers zusammenfallen."],"correctIndex":1,"explanation":"Die Übersicht fand: Echte Funkfelder hatten keine oder nur kleine, nicht signifikante Wirkungen, Symptome traten aber vermehrt auf, wenn die Exposition angekündigt war – also bezogen auf den wahrgenommenen, nicht auf den realen Feldzustand. Das spricht dafür, dass nicht die Strahlung, sondern die Erwartung die Beschwerden erzeugt. Das erklärt auch den Fall der Kollegin: Ihre Kopfschmerzen sind real, die negative Erwartung kann sie erzeugen (Nocebo-Effekt). „Real“ heißt also nicht „von außen verursacht“, und „von der Erwartung verursacht“ heißt nicht „erfunden“. Auf den Einzelfall übertragen ist das nur eine Wahrscheinlichkeitsaussage: Die Erwartung ist die naheliegendste Erklärung, aber im Einzelfall bleibt es eine Schlussfolgerung. Ob sie bei der Kollegin zutrifft, ließe sich nur durch eine verblindete Prüfung klären.","coreRule":"⚡ Wo die Beschwerden dem geglaubten statt dem tatsächlichen Reiz folgen, liegt Nocebo nahe.","beleg":"Werkstück C.4.5 (Bei Verschwörungsmythen, Nocebo); Fn. gl-c-nocebo-emf (Bosch-Capblanch u. a. 2024, Environment International 187, Art. 108612)","status":"entwurf","kurz":"Die Beschwerden folgen dem, was Menschen glauben, nicht dem, was gesendet wird: Bei angekündigter Strahlung traten sie häufiger auf, ob gesendet wurde oder nicht. Naheliegend, aber falsch: ein echtes Feld als Ursache zu vermuten.","prueffrage":"Wann treten die Beschwerden auf, und was passiert in den Fällen, in denen der Router gar nicht läuft?","rueckmeldung":[{"option":0,"text":"Dass manche Menschen besonders empfindlich reagieren, klingt vernünftig. Die Übersicht fand für echte Funkfelder aber kaum Wirkung, und die Kollegin hat die Beschwerden sogar beim ausgeschalteten Router. Der Befund stützt diese Annahme also nicht."},{"option":2,"text":"Langes Sitzen am Bildschirm kann tatsächlich Kopfschmerzen begünstigen. Es erklärt aber nicht, warum die Beschwerden dem Glauben folgen statt dem tatsächlichen Senden, denn genau das wurde in den Versuchen getrennt."},{"option":3,"text":"Kopfschmerzen sind häufig, und einzelne Zusammentreffen kommen vor. Über 41 Experimente entsteht durch Zufall aber kein Muster, in dem die Beschwerden gerade bei angekündigter Strahlung häufiger auftreten, ob gesendet wird oder nicht."}],"familie":"fair-testen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Bosch-Capblanch u. a. 2024, The effects of radiofrequency electromagnetic fields exposure on human self-reported symptoms: A systematic review of human experimental studies, Environment International 187 (PubMed-Abstract)","oeffentlich":true,"doi":"10.1016/j.envint.2024.108612","url":"https://pubmed.ncbi.nlm.nih.gov/38640611/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"66f1ddc1ec60a5aa"}},{"id":"qx-c2-013","clusterId":"C","werkstueckRef":"C.4.6","stufe":1,"question":"Ein Freund erzählt dir begeistert: „Ich hatte eine schwere Erkältung, am schlimmsten ging es mir am dritten Tag. Da habe ich einen Kräutertee für 50 Euro gekauft. Vier Tage später war ich fast beschwerdefrei. Der Tee wirkt!“ Welche Erklärung für seine Besserung ist am sparsamsten, wenn du nur dieses Wissen hast?","options":["Die Besserung erklärt sich auch ohne Wirkung des Tees: Erkältungen klingen von allein ab, und gekauft wurde der Tee auf dem Höhepunkt der Beschwerden.","Die Besserung erklärt sich durch einen Störfaktor: Er hat in den vier Tagen vermutlich noch ein Hausmittel genommen, das die Beschwerden gelindert hat.","Die Besserung erklärt sich durch umgekehrte Kausalität: Er hat den Tee erst gekauft, als es ihm schon besser ging, und beides nur nachträglich verknüpft.","Die Besserung erklärt sich durch Überlebensverzerrung: Von Misserfolgen mit dem Tee hört man kaum etwas, deshalb gelten Erfolgsgeschichten wie seine als typisch."],"correctIndex":0,"explanation":"Erkältungen sind selbstlimitierend: Das Immunsystem heilt sie meist von allein. Wer sich auf dem Höhepunkt der Beschwerden zu einer Behandlung entschließt, startet an einem Punkt, von dem aus es ohnehin bergauf geht. Dazu kommt die Erwartung, dass das Mittel hilft (Placebo-Effekt). Die zeitliche Abfolge „Mittel genommen, dann besser“ sagt nichts darüber, ob das Mittel die Ursache war (Post-hoc-Fehlschluss). Mit einer Kontrollgruppe ohne Behandlung ließe sich der natürliche Verlauf von einer echten Wirkung trennen. Aus dem Fall folgt weder, dass der Tee wirkt, noch dass er sicher wirkungslos ist. Dass er noch ein weiteres Mittel genommen hat, ist denkbar, steht aber nicht im Fall, und die sparsamste Erklärung braucht es nicht. Dass er den Tee erst nach der Besserung kaufte, widerspricht seiner Schilderung, denn gekauft hat er am schlimmsten Tag. Überlebensverzerrung erklärt, warum man Erfolgsgeschichten häufiger hört, nicht aber, warum es diesem Freund besser ging.","coreRule":"⚡ Besserung nach einem Mittel ist noch keine Wirkung des Mittels.","beleg":"Werkstück C.4.6 (Kernidee; Kontext & Tiefe)","status":"entwurf","scenario":"","quote":"","quoteLabel":"","kurz":"Eine Erkältung klingt meist von allein ab, und wer auf dem Höhepunkt der Beschwerden zu einem Mittel greift, startet dort, wo es ohnehin bergauf geht. Daraus, dass es nach dem Tee besser wurde, folgt noch nicht, dass der Tee es bewirkt hat.","prueffrage":"An welchem Tag kaufte dein Freund den Tee, und wie ging es ihm an diesem Tag im Vergleich zu den Tagen davor?","rueckmeldung":[{"option":1,"text":"Ein zusätzliches Hausmittel ist denkbar und würde die Besserung erklären. Im Bericht steht davon aber nichts, und es braucht es auch nicht: Der natürliche Verlauf reicht, die Annahme wäre eine unbelegte Zutat."},{"option":2,"text":"Umgekehrte Kausalität gibt es, sie passt hier aber nicht. Der Freund kaufte den Tee am schlimmsten Tag, also vor der Besserung, und die Reihenfolge in seiner Schilderung lässt sich nicht einfach umdrehen."},{"option":3,"text":"Dass man vor allem Erfolgsgeschichten hört, ist ein reales Phänomen und erklärt, warum solche Berichte so zahlreich wirken. Warum es gerade diesem Freund besser ging, beantwortet es aber nicht."}],"familie":"was-waere-ohne","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"IQWiG, gesundheitsinformation.de: Erkältung","oeffentlich":true,"url":"https://www.gesundheitsinformation.de/erkaeltung.html","abruf":"2026-10-12"},{"typ":"url","kurz":"Barnett, van der Pols & Dobson 2005, Regression to the mean: what it is and how to deal with it, Int J Epidemiol 34(1) (PubMed-Abstract)","oeffentlich":true,"doi":"10.1093/ije/dyh299","url":"https://pubmed.ncbi.nlm.nih.gov/15333621/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"65beeb7559cf8be5"}},{"id":"qx-c2-014","clusterId":"C","werkstueckRef":"C.4.6","stufe":2,"question":"Welche Erklärung für den Leistungsabfall ist am besten begründet?","scenario":"Eine Tennisspielerin hat die beste Saison ihrer Karriere gespielt und landet deshalb auf dem Titel eines Sportmagazins. In der Folgesaison spielt sie schlechter, bleibt aber weiter eine starke Spielerin. Kollegen sprechen vom „Fluch des Covers“.","options":["Der Medienrummel lenkt Sportlerinnen so ab, dass ihre Leistung danach dauerhaft unter dem früheren Durchschnitt liegt und kaum zurückkehrt.","Profi-Leistungen sind frei von Zufall, weshalb als Ursache nur psychologischer Druck oder Verletzungen in Frage kommen.","Sie kam aufs Cover, weil ihre Leistung gerade außergewöhnlich hoch war; nach einem Extremwert liegt der nächste meist wieder näher am Normalniveau.","Magazine wählen bevorzugt Sportlerinnen, die ihren Karrierehöhepunkt bereits überschritten haben und ohnehin schon nachlassen."],"correctIndex":2,"explanation":"Eine Rekordsaison ist ein Extremwert, und genau deshalb erscheint die Spielerin auf dem Cover. In jedem System, in das Zufall involviert ist, liegt nach einem Extremwert der nächste Wert mit hoher Wahrscheinlichkeit wieder näher am Durchschnitt. Diese Regression zur Mitte erklärt den Abfall ohne zusätzliche Annahmen, denn sie braucht weder einen Fluch noch eine dauerhafte Ablenkung. Die Spielerin kann dabei weiterhin sehr gut sein, nur nicht mehr auf dem außergewöhnlichen Höhepunkt. Das erwartete Muster wäre also: Rückgang, aber weiterhin starkes Niveau. Dasselbe Prinzip erklärt, warum nach dem schlimmsten Tag einer schwankenden Krankheit mit hoher Wahrscheinlichkeit eine Besserung folgt, unabhängig von einer Behandlung.","coreRule":"⚡ Wer wegen einer Rekordleistung auffällt, wird danach meist wieder normaler – ohne Fluch.","beleg":"Werkstück C.4.6 (Anwendung & Relevanz, In der Sport- und Wirtschaftswelt)","status":"freigegeben","freigabe":{"datum":"2026-10-13","pruefsumme":"9ced5798fb44a856","vermerk":"Prüfpult"},"kurz":"Aufs Cover kam sie wegen eines Extremwerts, und nach einem Extremwert liegt der nächste Wert wahrscheinlich näher am Durchschnitt. Ein Fluch ist dafür nicht nötig: Rückgang bei weiter starkem Niveau ist genau das zu Erwartende.","prueffrage":"Wie lagen ihre Ergebnisse in den Jahren vor der Rekordsaison, und wo liegt die Folgesaison im Vergleich dazu?","rueckmeldung":[{"option":0,"text":"Medienrummel kann tatsächlich Kraft kosten, daher wirkt die Erklärung plausibel. Sie behauptet aber einen dauerhaften Abfall unter das frühere Niveau, wofür eine einzige Saison nichts zeigt; die Spielerin bleibt stark."},{"option":1,"text":"Druck und Verletzungen kommen als Ursachen durchaus vor. Falsch ist aber die Voraussetzung: Auch Profi-Leistungen schwanken, etwa durch Tagesform oder knappe Sätze, und diese Schwankung kann den Rückgang ohne weitere Ursache erklären."},{"option":3,"text":"Dass die Auswahl vom Leistungsverlauf abhängt, ist richtig gedacht, aber die Reihenfolge stimmt nicht: Sie kam aufs Cover, weil sie auf dem Höhepunkt stand, nicht weil sie schon nachließ. Die Auswahl erfolgte also nach einem Extremwert."}],"familie":"was-waere-ohne","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Barnett, van der Pols & Dobson 2005, Regression to the mean: what it is and how to deal with it, Int J Epidemiol 34(1) (PubMed-Abstract)","oeffentlich":true,"doi":"10.1093/ije/dyh299","url":"https://pubmed.ncbi.nlm.nih.gov/15333621/","abruf":"2026-10-12"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"9ced5798fb44a856"}},{"id":"qx-c2-015","clusterId":"C","werkstueckRef":"C.4.6","stufe":3,"question":"Bei welcher Art von Erkrankung wäre sein Vorhaben am gefährlichsten?","options":["Bei einer Krankheit, die weder von allein abklingt noch schwankt, etwa Typ-1-Diabetes, weil die Methode dort eine wirksame Therapie ersetzen würde.","Bei einer Krankheit, die ohnehin von allein abklingt, etwa einer Erkältung, weil die Methode dort den Verlauf spürbar verlängern würde.","Bei einer Krankheit mit stark schwankenden Beschwerden, etwa unspezifischen Rückenschmerzen, weil dort Besserung und Verschlechterung kaum zu unterscheiden wären.","Bei einer Krankheit, die länger als eine Woche dauert, etwa einem hartnäckigen Husten, weil die Erwartung dann ihre Wirkung verlöre und jede Linderung ausbliebe."],"correctIndex":0,"explanation":"Eine Methode, die nur von Erwartung, Selbstheilung und Regression zur Mitte lebt, richtet bei Krankheiten, die ohnehin abklingen oder stark schwanken, kaum Schaden an: Die Besserung wäre auch ohne sie gekommen, und der Körper bekommt Zeit zur Heilung. Gefährlich wird es erst dort, wo eine Besserung nicht von allein zu erwarten ist, etwa bei Typ-1-Diabetes, einer schweren bakteriellen Infektion oder den meisten Krebsarten. Dort entsteht der Schaden nicht durch die Methode selbst, sondern dadurch, dass sie eine wirksame Therapie verdrängt und wertvolle Zeit verloren geht. Die Frage „Wäre es auch von allein besser geworden?“ entscheidet also nicht nur darüber, ob du eine Heilungsgeschichte glaubst, sondern auch darüber, wie riskant der Einsatz ist.","coreRule":"⚡ Gefährlich wird eine Scheinwirkung dort, wo die Krankheit nicht von allein besser wird und die Methode die echte Therapie ersetzt.","beleg":"Werkstück C.4.6 (Der Kipppunkt)","status":"entwurf","scenario":"Ein Bekannter schwärmt: „Die sanfte Naturmethode hat mir und meiner Familie schon oft geholfen. Ich nehme sie jetzt einfach bei allem.“ Du weißt: Ihre Wirkung beruht nur auf Erwartung, Selbstheilung und dem Abflachen zufälliger Beschwerdespitzen.","kurz":"Gefährlich wird die Methode dort, wo keine Besserung von allein zu erwarten ist: Sie verdrängt dann eine wirksame Therapie, und wertvolle Zeit geht verloren. Bei Krankheiten, die abklingen oder schwanken, richtet sie kaum Schaden an.","prueffrage":"Was geschieht bei jeder der genannten Krankheiten, wenn sie gar nicht wirksam behandelt wird?","rueckmeldung":[{"option":1,"text":"Dass eine Erkältung von allein abklingt, stimmt. Gerade deshalb verlängert eine wirkungslose Methode den Verlauf nicht spürbar: Die Besserung käme auch so, und der Körper bekommt die Zeit, die er zur Heilung braucht."},{"option":2,"text":"Bei schwankenden Beschwerden lässt sich tatsächlich schwer sagen, ob eine Besserung von der Methode kommt. Gefährlich ist das aber kaum: Die Beschwerdespitzen flachen ohnehin wieder ab, die Besserung käme also auch ohne sie."},{"option":3,"text":"Dass die Erwartung nach einer Woche ihre Wirkung verlöre, ist nicht belegt und erklärt keine Gefahr. Entscheidend ist nicht die Dauer, sondern ob eine Besserung von allein zu erwarten ist und eine wirksame Therapie verdrängt würde."}],"familie":"ergaenzen-oder-ersetzen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Johnson u. a. 2018, Use of Alternative Medicine for Cancer and Its Impact on Survival, J Natl Cancer Inst 110(1) (PubMed-Abstract)","oeffentlich":true,"doi":"10.1093/jnci/djx145","url":"https://pubmed.ncbi.nlm.nih.gov/28922780/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Hanna u. a. 2020, Mortality due to cancer treatment delay: systematic review and meta-analysis, BMJ 371 (PMC7610021)","oeffentlich":true,"doi":"10.1136/bmj.m4087","abruf":"2026-10-12"},{"typ":"url","kurz":"IQWiG, gesundheitsinformation.de: Erkältung","oeffentlich":true,"url":"https://www.gesundheitsinformation.de/erkaeltung.html","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"44e2d0ca7ba60fe4"}},{"id":"qx-c2-016","clusterId":"C","werkstueckRef":"C.4.6","stufe":4,"question":"Welche Prüffrage fehlt, bevor man den Blitzer als Ursache der Besserung ansieht?","scenario":"Eine Gemeinde baut nach dem schlimmsten Unfalljahr ihrer Geschichte an einer Kreuzung einen Blitzer ein; im Jahr darauf passieren dort weniger Unfälle. Der Bürgermeister sieht darin den Beweis, dass der Blitzer wirkt.","options":["Ob die Kosten des Blitzers im Verhältnis zu den Unfallkosten des schlimmsten Jahres vertretbar sind, denn nur dann ist die Maßnahme sinnvoll.","Wie sich vergleichbare Kreuzungen ohne Blitzer entwickelt haben, denn so lässt sich eine Wirkung von der Rückkehr zum Durchschnitt trennen.","Ob die Anwohner der Kreuzung den Blitzer befürworten, denn die Akzeptanz entscheidet darüber, ob die Maßnahme politisch durchsetzbar bleibt.","Ob sich der Rückgang an der Kreuzung auf andere Kreuzungen der Gemeinde übertragen lässt, denn nur dann gilt das Ergebnis über den Einzelfall hinaus."],"correctIndex":1,"explanation":"Ein außergewöhnlich schlechtes Jahr, eine Maßnahme genau danach, anschließend Besserung: Das ist das typische Muster der Regression zur Mitte. Nach einem extremen Ausreißer liegt der nächste Wert mit hoher Wahrscheinlichkeit wieder näher am Durchschnitt, auch ohne jede Maßnahme. Erst der Vergleich mit ähnlichen Kreuzungen, die keinen Blitzer bekommen haben, trennt diesen natürlichen Verlauf von einer echten Wirkung. Der Blitzer kann trotzdem wirken; es fehlt nur der Beleg. Die anderen Fragen sind in anderer Lage durchaus sinnvoll, klären hier aber nicht die Ursache: Kosten und Nutzen entscheiden, ob sich der Blitzer lohnt, nicht, ob er den Rückgang bewirkt hat. Die Zustimmung der Anwohner betrifft die Durchsetzbarkeit, nicht die Unfälle. Und die Übertragbarkeit auf andere Kreuzungen setzt voraus, dass die Wirkung an dieser Kreuzung schon geklärt ist.","coreRule":"⚡ Ohne Vergleichsgruppe bleibt offen, ob die Maßnahme wirkte oder der Zufall zur Normalität zurückkehrte.","beleg":"Werkstück C.4.6 (Kontext & Tiefe: Regression zur Mitte; Red Flags: fehlende Kontrollgruppe; Verbindungen: Kontrollgruppen); Übertragung auf ein Alltagsbeispiel","status":"entwurf","quote":"","quoteLabel":"","kurz":"Nach einem Ausreißerjahr fällt der nächste Wert meist ohnehin Richtung Durchschnitt zurück. Erst der Vergleich mit ähnlichen Kreuzungen ohne Blitzer zeigt, ob mehr als das dahintersteckt. Der Blitzer kann wirken, belegt ist es noch nicht.","prueffrage":"War das schlimmste Unfalljahr an dieser Kreuzung ein Ausreißer, und hätte es danach auch ohne Blitzer besser werden können?","rueckmeldung":[{"option":0,"text":"Kosten und Nutzen sind für die Entscheidung wichtig, ob sich ein Blitzer lohnt. Ob er den Rückgang tatsächlich bewirkt hat, beantwortet diese Rechnung nicht, und auf genau diese Ursachenfrage zielt die Aufgabe."},{"option":2,"text":"Die Haltung der Anwohner entscheidet darüber, ob die Maßnahme politisch tragfähig bleibt. Über die Unfallzahlen und ihre Ursache sagt sie nichts, sie betrifft eine andere Frage als die nach der Wirkung."},{"option":3,"text":"Ob sich ein Ergebnis übertragen lässt, ist eine berechtigte Frage, die sich aber erst später stellt. Sie setzt voraus, dass die Wirkung an dieser Kreuzung schon geklärt ist, und genau das fehlt hier noch."}],"familie":"was-waere-ohne","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Allsop 2010, The Effectiveness of Speed Cameras. A review of evidence. Executive Summary, RAC Foundation","oeffentlich":true,"url":"https://www.racfoundation.org/wp-content/uploads/speed-camera-effectiveness-allsop-exec-summary.pdf","seite":"PDF-S. 7","abruf":"2026-10-12"},{"typ":"url","kurz":"Barnett, van der Pols & Dobson 2005, Regression to the mean: what it is and how to deal with it, Int J Epidemiol 34(1) (PubMed-Abstract)","oeffentlich":true,"doi":"10.1093/ije/dyh299","url":"https://pubmed.ncbi.nlm.nih.gov/15333621/","abruf":"2026-10-12"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"3182f85246059e7d"}},{"id":"qx-c2-017","clusterId":"C","werkstueckRef":"C.4.7","stufe":1,"question":"Du liest die Meldung und willst sie prüfen, bevor du sie weiterleitest: Was ist der entscheidende Denkfehler dieser Schlagzeile?","scenario":"Eine Schlagzeile warnt vor „Dihydrogenmonoxid im Leitungswasser“: Es sei Bestandteil des sauren Regens, könne in gasförmigem Zustand schwere Verbrennungen verursachen, und sein Einatmen sei tödlich. Ein Chemiker erklärt, „Dihydrogenmonoxid“ sei nur ein ungewöhnlicher chemischer Name für H₂O, also für Wasser.","options":["Die Meldung nennt Eigenschaften eines Stoffes, aber weder Dosis noch Kontext; ohne sie sagt „kann tödlich sein“ nichts über die tatsächliche Gefahr.","Die Meldung beschreibt Eigenschaften, die der Stoff gar nicht hat; schon die genannten Tatsachenbehauptungen sind sachlich falsch.","Die Meldung verwendet einen Fachnamen; wer Fachnamen benutzt, will damit immer Angst erzeugen und das Publikum bewusst täuschen.","Die Meldung nennt Gefahren, die in großen Mengen wirklich bestehen; weil die Eigenschaften stimmen, ist die Warnung im Kern berechtigt."],"correctIndex":0,"explanation":"Wasser steckt im sauren Regen, heißer Wasserdampf kann schwere Verbrühungen verursachen, und Wasser in der Lunge führt zum Ertrinken. Die Aussagen sind einzeln richtig, aber ohne Menge und Kontext sagen sie nichts über das Risiko: Bei den allermeisten Stoffen ist eine kleine Dosis harmlos und eine sehr hohe schädlich (Ausnahmen wie erbgutschädigende Stoffe nimmt man ohne sichere Schwelle an), auch bei Wasser. Die Meldung nutzt einen unvertrauten Fachnamen und verschweigt genau die Information, die über Gefahr oder Sicherheit entscheidet. Zu prüfen wäre also: Welche Menge liegt vor, wo liegt die schädliche Schwelle, und wie verhält sich beides zur alltäglichen Belastung?","coreRule":"⚡ Nicht die Substanz allein, sondern die Menge im Kontext entscheidet über die Gefahr.","beleg":"Werkstück C.4.7 (Das tödliche Wasser)","status":"entwurf","kurz":"Die genannten Eigenschaften von Wasser stimmen einzeln, sagen aber ohne Menge und Kontext nichts über das Risiko: Meist ist eine kleine Menge harmlos und eine sehr große schädlich. Der unvertraute Fachname lässt das vergessen.","prueffrage":"Treffen die drei Warnungen auf Wasser zu, und was folgt daraus für das Glas Leitungswasser auf deinem Tisch?","rueckmeldung":[{"option":1,"text":"Bei so ungewöhnlichen Warnungen vermutet man leicht, sie seien erfunden. Doch die Tatsachen stimmen: Wasser steckt im sauren Regen, Dampf kann verbrühen, und eingeatmetes Wasser kann zum Ertrinken führen; es fehlt die Menge, nicht die Wahrheit."},{"option":2,"text":"Der unvertraute Name wirkt hier tatsächlich bedrohlich und verdeckt, worum es geht. Dass Fachnamen immer täuschen sollen, trägt aber nicht: Sie sind üblich und verraten keine Absicht; entscheidend ist, was die Meldung verschweigt."},{"option":3,"text":"Einzeln stimmen die Eigenschaften, und manche werden erst bei großen Mengen gefährlich. Gerade deshalb ist die Warnung ohne Menge und Kontext irreführend: Leitungswasser in alltäglicher Menge ist harmlos."}],"familie":"dosis-entscheidet","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Grandjean, P. (2016): Paracelsus Revisited: The Dose Concept in a Complex World. Basic & Clinical Pharmacology & Toxicology 119(2), 126–132","oeffentlich":true,"doi":"10.1111/bcpt.12622","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4942381/","abruf":"2026-10-12"},{"typ":"url","kurz":"EFSA: Margin of Exposure (Themenseite)","oeffentlich":true,"url":"https://efsa.europa.eu/en/topics/topic/margin-exposure","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"1f72d7f4b5212d19"}},{"id":"qx-c2-018","clusterId":"C","werkstueckRef":"C.4.7","stufe":2,"question":"Welche Frage und welche Vergleichsgrößen entkräften diese Schlagzeile am besten?","scenario":"In einer Chatgruppe kursiert die Meldung „Spuren von Formaldehyd in Impfstoffen gefunden!“ und löst Entsetzen aus. Eine Teilnehmerin schreibt: „Formaldehyd ist ein Gift. Wo Gift drin ist, darf nichts in meinen Körper!“ Du willst sachlich antworten.","options":["Wie viel ist es, und wie verhält sich die Menge zu dem, was Obst enthält und der Körper selbst ständig bildet?","Wer hat die Meldung ursprünglich verbreitet, und lässt sich dazu eine geprüfte Originalquelle finden?","Wurde der Stoff mit einer verlässlichen Methode nachgewiesen, und bestätigt ein unabhängiges Labor das Ergebnis?","Welchen Nutzen hat die Impfung, und wie verhält sich ihr Risiko zu dem der Krankheit, gegen die sie schützt?"],"correctIndex":0,"explanation":"Nicht die bloße Anwesenheit eines Stoffs entscheidet über seine Gefährlichkeit, sondern seine Menge im Verhältnis zu Grenzwert und natürlichen Quellen. Hier ist die Menge klein: Eine Impfdosis enthält höchstens 0,1 Milligramm Formaldehyd. Ein Apfel oder eine Birne enthält insgesamt mehr, und der Körper bildet selbst ständig weitaus höhere, aber völlig harmlose Mengen. Die Frage „Wie viel, verglichen womit?“ macht aus einem Schreckenswort eine prüfbare Größenordnung.","coreRule":"⚡ Frag bei jedem „Gift gefunden“ nach der Menge und dem Vergleichswert.","beleg":"Werkstück C.4.7 (Anwendung & Relevanz, Chemophobie); Fn. gl-c-formaldehyd (Kuhrt u. a. 2021; Packungsbeilage INFANRIX; Centre for Food Safety Hongkong)","status":"entwurf","kurz":"Entscheidend ist nicht, dass ein Stoff vorkommt, sondern wie viel davon und im Vergleich zu was. Der Denkfehler: „Gift“ als Eigenschaft eines Stoffs zu behandeln, statt die Menge zu prüfen, die hier kleiner ist als in einem Apfel.","prueffrage":"Was genau steht in der Meldung, und was müsstest du zusätzlich wissen, um ihre Bedeutung einschätzen zu können?","rueckmeldung":[{"option":1,"text":"Eine Quellenprüfung gehört dazu und ist an sich vernünftig. Sie klärt aber nur, woher die Meldung stammt. Selbst eine saubere Originalquelle würde nicht zeigen, ob die genannte Spur überhaupt etwas bedeutet."},{"option":2,"text":"Ein verlässlicher Nachweis ist sinnvoll, hilft hier aber wenig: Spuren sind tatsächlich enthalten, ein bestätigter Befund stützt die Schlagzeile also eher. Offen bleibt, ob die Menge etwas bedeutet, und darauf kommt es an."},{"option":3,"text":"Nutzen und Risiko gegeneinander abzuwägen gehört zur sorgfältigen Prüfung, ist aber eine größere Frage. Ob die gefundene Spur Formaldehyd etwas bedeutet, klärt sich dadurch nicht; die Schlagzeile bleibt unbeantwortet."}],"familie":"dosis-entscheidet","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"U.S. FDA: Common Ingredients in FDA-Approved Vaccines","oeffentlich":true,"url":"https://www.fda.gov/vaccines-blood-biologics/safety-availability-biologics/common-ingredients-fda-approved-vaccines","abruf":"2026-10-12"},{"typ":"url","kurz":"Centre for Food Safety Hongkong: Foods Known to Contain Naturally Occurring Formaldehyde","oeffentlich":true,"url":"https://www.cfs.gov.hk/english/whatsnew/whatsnew_fa/files/formaldehyde.pdf","abruf":"2026-10-12"},{"typ":"literatur","kurz":"GlaxoSmithKline: Packungsbeilage INFANRIX („≤100 mcg of residual formaldehyde“ je 0,5-ml-Dosis), nach Landkarte Fn. gl-c-formaldehyd","oeffentlich":false}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"7b89a65ce04f0f9d"}},{"id":"qx-c2-019","clusterId":"C","werkstueckRef":"C.4.7","stufe":3,"question":"Welche Einordnung sollte die Redaktion veröffentlichen?","options":["Die Leserin hat recht: Ohne sichere Schwelle ist auch die Spur im Brot so riskant wie eine große Dosis, also gilt Nulltoleranz, und der Faktor 20.000 spielt für die Bewertung keine Rolle.","Beide irren: Ohne sichere Schwelle sinkt das Risiko der Spur im Brot mit der Dosis, ohne ganz zu verschwinden; der Faktor 20.000 zählt, und man senkt den Stoff so weit wie vernünftig möglich.","Der Kollege hat recht: Die Spur im Brot liegt sicher unter jeder Schwelle, also ist sie harmlos, und weil der Faktor 20.000 so groß ist, muss man den Stoff im Brot nicht weiter senken.","Beide irren: Ohne sichere Schwelle hängt das Risiko der Spur im Brot gar nicht von der Dosis ab, also sagt der Faktor 20.000 nichts aus, und man muss vor jeder Bewertung auf deutlich mehr Daten warten."],"correctIndex":1,"explanation":"Beide Aussagen machen aus einem Kontinuum eine Ja-Nein-Frage. Für erbgutschädigende Stoffe und ionisierende Strahlung nimmt man vorsorglich keine sichere Schwelle an: Das Risiko sinkt nach dieser Annahme mit der Dosis, verschwindet aber nicht ganz. „Keine Schwelle“ heißt also weder „jede Menge gleich gefährlich“ noch „Dosis egal“. Behörden bewerten deshalb den Abstand zwischen der tatsächlichen Belastung und der Dosis, die im Tierversuch Tumoren auslöst, und senken solche Stoffe so weit, wie es vernünftigerweise möglich ist (ALARA-Prinzip); für das Brot heißt das: Der Faktor 20.000 geht in die Bewertung ein, und trotzdem wird der Stoff so weit wie vernünftig gesenkt. Auch hier hängt das Risiko von der Dosis ab. Die Leserin liest „keine Schwelle“ als „alles gleich schlimm“ und übergeht damit den Abstand. Der Kollege unterstellt eine sichere Schwelle, die gerade nicht angenommen wird, und verzichtet deshalb zu Unrecht aufs Senken. Wer meint, ohne Schwelle hänge das Risiko gar nicht von der Dosis ab, übersieht, dass es auch hier mit der Dosis steigt und der Abstand deshalb aussagekräftig ist.","coreRule":"⚡ Auch ohne sichere Schwelle gilt: Das Risiko wächst mit der Dosis – Null gibt es nicht, aber auch nicht „alles gleich schlimm“.","beleg":"Werkstück C.4.7 (Kontext & Tiefe, „Die Kurve ist entscheidend“); Fn. gl-c-schwelle (Mußhoff u. a. 2015, S. 602–603; Schrenk 2011, S. 317)","status":"entwurf","scenario":"Eine Redaktion berichtet: In einem Brot wurden Spuren eines Stoffes gefunden, der das Erbgut schädigen kann; für solche Stoffe nehmen Behörden vorsorglich keine sichere Schwelle an, unterhalb derer das Risiko null wäre. Die gemessene Belastung liegt etwa um den Faktor 20.000 unter der Dosis, die im Tierversuch Tumoren auslöste. Eine Leserin schreibt: „Keine sichere Menge heißt: Jede Spur ist so gefährlich wie eine große Dosis, das Brot muss weg.“ Ein Kollege hält dagegen: „So winzige Spuren sind einfach harmlos, auf die genaue Menge kommt es nicht an.“","kurz":"Ohne angenommene Schwelle sinkt das Risiko mit der Dosis, verschwindet aber nicht ganz. Deshalb zählt der Abstand von 20.000, und der Stoff wird trotzdem so weit wie vernünftig gesenkt. Beide machen aus einem Kontinuum ein Ja-Nein.","prueffrage":"Was lässt sich über das Risiko zweier unterschiedlich großer Mengen sagen, wenn man nirgends eine Grenze zum Nullrisiko ansetzt?","rueckmeldung":[{"option":0,"text":"Dass auch eine Spur nicht auf null Risiko gerechnet wird, stimmt. Daraus folgt aber nicht, dass sie so gefährlich ist wie eine große Dosis: Das Risiko sinkt mit der Dosis, und der Faktor 20.000 geht in die Bewertung ein."},{"option":2,"text":"Der große Abstand ist tatsächlich ein wichtiges Argument für eine geringe Belastung. Er beweist aber keine Harmlosigkeit, denn für solche Stoffe wird gerade keine sichere Schwelle angenommen, und das Senken bleibt sinnvoll."},{"option":3,"text":"Dass es keine Dosis mit garantiertem Nullrisiko gibt, stimmt. Daraus folgt aber nicht, dass die Dosis egal wäre: Das Risiko steigt mit ihr, deshalb sagt der Abstand von 20.000 durchaus etwas aus, und man muss nicht auf mehr Daten warten."}],"familie":"dosis-entscheidet","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"EFSA: Margin of Exposure (Themenseite)","oeffentlich":true,"url":"https://efsa.europa.eu/en/topics/topic/margin-exposure","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Schrenk, D. (2011): Lebensmittel – Nahrungsergänzungsmittel – Arzneimittel. Toxikologische Bewertung und Abgrenzung. Pharmazie in unserer Zeit 40(4), 316–324 (doi 10.1002/pauz.201100426)","oeffentlich":false},{"typ":"literatur","kurz":"Mäntele, W. (2021): Elektrosmog und Ökoboom. Springer, Kap. „Gibt es einen Schwellwert für die Dosis?“","oeffentlich":false}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"a4f21a91be2ab93f"}},{"id":"qx-c2-020","clusterId":"C","werkstueckRef":"C.4.8","stufe":1,"question":"Ein Gesprächspartner sagt: „Der Zweite Hauptsatz der Thermodynamik verbietet es grundsätzlich, dass ein Lebewesen unbegrenzt lange lebt. Entropie nimmt immer zu, also muss jeder Organismus irgendwann zerfallen.“ Was ist an diesem Schluss am ehesten fehlerhaft?","options":["Er übersieht, dass ein Organismus ein offenes System ist: Energie fließt zu, Entropie wird abgegeben, und so kann seine Ordnung lokal bestehen bleiben.","Er verallgemeinert voreilig: Aus der Alterung der Lebewesen, die er kennt, schließt er auf alle Organismen, obwohl er nur wenige Arten betrachtet hat.","Er argumentiert im Kreis: Den Zerfall jedes Organismus setzt er schon voraus und leitet ihn dann scheinbar aus dem Zweiten Hauptsatz ab.","Er beruft sich auf Autorität: Weil der Zweite Hauptsatz in der Physik unbestritten gilt, hält er seine Aussage über Lebewesen für gesichert."],"correctIndex":0,"explanation":"Kein System setzt den Zweiten Hauptsatz außer Kraft. Er verbietet einem offenen System aber nicht, seine Ordnung beliebig lange zu halten, solange Energie nachfließt und Entropie nach außen abgegeben wird. Ein Lebewesen ist ein solches offenes System im Stoff- und Energiefluss: Es ist eine lokale Senke niedriger Entropie und hält diese Ordnung nur durch fortwährende Energiezufuhr und die Abgabe von Entropie nach außen aufrecht. Jede Reparatur kostet Energie, aber ein Verbot unbegrenzter Lebensdauer folgt daraus nicht. Dass Körper nicht unbegrenzt in Wartung investieren, ist eine Frage der evolutionär eingestellten Energieverteilung (Fortpflanzung statt Instandhaltung), keine physikalische Notwendigkeit. Schon der Evolutionsbiologe George C. Williams wies 1957 den Vergleich des Organismus mit einer verschleißenden Maschine zurück. Die Gegenthese, der Tod sei physikalisch unvermeidlich, wird vertreten, bleibt aber umstritten, denn bei manchen Arten steigt das Sterberisiko mit dem Alter kaum oder gar nicht. Der Fehlschluss besteht darin, aus dem Hauptsatz ein Verbot abzuleiten, das er für ein offenes System gar nicht ausspricht. Die anderen Denkfehler gibt es durchaus, der Gesprächspartner begeht sie hier aber nicht: Er verallgemeinert nicht aus wenigen Beobachtungen, sondern beruft sich auf ein allgemeines Gesetz. Sein Schluss ist auch kein Kreis, denn Entropiezunahme und Zerfall des Organismus sind verschiedene Aussagen. Und das Gesetz selbst ist unbestritten, ein bloßer Autoritätsfehler liegt also nicht vor; falsch ist, was er daraus für Lebewesen ableitet.","coreRule":"⚡ Ein Gesetz über abgeschlossene Systeme beweist nichts über offene. Reparatur kostet Energie, verboten ist sie nicht.","beleg":"Werkstück C.4.8 (Kontext & Tiefe, Hierarchie der Grenzen); Fn. gl-c-williams (Williams 1957, S. 398 und 401–402)","status":"entwurf","scenario":"","quote":"","quoteLabel":"","kurz":"Der Zweite Hauptsatz gilt, verbietet einem offenen System aber nicht, seine Ordnung zu halten, solange Energie zufließt und Entropie nach außen abgegeben wird. Der Fehler ist, aus dem Gesetz ein Verbot abzuleiten, das es für Lebewesen gar nicht ausspricht.","prueffrage":"Bleibt ein Kühlschrank innen dauerhaft kalt, obwohl Wärme von selbst immer vom Warmen zum Kalten fließt, und was braucht er dafür?","rueckmeldung":[{"option":1,"text":"Hier wird nicht von einzelnen Beobachtungen auf alle Arten geschlossen, sondern ein allgemeines Gesetz herangezogen. Der Fehler liegt darin, was aus diesem Gesetz für Lebewesen gefolgert wird, nicht in einer zu schmalen Beobachtungsbasis."},{"option":2,"text":"Ein Kreis läge vor, wenn der Zerfall schon in der Voraussetzung steckte. Entropiezunahme und Zerfall sind aber zwei verschiedene Aussagen. Der Schluss trägt nicht, weil er aus dem Gesetz mehr herausliest, als es für ein offenes System sagt."},{"option":3,"text":"Dass der Zweite Hauptsatz unbestritten gilt, stimmt. Das Argument beruft sich aber nicht auf eine Person oder Instanz, sondern auf ein Naturgesetz. Falsch ist, was daraus für Lebewesen abgeleitet wird, denn dieses Gesetz verbietet einem offenen System keine dauerhafte Ordnung."}],"familie":"bilanz-pruefen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Schaible, R. u. a. (2015): Constant mortality and fertility over age in Hydra. PNAS 112(51), 15701–15706","oeffentlich":true,"doi":"10.1073/pnas.1521002112","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4697432/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Jones, O. R. u. a. (2014): Diversity of ageing across the tree of life. Nature 505(7482), 169–173","oeffentlich":true,"doi":"10.1038/nature12789","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4157354/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Williams, G. C. (1957): Pleiotropy, natural selection, and the evolution of senescence. Evolution 11(4), 398–411 (doi 10.1111/j.1558-5646.1957.tb02911.x)","oeffentlich":false}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"5061cdf3d38540b4"}},{"id":"qx-c2-021","clusterId":"C","werkstueckRef":"C.4.8","stufe":2,"question":"Wie sollte die Werbung vor dem Hintergrund der Studienlage beurteilt werden?","scenario":"Ein Online-Shop verspricht: „Antioxidantien-Kapseln stoppen den Rost des Alterns und verlängern dein Leben.“ Zur Prüfung liegt dir eine Übersichtsarbeit vor, die 78 Studien mit insgesamt 296.707 Teilnehmenden ausgewertet hat, Gesunde ebenso wie Kranke.","options":["Die Behauptung ist nicht prüfbar: „Rost des Alterns“ ist nur ein Bild, und solange der Begriff unscharf bleibt, kann auch die Übersichtsarbeit nichts darüber sagen.","Die Behauptung ist gut begründet, denn freie Radikale schädigen Zellen nachweislich, und Antioxidantien fangen sie ab, sodass der Mechanismus die Aussage trägt.","Die Behauptung ist nicht belegt: In der Übersichtsarbeit zeigt sich keine geringere Sterblichkeit, bei Beta-Carotin und Vitamin E sogar Hinweise auf eine höhere.","Die Behauptung ist schon deshalb zu verwerfen, weil der Shop an den Kapseln verdient; wer ein Interesse am Verkauf hat, dessen Aussage kann nicht stimmen."],"correctIndex":2,"explanation":"Die plausible Idee „Altern ist molekularer Rost, also hilft ein Rostschutz“ ist kein Beleg. Ob Kapseln die Sterblichkeit tatsächlich senken, entscheidet sich an Studien mit vielen Teilnehmenden, und die liegen vor: Die Cochrane-Übersicht von Bjelakovic u. a. (2012) wertete 78 Studien mit 296.707 Teilnehmenden aus. Antioxidantien als Nahrungsergänzung senkten die Sterblichkeit nicht, Beta-Carotin und Vitamin E scheinen sie sogar zu erhöhen. Dass freie Radikale Schäden verursachen, ist zudem nur ein Teil des Bildes: Es gibt viele weitere Schadensquellen, und ein einzelner Wirkstoff kann nicht alle abdecken. Wer ein Ein-Wirkstoff-Versprechen prüft, fragt deshalb nicht, ob der Mechanismus einleuchtet, sondern ob die Wirkung am Menschen belegt ist. Die anderen Gedanken klingen vernünftig, passen aber nicht: Die Behauptung ist durchaus prüfbar, denn die Studien haben die Sterblichkeit gemessen. Ein einleuchtender Mechanismus ersetzt diese Messung nicht. Und ein Verkaufsinteresse des Shops ist ein Grund zur Vorsicht, widerlegt die Aussage aber nicht.","coreRule":"⚡ Ein einleuchtender Mechanismus ersetzt keinen Beleg: Wer „Rostschutz“ verspricht, muss zeigen, dass Kapseln die Sterblichkeit senken – große Studien zeigen das bisher nicht.","beleg":"Werkstück C.4.8 (Ebene 2: Die Chemie; Red Flags); Fn. gl-c-antioxidantien (Bjelakovic u. a. 2012, Cochrane CD007176)","status":"entwurf","kurz":"Ob Kapseln die Sterblichkeit senken, zeigt sich an Studien, nicht daran, dass ein „Rostschutz“ einleuchtet. Die 78 ausgewerteten Studien zeigen keine geringere Sterblichkeit, bei Beta-Carotin und Vitamin E sogar Hinweise auf eine höhere.","prueffrage":"Woran könntest du erkennen, ob die Kapseln bei Menschen tatsächlich etwas bewirken, und nicht nur im Reagenzglas oder in der Theorie?","rueckmeldung":[{"option":0,"text":"Das Bild vom „Rost“ ist tatsächlich unscharf. Das Versprechen, das Leben zu verlängern, lässt sich aber messen, und genau das haben die Studien mit der Sterblichkeit getan. Die Aussage ist also prüfbar."},{"option":1,"text":"Freie Radikale können Zellen schädigen, und das lässt den Mechanismus einleuchtend wirken. Eine Wirkung am Menschen belegt das aber nicht, und es gibt viele weitere Schadensquellen, die ein einzelner Wirkstoff nicht abdeckt."},{"option":3,"text":"Ein Verkaufsinteresse ist ein berechtigter Grund zur Vorsicht. Ob die Aussage stimmt, entscheidet sich aber an den Daten und nicht an den Motiven des Absenders; auch wer verdient, kann recht haben."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Bjelakovic, G. u. a. (2012): Antioxidant supplements for prevention of mortality in healthy participants and patients with various diseases. Cochrane Database of Systematic Reviews (3), CD007176","oeffentlich":true,"doi":"10.1002/14651858.CD007176.pub2","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8407395/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"a0c9746bbbf9c3b9"}},{"id":"qx-c2-022","clusterId":"C","werkstueckRef":"C.4.8","stufe":3,"question":"Welche Einschätzung der Aussage ist am besten begründet?","options":["Die Aussage ist plausibel, aber nicht belegt: Der Mausbefund stützt den Zielkonflikt nicht, und beim Menschen fehlt bisher ein gesichertes Beispiel für ein solches Gen.","Die Aussage ist wahrscheinlich zutreffend: Weil bei Fadenwürmern, Fliegen und Mäusen mehrere Gene solche Zielkonflikte zeigen, darf man das auf p53 beim Menschen übertragen.","Die Aussage ist wohl widerlegt: Weil zusätzliche, normal gesteuerte p53-Kopien das Altern nicht beschleunigen, kann p53 im Alter keinen Schaden anrichten, und die Hypothese fällt.","Die Aussage ist vorläufig tragfähig: Die Biologin kennt p53 aus der Forschung, und ihre Fachkenntnis genügt als Grundlage, solange niemand mit Belegen widerspricht."],"correctIndex":0,"explanation":"Die Hypothese ist plausibel: Ein Gen, das in der Jugend krebsverdächtige Zellen rigoros entfernt, könnte im Alter auch nützliche Stammzellen opfern. Plausibel ist aber nicht bewiesen. Bei „Super-p53“-Mäusen mit zusätzlichen, normal gesteuerten p53-Kopien trat der Krebsschutz ohne beschleunigtes Altern auf; mehr Schutz durch p53 kostet also nicht zwangsläufig schnelleres Altern, und der behauptete Zielkonflikt wird dadurch nicht gestützt. Für den Menschen gibt es bislang keinen überzeugenden Fall, in dem das verantwortliche Gen identifiziert wäre. Ein stimmiges Erklärungsbild ersetzt keine Evidenz, und Befunde aus einer Art lassen sich nicht ungeprüft auf eine andere übertragen.","coreRule":"⚡ Ein schönes Erklärungsbild ist noch kein Befund: Prüfe, ob Experimente es tatsächlich stützen und ob sie für die Art gelten, über die du sprichst.","beleg":"Werkstück C.4.8 (Das Adaptive Talent; Anwendung & Relevanz); Fn. gl-c-p53 (García-Cao u. a. 2002, EMBO J 21 (22), S. 6225–6235); Fn. gl-c-austad (Austad/Hoffman 2018, S. 289)","status":"entwurf","scenario":"Eine Biologin sagt: „p53 ist das klassische Beispiel für antagonistische Pleiotropie: In der Jugend schützt das Gen vor Krebs, im Alter treibt es den Zerfall voran.“ Du kennst zwei Befunde: Mäuse mit zusätzlichen, normal gesteuerten p53-Kopien waren besser vor Krebs geschützt und alterten trotzdem normal. Bei Fadenwürmern, Fliegen und Mäusen sind mehrere Gene mit solchen Zielkonflikten beschrieben, beim Menschen ist bislang kein Gen dieser Art zweifelsfrei identifiziert.","kurz":"Die Hypothese klingt stimmig, ist aber nicht belegt: Der Mausbefund stützt den Zielkonflikt nicht, und beim Menschen fehlt ein gesichertes Beispiel. Ein plausibles Erklärungsbild ersetzt keine Evidenz.","prueffrage":"Was geschah bei den Mäusen mit zusätzlichen p53-Kopien mit der Krebsrate und mit der Alterung?","rueckmeldung":[{"option":1,"text":"Dass bei Würmern, Fliegen und Mäusen mehrere Gene solche Zielkonflikte zeigen, macht die Hypothese denkbar. Für p53 und den Menschen belegt es aber nichts, denn Befunde zu anderen Genen und Arten lassen sich nicht ungeprüft übertragen."},{"option":2,"text":"Daran stimmt: Mehr normal gesteuertes p53 beschleunigte das Altern nicht, der Zielkonflikt bleibt also ungestützt. Widerlegt ist die Hypothese damit nicht, denn dort war p53 nur vermehrt, nicht verändert."},{"option":3,"text":"Fachkenntnis spricht dafür, dass die Biologin ernst zu nehmen ist. Sie ersetzt aber keine Belege, und Belege müssen nicht erst durch Widerspruch anderer eingefordert werden: Wer eine Behauptung aufstellt, muss sie stützen."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"García-Cao, I. u. a. (2002): „Super p53“ mice exhibit enhanced DNA damage response, are tumor resistant and age normally. EMBO Journal 21(22), 6225–6235","oeffentlich":true,"doi":"10.1093/emboj/cdf595","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC137187/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Austad, S. N.; Hoffman, J. M. (2018): Is antagonistic pleiotropy ubiquitous in aging biology? Evolution, Medicine, and Public Health 2018(1), 287–294","oeffentlich":true,"doi":"10.1093/emph/eoy033","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"769dfabcb5c2e9e6"}},{"id":"qx-c2-023","clusterId":"C","werkstueckRef":"C.4.9","stufe":1,"question":"Welche Erklärung passt am besten zu diesem Muster?","options":["Wo Tiere ohnehin früh sterben, lohnt sich Körperwartung kaum; Art A investiert eher in Fortpflanzung und altert deshalb auch im Labor früher als Art B.","Kleinere Tiere altern schneller, weil die Lebensdauer mit der Körpergröße zunimmt; Art A ist die kleinere und altert deshalb im Labor früher als Art B.","Wo der Stoffwechsel schneller läuft, wird die begrenzte Lebensenergie früher verbraucht; Art A hat den schnelleren und altert deshalb im Labor früher als Art B.","Wo Fressfeinde drohen, belastet Dauerstress den Körper; Art A altert deshalb im Labor früher als Art B, weil dieser Stress ihre Zellen vorzeitig verschleißt."],"correctIndex":0,"explanation":"Die Evolution investiert nur so viel in Reparatur und Wartung des Körpers („Soma“), wie nötig ist, um ihn bis zur erfolgreichen Fortpflanzung am Leben zu erhalten (Disposable-Soma-Theorie). Stirbt eine Art in der Natur meist früh, bringt aufwendige Wartung für spätere Jahre kaum zusätzlichen Nachwuchs; die Ressourcen gehen besser in Fortpflanzung. Übertragen auf die Beobachtung heißt das: Art A altert auch im geschützten Labor früher, weil Selektion ihre Ausstattung auf die kurze Lebenserwartung in der Natur eingestellt hat (eine Übertragung der Theorie, kein direkter Befund).","coreRule":"⚡ Wartung lohnt sich nur so weit, wie ein Körper realistisch lebt, um seine Gene weiterzugeben.","beleg":"Werkstück C.4.9 (Ebene 1: Die Biologie, Disposable Soma Theory; Anwendung auf Fressfeinde und Laborbedingungen ist Transfer, nicht im Buchtext belegt)","status":"entwurf","scenario":"Eine Forscherin vergleicht zwei ähnlich große Tierarten: Art A hat viele Fressfeinde und stirbt in der Natur meist schon im ersten Lebensjahr, Art B hat kaum Feinde und lebt oft viele Jahre. Im Labor, wo keine Fressfeinde drohen, zeigt Art A nach kurzer Zeit deutliche Alterserscheinungen, Art B erst viel später.","kurz":"Wo Tiere in der Natur meist früh sterben, lohnt sich Körperwartung für spätere Jahre kaum, und Art A hat ihre Ausstattung offenbar darauf eingestellt. Der naheliegende Fehler: Im Labor fehlen die Feinde, doch das Altern folgt der Anpassung an früher, nicht dem heutigen Umfeld.","prueffrage":"Worin unterscheiden sich die beiden Arten in der Natur, und bleibt dieser Unterschied im Labor sichtbar, obwohl dort keine Fressfeinde drohen?","rueckmeldung":[{"option":1,"text":"Dass kleinere Tiere im Schnitt kürzer leben, trifft als grobe Regel über viele Arten hinweg zu. Hier sind beide Arten aber ähnlich groß, die Größe kann den Unterschied also nicht erklären."},{"option":2,"text":"Ein schnellerer Stoffwechsel, der die Lebensenergie früher aufbraucht, ist ein bekanntes, aber umstrittenes Erklärungsmuster. Von unterschiedlichem Stoffwechsel ist im Szenario keine Rede, die Annahme wird einfach hinzugefügt."},{"option":3,"text":"Dauerstress durch Fressfeinde kann den Körper belasten, das ist plausibel. Im Labor drohen aber keine Fressfeinde, und von Nachwirkungen früheren Stresses steht nichts da. So erklärt er das frühe Altern gerade dort nicht."}],"familie":"auslese-statt-plan","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Austad, S. N.; Hoffman, J. M. (2018): Is antagonistic pleiotropy ubiquitous in aging biology? Evolution, Medicine, and Public Health 2018(1), 287–294","oeffentlich":true,"doi":"10.1093/emph/eoy033","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Williams, G. C. (1957): Pleiotropy, natural selection, and the evolution of senescence. Evolution 11(4), 398–411 (doi 10.1111/j.1558-5646.1957.tb02911.x)","oeffentlich":false}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"94479528ab19b0c4"}},{"id":"qx-c2-024","clusterId":"C","werkstueckRef":"C.4.9","stufe":2,"question":"Welche Erklärung für die niedrige Krebsrate bei Kindern ist am besten begründet?","options":["Krebs ist eine Alterskrankheit, und die wenigen Lebensjahre von Kindern genügen als Erklärung: Mehr als „jung“ muss man zur niedrigen Rate nicht wissen.","Ein Schutzmechanismus erkennt und beseitigt beschädigte Zellen bei Kindern früh, und in ihren jungen Zellen haben sich erst wenige Mutationen angesammelt.","Die Rate ist gar nicht niedriger, nur gibt es weniger Kinder als Erwachsene und deshalb auch weniger Krebsfälle bei Kindern (Basisrate).","Bei Kindern wird Krebs seltener erkannt, weil sie seltener zur Vorsorge gehen, sodass die niedrige Rate vor allem ein Messartefakt ist."],"correctIndex":1,"explanation":"„Jung“ ist hier keine Erklärung, sondern ein Sammelbegriff für zwei Mechanismen. Ein Wächtergen wie p53 erkennt Zellen mit beschädigter DNA und kann ihren programmierten Zelltod (Apoptose) auslösen, bevor sie zu Krebszellen werden; dieser Schutz wirkt von Anfang an. Den Unterschied zwischen Kindern und Älteren macht vor allem die Zahl der Mutationen: Junge Zellen haben erst wenige angesammelt, und mit den Jahren können auch Schutzgene wie p53 selbst getroffen werden. Wer eine Alltagserklärung wie „weil jung“ prüft, fragt also: Welche Mechanismen stecken dahinter, und trägt jeder einzelne? Die anderen Gedanken klingen sinnvoll, passen hier aber nicht: „Alterskrankheit“ und „jung“ benennen die Beobachtung, erklären sie aber nicht. Gefragt ist die Rate, und die bleibt von der Zahl der Kinder unberührt. Für ein Messartefakt spricht nichts, denn schwere Symptome bei Kindern werden in der Regel ärztlich abgeklärt.","coreRule":"⚡ Prüfe Sammelbegriffe wie „weil jung“: Zerlege sie in die Mechanismen, die tatsächlich wirken. Hier schützt der Wächter p53, und es gibt noch wenig Fehler, die sich angehäuft haben.","beleg":"Werkstück C.4.9 (Der Wächter kehrt zurück, zweiter Absatz); Verweis auf C.4.4","status":"entwurf","scenario":"Eine Kollegin sagt: „Krebs ist eine Alterskrankheit, bei Kindern kommt er kaum vor. Das liegt doch nur daran, dass Kinder jung sind, mehr steckt nicht dahinter.“ Du willst wissen, was dieses „jung“ konkret bedeutet.","kurz":"„Jung“ benennt die Beobachtung, erklärt sie aber nicht. Dahinter stehen zwei Mechanismen: Ein Wächtergen wie p53 kann beschädigte Zellen beseitigen, und junge Zellen haben erst wenige Mutationen angesammelt. Prüfe bei „weil jung“, welche Mechanismen tragen.","prueffrage":"Was genau unterscheidet eine junge Zelle von einer alten, und lässt sich jeder dieser Unterschiede einzeln benennen?","rueckmeldung":[{"option":0,"text":"Dass Alter eine Rolle spielt, stimmt, und „jung“ klingt nach einer vollständigen Antwort. Es beschreibt aber nur, was zu beobachten ist, nicht warum. Erst die Mechanismen dahinter erklären die niedrige Rate."},{"option":2,"text":"Mehr Erwachsene bedeuten tatsächlich mehr Fälle in absoluten Zahlen. Gefragt ist aber die Rate, also der Anteil, und der hängt nicht davon ab, wie viele Kinder es gibt. Die Rate bei Kindern ist wirklich niedriger."},{"option":3,"text":"Ein Messfehler wäre eine denkbare Erklärung, doch es gibt keinen Grund dafür: Schwere Symptome bei Kindern werden in der Regel ärztlich abgeklärt. Die niedrige Rate liegt also nicht an übersehenen Fällen."}],"familie":"genau-unterscheiden","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Zhang, H. u. a. (2024): Unraveling the Guardian: p53’s Multifaceted Role in the DNA Damage Response and Tumor Treatment Strategies. International Journal of Molecular Sciences 25(23), 12928","oeffentlich":true,"doi":"10.3390/ijms252312928","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC11641486/","abruf":"2026-10-12"},{"typ":"url","kurz":"National Cancer Institute: The Genetics of Cancer","oeffentlich":true,"url":"https://www.cancer.gov/about-cancer/causes-prevention/genetics","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"e5c23574640cc36d"}},{"id":"qx-c2-025","clusterId":"C","werkstueckRef":"C.4.9","stufe":3,"question":"Eine Forscherin behauptet: „Freie Radikale rosten uns zu Tode – oxidativer Schaden ist die Ursache des Alterns.“ Welche Beobachtung spricht am stärksten gegen diese Behauptung?","options":["Bei Mäusen beschleunigten zusätzliche oxidative Schäden das Altern nicht, und der Nacktmull wird trotz hoher oxidativer Schäden außergewöhnlich alt.","Im Gewebe älterer Tiere findet man deutlich mehr oxidativ geschädigte Eiweiße, Fette und DNA-Abschnitte als im Gewebe junger Tiere.","Freie Radikale entstehen ständig als Nebenprodukt der Zellatmung in den Mitochondrien und lassen sich in jeder atmenden Zelle nachweisen.","Raucher sind einem erhöhten oxidativen Stress ausgesetzt und haben im Durchschnitt eine kürzere Lebenserwartung als Nichtraucher."],"correctIndex":0,"explanation":"Wenn oxidativer Schaden die Ursache des Alterns wäre, müsste jeder Eingriff, der ihn verändert, auch die Lebensdauer verändern. Genau das tritt nicht ein: Mehr oxidativer Schaden beschleunigte das Altern von Mäusen nicht, und eine Art mit hohen oxidativen Schäden wird dennoch außergewöhnlich alt. Auch Veränderungen der Schutzenzyme änderten die Lebensdauer von Mäusen in einer großen Versuchsreihe nur in einem von 18 Fällen. Weil dieselben Moleküle auch als Signalstoffe wirken, gilt oxidativer Schaden heute als ein Baustein des Alterns unter vielen, nicht als seine Ursache. Wer eine Theorie prüft, fragt also: Was müsste gelten, wenn sie stimmt – und tritt es ein?","coreRule":"⚡ Prüfe eine Ursachenbehauptung mit der Gegenprobe: Ändert sich das Ergebnis, wenn du die vermutete Ursache veränderst? Oxidativer Schaden ist ein Baustein des Alterns, nicht seine alleinige Ursache.","beleg":"Werkstück C.4.9 (Ebene 2: Oxidativer Stress); Fn. gl-c-radikale (Pérez u. a. 2009: nur 1 von 18 Veränderungen der Schutzenzyme änderte die Lebensdauer; López-Otín u. a. 2013: mehr oxidative Schäden beschleunigen das Altern nicht; Gladyshev 2014; zum Nacktmull Verweis auf Andziak u. a. 2006, Werkstück C.4.11)","status":"entwurf","scenario":"Die Theorie der freien Radikale galt lange als wichtigste Erklärung des Alterns. Du prüfst, ob sie sich halten lässt.","kurz":"Wäre oxidativer Schaden die Ursache des Alterns, müsste mehr davon das Leben verkürzen. Das trat bei Mäusen nicht ein, und der Nacktmull wird trotz hoher Schäden sehr alt. Dass Schäden im Alter zunehmen, zeigt nur, dass sie auftreten.","prueffrage":"In welchen Versuchen wurde der oxidative Schaden gezielt verändert, und wie alt wurden die Tiere danach?","rueckmeldung":[{"option":1,"text":"Dass im Alter mehr oxidativ geschädigte Moleküle vorliegen, stimmt. Es zeigt aber nur, dass diese Schäden auftreten, nicht dass sie das Altern verursachen. Mit der Behauptung ist das vereinbar und spricht deshalb nicht gegen sie."},{"option":2,"text":"Die Entstehung freier Radikale in den Mitochondrien ist unstrittig. Sie sagt aber nur, woher die Radikale kommen, und prüft nicht, ob ihr Schaden das Altern verursacht. Für oder gegen die Ursachenbehauptung folgt daraus nichts."},{"option":3,"text":"Raucher haben mehr oxidativen Stress und leben im Schnitt kürzer, das stimmt. Das passt eher zur Behauptung als gegen sie. Rauchen schädigt den Körper jedoch auf viele andere Arten, sodass der Befund die Ursache nicht eindeutig trifft."}],"familie":"korrelation-und-ursache","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Pérez, V. I. u. a. (2009): Is the oxidative stress theory of aging dead? Biochimica et Biophysica Acta 1790(10), 1005–1014","oeffentlich":true,"doi":"10.1016/j.bbagen.2009.06.003","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC2789432/","abruf":"2026-10-12"},{"typ":"doi","kurz":"López-Otín, C. u. a. (2013): The Hallmarks of Aging. Cell 153(6), 1194–1217, Abschnitt „Mitochondrial Dysfunction“","oeffentlich":true,"doi":"10.1016/j.cell.2013.05.039","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3836174/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Andziak, B. u. a. (2006): High oxidative damage levels in the longest-living rodent, the naked mole-rat. Aging Cell 5(6), 463–471 (doi 10.1111/j.1474-9726.2006.00237.x)","oeffentlich":false}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"b7842f9f7bab1688"}},{"id":"qx-c2-026","clusterId":"C","werkstueckRef":"C.4.9","stufe":4,"question":"Welche Einschätzung des Ansatzes ist am besten begründet?","scenario":"Ein Start-up wirbt für einen Wirkstoff, der gezielt „Zombie-Zellen“ (seneszente Zellen) aus dem Gewebe entfernen soll, und nennt ihn den „ersten Schritt zur Verjüngung“. Eine Investorin fragt dich, was man davon realistischerweise erwarten darf.","options":["Der Ansatz zielt darauf, Beschwerden zu lindern: Er dämpft die Entzündungsstoffe, die Zombie-Zellen abgeben, und soll das Gewebe so entlasten, ohne die Zellen selbst zu entfernen.","Der Ansatz zielt darauf, das Altern umzukehren: Er schaltet in den Zombie-Zellen Erbanlagen um, damit sie wieder jung werden, und greift dafür gezielt in die Gene ein.","Der Ansatz zielt darauf, den zellulären Verschleiß zu verlangsamen: Er entfernt Zellen, die sich angesammelt haben, und soll das Altern so bremsen, ohne in die Gene einzugreifen.","Der Ansatz zielt darauf, das Gewebe zu erneuern: Er bringt frische Stammzellen ein, die die Zombie-Zellen ersetzen, und soll das Gewebe so wieder auffüllen wie eine Organersatztherapie."],"correctIndex":2,"explanation":"Entscheidend ist, an welcher Stelle der Ansatz eingreift. Das Entfernen seneszenter „Zombie-Zellen“ setzt am Verschleiß der Zellen an und soll ihn verlangsamen, ähnlich wie das Ankurbeln der zelleigenen Reinigungsprozesse (Autophagie). Ob und wie gut das beim Menschen funktioniert, sagt diese Einordnung nicht, und das Altern selbst abzuschaffen, ist damit ohnehin nicht gemeint. Eine Werbeaussage wie „Verjüngung“ verlangt deshalb Belege aus Studien am Menschen, nicht nur ein plausibles Wirkprinzip.","coreRule":"⚡ Frag bei Anti-Aging-Versprechen, wo der Ansatz eingreift: bei den Folgen (Krankheiten), beim Verschleiß (Zellen, Chemie) oder bei den Grundlagen (Gene). Daran hängt, was er leisten kann und was nicht.","beleg":"Werkstück C.4.9 (Anwendung & Relevanz, Die drei Stufen des Anti-Aging)","status":"entwurf","kurz":"Der Wirkstoff nimmt angesammelte Zellen heraus und setzt so am Zellverschleiß an, er soll das Altern bremsen, nicht umkehren. Ob das beim Menschen funktioniert, zeigen erst Studien, ein plausibles Wirkprinzip allein belegt „Verjüngung“ nicht.","prueffrage":"Welche Ergebnisse aus Studien am Menschen nennt das Start-up für seinen Wirkstoff, und was genau wurde dort gemessen?","rueckmeldung":[{"option":0,"text":"Zombie-Zellen geben tatsächlich Entzündungsstoffe ab, und deren Dämpfung ist ein denkbarer Ansatz. Der Wirkstoff soll die Zellen aber gerade entfernen und nicht nur ihre Signale abschwächen, und das ist ein anderer Eingriffspunkt."},{"option":1,"text":"Beim Wort „Verjüngung“ liegt Reprogrammierung der Gene nahe. Hier wird jedoch nichts umgeschrieben, sondern nur Vorhandenes entfernt. Das Altern umzukehren ist damit ohnehin nicht gemeint."},{"option":3,"text":"Ein Ersatzverfahren mit Stammzellen gibt es als eigene Therapieform. Dieser Wirkstoff liefert aber nichts Neues, sondern nimmt nur angesammelte Zellen heraus, er ist also kein Organersatz."}],"familie":"genau-unterscheiden","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Chaib, S.; Tchkonia, T.; Kirkland, J. L. (2022): Cellular senescence and senolytics: the path to the clinic. Nature Medicine 28(8), 1556–1568","oeffentlich":true,"doi":"10.1038/s41591-022-01923-y","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC9599677/","abruf":"2026-10-12"},{"typ":"doi","kurz":"López-Otín, C. u. a. (2013): The Hallmarks of Aging. Cell 153(6), 1194–1217","oeffentlich":true,"doi":"10.1016/j.cell.2013.05.039","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3836174/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"1e6a4ac200bb5b43"}},{"id":"qx-c2-027","clusterId":"C","werkstueckRef":"C.4.10","stufe":1,"question":"Ein Labor hält menschliche Bindegewebszellen in einer Petrischale mit bester Nährlösung, wechselt das Medium regelmäßig und hält alle Bedingungen konstant. Nach etwa 50 Teilungen stellen die Zellen die Teilung ein, bleiben aber am Leben. Was erklärt diesen Befund am besten?","options":["Die Zellen haben eine eigene Teilungsgrenze: Bei jeder Teilung verkürzen sich die Schutzkappen an den Chromosomenenden, bis nach etwa 50 Teilungen der Stopp ausgelöst wird.","Im Medium häufen sich Stoffwechselabfälle der Zellen an, die ab einer bestimmten Menge die Teilung hemmen, bis die Kultur nach etwa 50 Teilungen zum Stillstand kommt.","Die Zellen lösen nach etwa 50 Teilungen den programmierten Zelltod aus, mit dem der Körper gealterte Zellen gezielt beseitigt, sodass die Schale nach und nach leer wird.","Die Zellen teilen sich nur auf äußere Wachstumssignale hin; nach etwa 50 Teilungen bleibt dieses Signal in der Schale aus, und die Zellen reagieren nicht mehr."],"correctIndex":0,"explanation":"Der Befund spricht gegen die Annahme, die Umgebung sei schuld: Die Bedingungen waren konstant und ideal, und der Teilungsstopp trat trotzdem nach etwa 50 Teilungen ein. Das deutet auf eine Grenze, die in der Zelle selbst liegt. Tatsächlich geht beim Kopieren der DNA bei jeder Teilung ein winziges Stück der Telomere verloren, der Schutzkappen an den Chromosomenenden (vergleichbar mit den Plastikkappen an Schnürsenkeln). Werden sie zu kurz, deutet die Zelle das als mögliche DNA-Schädigung, aktiviert das Wächter-Gen p53 und hört auf, sich zu teilen, ein Schutz vor Krebs. Die Zellen leben weiter, sind aber seneszent, gleichsam „Zombie-Zellen“. Diese nach Leonard Hayflick benannte Grenze zeigt früh, dass Altern auch von innen kommt. Sie bedeutet aber nicht, dass ein Programm den ganzen Körper altern lässt.","coreRule":"⚡ Wenn ein Effekt trotz konstanter, idealer Außenbedingungen eintritt, such die Ursache im System selbst.","beleg":"Werkstück C.4.10 (Die tickende Uhr in der Petrischale; Kernidee; Kontext & Tiefe)","status":"entwurf","scenario":"Eine Kommilitonin sagt: „Zellen in einer idealen Umgebung müssten sich doch ewig teilen können. Wenn sie aufhören, muss die Nährlösung schuld sein.“ Du sollst beurteilen, ob das stimmt.","quote":"","quoteLabel":"","kurz":"Der Teilungsstopp trat trotz konstanter, idealer Bedingungen ein, die Grenze muss also in der Zelle liegen: Mit jeder Teilung verkürzen sich die Telomere, bis die Zelle aufhört. Die Umgebung ist hier nicht die naheliegende Ursache.","prueffrage":"Was hat sich im Labor über die Zeit verändert, und was blieb für die Zellen konstant?","rueckmeldung":[{"option":1,"text":"Abfallstoffe können eine Kultur tatsächlich bremsen. Hier wurde das Medium aber regelmäßig gewechselt, und die Bedingungen blieben konstant, sodass sich nichts Hemmendes ansammeln konnte."},{"option":2,"text":"Programmierter Zelltod kommt vor und räumt gealterte Zellen weg. Die Zellen in der Schale bleiben aber am Leben und teilen sich nur nicht mehr, das ist etwas anderes als Sterben."},{"option":3,"text":"Wachstumssignale sind für die Teilung nötig. In der Schale blieben die Bedingungen aber konstant, ein plötzlich ausbleibendes Signal gibt es also nicht, und der Stopp kommt aus der Zelle selbst."}],"familie":"sparsamste-erklaerung","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Roake & Artandi 2017, Control of Cellular Aging, Tissue Function, and Cancer by p53 Downstream of Telomeres, Cold Spring Harb Perspect Med 7(5) (PMC5411683)","oeffentlich":true,"doi":"10.1101/cshperspect.a026088","abruf":"2026-10-12"},{"typ":"url","kurz":"Shay & Wright 2000, Hayflick, his limit, and cellular ageing, Nat Rev Mol Cell Biol 1(1) (PubMed-Abstract)","oeffentlich":true,"doi":"10.1038/35036093","url":"https://pubmed.ncbi.nlm.nih.gov/11413492/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Hayflick & Moorhead 1961, The serial cultivation of human diploid cell strains, Exp Cell Res 25","oeffentlich":false,"doi":"10.1016/0014-4827(61)90192-6"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"c79557a8bf752c96"}},{"id":"qx-c2-028","clusterId":"C","werkstueckRef":"C.4.10","stufe":2,"question":"Welche Erklärung ist am sparsamsten für diesen Befund?","options":["Die Zellen verbrauchen die Nährstoffe der erneuerten Lösung so stark, dass örtlicher Mangel die Teilung stoppt; Tumorzellen kommen mit weniger Nährstoffen aus.","Die Zellen stoppen die Teilung selbst, als Schutz vor Krebs, weil sie die verkürzten Schutzkappen als mögliche DNA-Schädigung deuten; Tumorzellen umgehen diese Bremse.","Die Zellen sterben durch programmierten Zelltod, wenn die verkürzten Schutzkappen als mögliche DNA-Schädigung gedeutet werden; Tumorzellen entgehen ihm.","Ein Störfaktor in der Kultur, etwa eine Verunreinigung, hemmt die Teilung der Zellen mit den verkürzten Schutzkappen; Tumorzellen sind gegen ihn widerstandsfähig."],"correctIndex":1,"explanation":"Der Befund enthält drei Hinweise: Die Nährlösung ist nicht der Engpass, die Zellen leben nach dem Stopp weiter, und die Chromosomenenden sind kürzer geworden. Das passt zu einer eingebauten Bremse: Bei jeder Teilung geht ein Stück der Schutzkappen (Telomere) verloren. Erreichen sie eine kritische Kürze, wird das als mögliche DNA-Schädigung gedeutet, das Wächter-Gen p53 stoppt die Teilung, und die Zelle bleibt als seneszente „Zombie-Zelle“ am Leben. Das verhindert, dass beschädigte Zellen sich unkontrolliert vermehren. Tumorzellen teilen sich unbegrenzt, weil sie oft das Enzym Telomerase reaktivieren und so die Grenze umgehen. Nährstoffmangel bremst Kulturen oft, wurde hier aber durch die erneuerte Lösung ausgeschlossen. Programmierter Zelltod ist ein anderer Weg, doch die Zellen leben ja weiter. Ein Störfaktor in der Schale müsste auch die Tumorzellen treffen und bräuchte eine Zusatzannahme, während die verkürzten Schutzkappen schon alles erklären.","coreRule":"⚡ Wähle die Erklärung, die alle Beobachtungen zugleich trägt, und prüfe jede Alternative an dem, was sie vorhersagen würde.","beleg":"Werkstück C.4.10 (Kontext & Tiefe, Der Seneszenz-Stopp; Anwendung & Relevanz)","status":"entwurf","scenario":"Ein Labor züchtet gesunde menschliche Zellen in einer Nährlösung, die immer wieder erneuert wird, sodass nichts knapp wird. Nach etwa 50 Teilungen hören die Zellen auf, sich zu teilen, bleiben aber am Leben und verbrauchen weiter Nährstoffe. Messungen zeigen, dass die Schutzkappen an den Chromosomenenden mit jeder Teilung kürzer geworden sind und nun eine kritische Länge erreicht haben. Gleichzeitig teilen sich Zellen aus einem Tumor unter denselben Bedingungen unbegrenzt weiter.","quote":"","quoteLabel":"","kurz":"Die Zellen bremsen sich selbst: Verkürzte Schutzkappen gelten als mögliche DNA-Schädigung, die Teilung stoppt, die Zellen bleiben aber am Leben. Naheliegend ist, äußere Ursachen oder Zusatzannahmen zu suchen, obwohl der Befund schon alles erklärt.","prueffrage":"Was lässt sich in der Schale beobachten, nachdem die Teilung aufgehört hat, und was zeigt die Messung an den Chromosomenenden?","rueckmeldung":[{"option":0,"text":"Nährstoffmangel bremst Kulturen oft, deshalb wirkt die Erklärung vertraut. Hier wurde er aber durch die erneuerte Lösung ausgeschlossen, und sie erklärt weder die verkürzten Schutzkappen noch, warum Tumorzellen weniger bräuchten."},{"option":2,"text":"Programmierter Zelltod ist tatsächlich ein möglicher Weg, auf verkürzte Schutzkappen zu reagieren. Hier aber bleiben die Zellen am Leben und verbrauchen weiter Nährstoffe, sie sterben also nicht ab, sondern hören nur auf, sich zu teilen."},{"option":3,"text":"Eine Verunreinigung ist als Störfaktor in Kulturen denkbar. Sie bräuchte aber die Zusatzannahme, dass sie nur die alten Zellen trifft und Tumorzellen verschont, wofür nichts im Befund spricht, während die verkürzten Schutzkappen schon alles erklären."}],"familie":"sparsamste-erklaerung","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Roake & Artandi 2017, Control of Cellular Aging, Tissue Function, and Cancer by p53 Downstream of Telomeres, Cold Spring Harb Perspect Med 7(5) (PMC5411683)","oeffentlich":true,"doi":"10.1101/cshperspect.a026088","abruf":"2026-10-12"},{"typ":"url","kurz":"Shay & Wright 2000, Hayflick, his limit, and cellular ageing, Nat Rev Mol Cell Biol 1(1) (PubMed-Abstract)","oeffentlich":true,"doi":"10.1038/35036093","url":"https://pubmed.ncbi.nlm.nih.gov/11413492/","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"bc55f25fd992aca1"}},{"id":"qx-c2-029","clusterId":"C","werkstueckRef":"C.4.10","stufe":3,"question":"Ein Forschungsteam schlägt vor, in gesunden Körperzellen das Enzym Telomerase dauerhaft zu aktivieren, damit sie sich unbegrenzt teilen können und das Altern aufgehalten wird. Krebszellen sind häufig deshalb „unsterblich“, weil sie Telomerase wieder anschalten. Welches Dilemma folgt daraus?","options":["Telomerase-Hemmer würden Tumoren bremsen, aber auch Stammzellen schädigen, die ihre Teilungsfähigkeit brauchen; das Dilemma liegt also in der Krebstherapie.","Telomerase würde gesunde Zellen zwar länger teilungsfähig halten, doch das Altern hat viele weitere Ursachen, sodass der Körper trotzdem weiter altern würde.","Wer sich die Telomerase-Behandlung leisten kann, würde länger leben als andere; das Dilemma liegt dann in der ungleichen Verteilung der gewonnenen Lebensjahre.","Telomerase könnte gesunden Zellen dieselbe Unsterblichkeit geben wie Krebszellen, sodass die schützende Teilungsgrenze entfiele und das Krebsrisiko stiege."],"correctIndex":3,"explanation":"Normale Zellen können sich nur etwa 40 bis 60 Mal teilen. Wenn die Telomere kritisch kurz werden, deutet die Zelle das als mögliche gefährliche DNA-Schädigung, aktiviert das Wächter-Gen p53 und stellt die Teilung ein. Diese Grenze schützt damit vor Krebs. Krebszellen umgehen sie häufig, indem sie Telomerase reaktivieren. Wer Telomerase in gesunden Zellen aktiviert, nimmt ihnen deshalb dieselbe Bremse. Ein möglicher Gewinn (länger teilungsfähige Zellen) ist untrennbar mit einem Risiko (ungebremstes Wachstum geschädigter Zellen) verbunden. Das Dilemma entsteht, weil Nutzen und Schaden am selben Mechanismus hängen.","coreRule":"⚡ Wer eine Schutzgrenze aufhebt, um einen Nutzen zu gewinnen, nimmt auch den Schutz weg, den sie geboten hat: Prüfe, wofür die Grenze da ist, bevor du sie abschaffen willst.","beleg":"Werkstück C.4.10 (Anwendung & Relevanz); vgl. Werkstück C.4.4","status":"entwurf","scenario":"","quote":"","quoteLabel":"","kurz":"Wer Telomerase in gesunden Zellen dauerhaft aktiviert, nimmt ihnen die Teilungsgrenze, die vor Krebs schützt. Nutzen und Risiko hängen am selben Mechanismus. Ein Dilemma entsteht dort, wo beides untrennbar verbunden ist, nicht bei jedem Haken einer Idee.","prueffrage":"Was geschieht normalerweise, wenn die Telomere einer gesunden Zelle sehr kurz geworden sind?","rueckmeldung":[{"option":0,"text":"Telomerase-Hemmer sind tatsächlich ein eigenes Dilemma der Krebstherapie. Der Vorschlag aber will Telomerase in gesunden Zellen einschalten, also die Gegenrichtung. Gefragt ist das Dilemma dieses Vorschlags."},{"option":1,"text":"Dass Altern viele Ursachen hat, stimmt und schmälert den möglichen Nutzen. Das ist aber nur eine Einschränkung des Gewinns, kein Konflikt, denn ein Risiko, das am selben Mechanismus hängt, kommt darin nicht vor."},{"option":2,"text":"Gerechtigkeitsfragen solcher Behandlungen sind real. Sie ergeben sich aber nicht aus dem, was über Krebszellen und Telomerase gesagt ist, sondern setzen Annahmen über Kosten und Zugang voraus, die in der Situation nicht stehen."}],"familie":"nutzen-und-risiko-abwaegen","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Roake & Artandi 2017, Control of Cellular Aging, Tissue Function, and Cancer by p53 Downstream of Telomeres, Cold Spring Harb Perspect Med 7(5) (PMC5411683)","oeffentlich":true,"doi":"10.1101/cshperspect.a026088","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Hayflick & Moorhead 1961, The serial cultivation of human diploid cell strains, Exp Cell Res 25","oeffentlich":false,"doi":"10.1016/0014-4827(61)90192-6"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"9619caf5fcc51c13"}},{"id":"qx-c2-030","clusterId":"C","werkstueckRef":"C.4.10","stufe":4,"question":"Wie ist die Aussage „Die Forschung hat bewiesen: höchstens 120 bis 150 Jahre“ einzuordnen?","scenario":"Ein Artikel meldet: „Die Forschung hat bewiesen: Der Mensch kann höchstens 120 bis 150 Jahre alt werden.“ Als Grundlage dient eine Modellrechnung, die aus den Blutwerten von Hunderttausenden Menschen schätzt, wann die körperliche Widerstandsfähigkeit vollständig verloren ginge. Andere Forschergruppen werten stattdessen die tatsächlich erreichten Höchstalter aus und kommen zu voneinander abweichenden Ergebnissen: Die eine sieht die Höchstalter seit Jahrzehnten bei 114 Jahren stagnieren, die andere findet ab 105 Jahren ein Sterblichkeitsplateau ohne erkennbare Grenze.","options":["Als Schätzung eines Modells; weil Auswertungen der tatsächlich erreichten Höchstalter zu abweichenden Ergebnissen kommen, ist „bewiesen“ zu stark.","Als bewiesen, weil die Modellrechnung auf den Blutwerten von Hunderttausenden Menschen beruht und eine so große Stichprobe das Ergebnis absichert.","Als Zirkelschluss; weil das Modell die Grenze von 120 bis 150 Jahren schon in seine Annahmen einbaut, gibt es sie am Ende nur als Ergebnis aus.","Als zunächst unbeurteilbar; erst wenn bekannt ist, wie sorgfältig die Blutwerte der Hunderttausenden erhoben wurden, lässt sich das Gewicht einschätzen."],"correctIndex":0,"explanation":"Eine Modellrechnung, die aus Blutwerten einen Punkt „totalen Resilienzverlusts“ schätzt (Pyrkov u. a. 2021: etwa 120–150 Jahre), ist eine Modellschätzung, kein direkt beobachteter Wert. Das zeigt schon der Blick auf die Gegenseite: Eine Auswertung der jährlichen Höchstalter (Dong u. a. 2016) sieht seit den 1990er Jahren eine Stagnation bei 114 Jahren, eine andere (Barbi u. a. 2018) ab 105 Jahren ein Sterblichkeitsplateau ohne erkennbare Grenze. Wo sich methodisch unterschiedliche Auswertungen nicht einig sind, ist die Frage offen. Eine große Stichprobe ändert an der Natur einer Modellschätzung nichts. Wer eine offene Forschungsfrage als „bewiesen“ meldet, zeigt mehr Sicherheit, als die Belege hergeben.","coreRule":"⚡ Eine Modellschätzung ist kein Beweis, und widersprechen sich unabhängige Auswertungen, ist die Frage offen.","beleg":"Werkstück C.4.10 (Die Berechnungen; Der Stand der Forschung); Fn. gl-c-lebensspanne (Pyrkov u. a. 2021, Nat. Commun. 12, Art. 2765); Fn. gl-c-lebensspanne-dissens (Dong u. a. 2016, Nature 538, S. 257–259; Barbi u. a. 2018, Science 360, S. 1459–1461; Warner u. a. 2005)","status":"entwurf","kurz":"Eine Modellrechnung liefert eine Schätzung, keinen beobachteten Wert. Da Auswertungen der tatsächlich erreichten Höchstalter zu abweichenden Ergebnissen kommen, ist die Frage offen. „Bewiesen“ zeigt mehr Sicherheit, als die Belege hergeben.","prueffrage":"Was wurde für die Modellrechnung tatsächlich gemessen, und welcher Wert wurde daraus erst errechnet?","rueckmeldung":[{"option":1,"text":"Hunderttausende Datensätze wirken überzeugend, und die Stichprobe ist tatsächlich groß. Sie macht die Schätzung aber nicht zum Beweis: Aus den Werten wird ein Punkt berechnet, den niemand beobachtet hat, und andere Auswertungen kommen anders heraus."},{"option":2,"text":"Bei einer errechneten Obergrenze liegt der Verdacht nahe, sie sei nur eingespeist worden. Das Modell schätzt die Grenze aber aus den Blutwerten und setzt sie nicht voraus. Das Problem liegt anderswo: Eine Schätzung wird als Beweis ausgegeben."},{"option":3,"text":"Die Qualität der Blutwerte ist eine gute Zusatzfrage. Die Einordnung braucht sie aber nicht abzuwarten: Schon dass andere Auswertungen der tatsächlich erreichten Höchstalter zu abweichenden Ergebnissen kommen, zeigt, dass „bewiesen“ zu stark ist."}],"familie":"wiederholung-abwarten","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Pyrkov u. a. 2021, Longitudinal analysis of blood markers reveals progressive loss of resilience and predicts human lifespan limit, Nature Communications 12 (PMC8149842)","oeffentlich":true,"doi":"10.1038/s41467-021-23014-1","abruf":"2026-10-12"},{"typ":"doi","kurz":"Dong, Milholland & Vijg 2016, Evidence for a limit to human lifespan, Nature 538 (PMC11673931)","oeffentlich":true,"doi":"10.1038/nature19793","abruf":"2026-10-12"},{"typ":"doi","kurz":"Barbi u. a. 2018, The plateau of human mortality: Demography of longevity pioneers, Science 360 (PMC6457902)","oeffentlich":true,"doi":"10.1126/science.aat3119","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"c551505e08f420fb"}},{"id":"qx-c2-031","clusterId":"C","werkstueckRef":"C.4.11","stufe":1,"question":"Ein Museumstext behauptet: „Vor etwa 300 Millionen Jahren gab es Libellen mit der Spannweite von Möwen – das beweist, dass die Schwerkraft damals deutlich geringer war.“ Welche Prüfung trifft den Kern der Behauptung am besten?","options":["Gibt es unabhängige Belege für eine geringere Schwerkraft, und lässt sich die Größe der Libellen auch ohne sie erklären?","Sind die Fossilien tatsächlich rund 300 Millionen Jahre alt, und wurden die Spannweiten an vollständigen Funden gemessen?","Wer hat den Museumstext verfasst, und hat diese Person eine fachliche Ausbildung in Paläontologie oder Geologie?","Sind die Funde repräsentativ, oder stammen sie alle aus einer einzigen Fundstelle mit besonderen Bedingungen?"],"correctIndex":0,"explanation":"Der Schluss „riesige Tiere, also geringere Schwerkraft“ ist eine Erklärung unter mehreren. Gute Prüfung heißt, nach unabhängigen Belegen für genau diese Ursache zu fragen und zu klären, ob eine andere Erklärung dasselbe leistet. Hier gibt es sie: Nach gängigen Modellen (Berner 2006; Krause u. a. 2018) lag der Sauerstoffgehalt vor rund 300 Millionen Jahren bei etwa 25 bis 30 Prozent (heute 21), gestützt durch fossile Holzkohle. Insekten haben ein einfaches Atmungssystem, das von höherer Sauerstoffkonzentration profitierte; das macht große Körper plausibel (Clapham/Karr 2012). Für eine andere Schwerkraft gibt es keinen Beleg; die Größe lässt sich auch ohne diese Annahme über den Sauerstoff erklären. Auch die Sauerstofferklärung bleibt eine begründete Vermutung, kein bewiesener Befund. Alter und Vollständigkeit der Funde zu prüfen ist sinnvoll, doch das Szenario nennt sie als belegt, und selbst gesicherte Funde sagen nichts über die Ursache der Größe. Die Frage nach dem Verfasser des Textes prüft eine Person, nicht die Behauptung. Und ob die Funde repräsentativ sind, betrifft, wie verbreitet solche Riesen waren, nicht, warum sie so groß werden konnten.","coreRule":"⚡ Eine Behauptung prüfst du, indem du nach unabhängigen Belegen für genau die genannte Ursache fragst und nach einfacheren Erklärungen suchst.","beleg":"Werkstück C.4.11 (Der Sauerstoffgehalt); Fn. gl-c-karbon (Sauerstoffwerte: Berner 2006, Krause u. a. 2018; Insektengröße: Clapham/Karr 2012)","status":"entwurf","scenario":"Fossilien aus dem Karbon belegen riesige libellenähnliche Insekten, sogenannte Riesenlibellen. Zugleich weisen unabhängige Spuren (etwa fossile Holzkohle) und mehrere Klimamodelle auf einen Sauerstoffanteil der Luft von etwa 25 bis 30 Prozent hin, gegenüber 21 Prozent heute.","kurz":"Aus „riesig“ folgt nicht „geringe Schwerkraft“: Das ist nur eine von mehreren möglichen Erklärungen. Gefragt werden muss nach unabhängigen Belegen dafür und danach, ob etwas anderes die Größe ebenso erklärt, hier etwa ein höherer Sauerstoffgehalt.","prueffrage":"Was an der Behauptung im Museumstext ist durch Fossilien belegt, und was ist daraus erst gefolgert?","rueckmeldung":[{"option":1,"text":"Alter und Vollständigkeit der Funde zu prüfen ist sinnvoll, doch das Szenario nennt sie bereits als belegt. Selbst gesicherte Funde sagen noch nichts darüber, warum die Tiere so groß wurden."},{"option":2,"text":"Die Frage nach dem Verfasser wirkt wie gründliches Prüfen, nimmt aber eine Person in den Blick statt die Aussage. Auch eine Fachfrau kann sich irren, und der Satz muss sich an seinen Belegen messen lassen."},{"option":3,"text":"Ob die Funde repräsentativ sind, ist eine gute Frage, sagt aber nur, wie verbreitet solche Riesen waren. Warum sie so groß werden konnten, bleibt davon unberührt, und genau darauf zielt die Behauptung."}],"familie":"sparsamste-erklaerung","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Krause u. a. 2018, Stepwise oxygenation of the Paleozoic atmosphere, Nature Communications 9 (PMC6172248)","oeffentlich":true,"doi":"10.1038/s41467-018-06383-y","abruf":"2026-10-12"},{"typ":"doi","kurz":"Clapham & Karr 2012, Environmental and biotic controls on the evolutionary history of insect body size, PNAS 109(27) (PMC3390886)","oeffentlich":true,"doi":"10.1073/pnas.1204026109","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Berner 2006, GEOCARBSULF: A combined model for Phanerozoic atmospheric O2 and CO2, Geochim Cosmochim Acta 70(23)","oeffentlich":false,"doi":"10.1016/j.gca.2005.11.032"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"fccb896d751e999f"}},{"id":"qx-c2-032","clusterId":"C","werkstueckRef":"C.4.11","stufe":2,"question":"Eine Schülerin behauptet: „Ein Blauwal ist so riesig, weil Meerestiere einfach stärkere Gene für Wachstum haben als Landtiere.“ Was spricht am stärksten gegen diese Erklärung?","options":["Ein Blauwal im Wasser wird vom Auftrieb getragen, ein Landtier muss sein ganzes Gewicht selbst stützen und bräuchte dafür im Verhältnis immer massivere Knochen.","Körpergröße ist zu einem erheblichen Teil erblich: Blauwal-Kälber werden groß, weil ihre Eltern groß sind, sodass Gene bei Größenunterschieden mitwirken.","Wasser enthält weniger gelösten Sauerstoff als Luft, sodass ein Blauwal seine riesige Körpermasse eher schwerer versorgt als ein Landtier die seine.","Blauwale legen für ihre weiten Wanderungen dicke Fettreserven an, die einen großen Teil ihres Körpergewichts ausmachen, sodass ihre Größe teils aus Speicherfett besteht."],"correctIndex":0,"explanation":"Die Erklärung über „stärkere Gene“ übersieht, dass die Umgebung die Möglichkeiten vorgibt. Wasser trägt einen großen Teil des Körpergewichts durch Auftrieb, sodass ein Meerestier sein Gewicht kaum selbst stützen muss. An Land setzt die Schwerkraft dagegen eine Obergrenze: Je schwerer ein Landtier wird, desto massiver müssen seine tragenden Knochen im Verhältnis werden; schon Galilei hielt 1638 fest, dass Riesentiere im Wasser bestehen können, an Land aber nicht ohne veränderte Körperproportionen. Dass Körpergröße zum Teil erblich ist, stimmt, ist aber kein Gegenargument, sondern spricht eher dafür, dass Gene eine Rolle spielen. Dass Wasser weniger gelösten Sauerstoff enthält, erschwert große Körper eher, erklärt also nicht, warum Meerestiere größer werden. Fettreserven sind ein Teil des Körpergewichts, sagen aber nichts darüber, was dieses Gewicht überhaupt tragbar macht.","coreRule":"⚡ Bevor du Unterschiede den Genen zuschreibst, prüfe die physikalischen Rahmenbedingungen: An Land begrenzt die Schwerkraft die Größe, im Wasser trägt der Auftrieb mit.","beleg":"Werkstück C.4.11 (Die Stärke der Erdanziehungskraft, Blauwal/Auftrieb); Fn. gl-c-schwerkraft (Galilei 1638: Riesentiere im Wasser; Campione/Evans 2012, BMC Biology 10, 60)","status":"entwurf","scenario":"Die Größe von Tieren hängt nicht nur von ihren Genen ab, sondern auch von den physikalischen Bedingungen, unter denen sie leben. Landtiere und Meerestiere tragen ihr Gewicht unter sehr verschiedenen Bedingungen.","kurz":"Entscheidend ist die Umgebung: Wasser trägt durch den Auftrieb viel vom Gewicht, an Land setzt die Schwerkraft eine Grenze. Wer die Größe allein mit „stärkeren Genen“ erklärt, übersieht, dass die Umgebung die Möglichkeiten vorgibt.","prueffrage":"Wie schwer werden die größten Tiere im Meer und an Land, und worin unterscheiden sich ihre Lebensbedingungen außer in den Genen?","rueckmeldung":[{"option":1,"text":"Dass Körpergröße zum Teil erblich ist, stimmt. Das spricht aber nicht gegen die Gen-Erklärung, sondern eher für eine Rolle der Gene. Es erklärt auch nicht, warum gerade Meerestiere so viel größer werden können als Landtiere."},{"option":2,"text":"Wasser enthält tatsächlich weniger gelösten Sauerstoff als Luft. Das erschwert große Körper eher und kann daher nicht erklären, warum Meerestiere größer werden. Gegen die Gen-Erklärung wendet es sich ebenfalls nicht."},{"option":3,"text":"Fettreserven machen bei Walen tatsächlich einen großen Teil des Körpergewichts aus. Sie sind aber nur ein Teil dieses Gewichts und sagen nichts darüber, was es überhaupt tragbar macht. Die Gen-Erklärung widerlegen sie nicht."}],"familie":"sparsamste-erklaerung","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Campione & Evans 2012, A universal scaling relationship between body mass and proximal limb bone dimensions in quadrupedal terrestrial tetrapods, BMC Biology 10 (PMC3403949)","oeffentlich":true,"doi":"10.1186/1741-7007-10-60","abruf":"2026-10-12"},{"typ":"doi","kurz":"Biewener 2005, Biomechanical consequences of scaling, Journal of Experimental Biology 208(9)","oeffentlich":true,"doi":"10.1242/jeb.01520","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Galilei 1638, Unterredungen und mathematische Demonstrationen über zwei neue Wissenszweige (dt. von Oettingen 1890, Ostwald's Klassiker 11)","oeffentlich":false}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"b3dbd0a75730f194"}},{"id":"qx-c2-033","clusterId":"C","werkstueckRef":"C.4.11","stufe":3,"question":"Wie solltest du diese Aussage einschätzen?","scenario":"Jemand sagt: „Oxidation und Schwerkraft verhindern am Ende immer echte biologische Unsterblichkeit – das ist Physik, da gibt es keine Ausnahme.“ Du weißt: Die Maus lebt nur wenige Jahre. Der Nacktmull, ein Nagetier ähnlicher Größe, wird rund zehnmal so alt wie eine Maus, obwohl seine Zellen deutlich mehr oxidative Schäden aufweisen als die einer Maus.","options":["Als gesicherter Befund, weil physikalische Gesetze keine Ausnahmen kennen und langlebige Tiere sich nur langsamer abnutzen.","Als widerlegt, weil eine Regel ohne Ausnahme schon durch ein einziges Gegenbeispiel fällt und der Nacktmull eines liefert.","Als plausible Vermutung, nicht als Befund, weil ein Gegenbeispiel zur Vorsicht mahnt und die Aussage unbewiesen bleibt.","Als belanglos, weil sich Beobachtungen an einer Tierart nicht ohne Weiteres auf andere Arten übertragen lassen."],"correctIndex":2,"explanation":"Die Aussage klingt nach Physik, ist aber eine Vermutung über das Altern, kein gemessenes Ergebnis. Der Nacktmull zeigt, warum Vorsicht angebracht ist: Er lebt trotz deutlich höherer oxidativer Schäden (Andziak u. a. 2006) rund zehnmal so lange wie eine Maus ähnlicher Größe. Das widerlegt die Vermutung nicht, zeigt aber, dass viel Oxidation nicht zwingend ein kurzes Leben bedeutet. Zur Schwerkraft sagt das Beispiel nichts; dieser Teil der Aussage ist ebenso wenig belegt, nur behauptet. Dass Oxidation und Schwerkraft echte biologische Unsterblichkeit am Ende immer verhindern, bleibt deshalb eine Vermutung, kein Befund.","coreRule":"⚡ Plausible Grenzen sind keine bewiesenen Grenzen – ein Gegenbeispiel genügt zur Vorsicht.","beleg":"Werkstück C.4.11 (Schlussfolgerung); Fn. gl-c-nacktmull (Andziak u. a. 2006, Aging Cell 5(6), S. 463–471: hohe oxidative Schäden beim Nacktmull)","status":"entwurf","kurz":"Die Aussage klingt nach Physik, ist aber nur eine Vermutung über das Altern, kein Messergebnis. Der Nacktmull lebt trotz mehr oxidativer Schäden etwa zehnmal so lange wie die Maus. Das widerlegt nichts, mahnt aber zur Vorsicht.","prueffrage":"Was genau wurde beim Nacktmull gemessen, und sagt das etwas darüber aus, ob Unsterblichkeit möglich ist?","rueckmeldung":[{"option":0,"text":"Physikalische Gesetze kennen tatsächlich keine Ausnahmen. Aber dass Oxidation und Schwerkraft ein solches Gesetz des Alterns bilden, ist hier nicht belegt. Und der Nacktmull lebt trotz höherer Schäden länger, passt also nicht zu bloßer Abnutzung."},{"option":1,"text":"Ein einziges echtes Gegenbeispiel kann eine Allaussage tatsächlich kippen. Der Nacktmull ist aber keines: Er lebt zwar rund zehnmal so lange wie eine Maus, stirbt am Ende aber auch. Widerlegt wäre die Aussage erst durch ein unsterbliches Lebewesen."},{"option":3,"text":"Befunde einer Art lassen sich nicht ohne Weiteres auf andere übertragen. Die Aussage soll aber für alle Lebewesen gelten und muss sich deshalb auch an einer einzelnen Art messen lassen. Belanglos ist der Nacktmull daher nicht, er mahnt zur Vorsicht."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Andziak u. a. 2006, High oxidative damage levels in the longest-living rodent, the naked mole-rat, Aging Cell 5(6) (PubMed-Abstract)","oeffentlich":true,"doi":"10.1111/j.1474-9726.2006.00237.x","url":"https://pubmed.ncbi.nlm.nih.gov/17054663/","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"0cddce709bc373b2"}},{"id":"qx-c2-034","clusterId":"C","werkstueckRef":"C.4.11","stufe":4,"question":"Wie solltest du diesen Befund einordnen?","scenario":"Eine Schweizer Studie mit 1,64 Millionen Erwachsenen im Alter von 40 bis 84 Jahren, die in 259 bis 1960 Metern Höhe wohnen, zeigt: Je 1000 Höhenmeter starben 22 Prozent weniger Menschen an koronarer Herzkrankheit und 12 Prozent weniger an Schlaganfall. Frühere Studien zum Thema kamen zu widersprüchlichen Ergebnissen. Jemand folgert daraus: „Dünne Luft schützt das Herz.“","options":["Als Beobachtung mit offener Ursache: Der Zusammenhang selbst ist belegt, ob die dünne Luft der Grund ist, dagegen nicht.","Als bewiesene Schutzwirkung der dünnen Luft: Das Risiko sinkt mit jeder Höhenstufe weiter, und dieser Stufenverlauf zeigt, dass sie wirkt.","Als Zufallsbefund: Frühere Studien kamen zu widersprüchlichen Ergebnissen, daher sagt auch der Zusammenhang dieser Studie nichts aus.","Als Handlungsempfehlung: Wer sein Herz schützen will, sollte in höhere Lagen ziehen, denn dort sinkt das Risiko deutlich."],"correctIndex":0,"explanation":"Die Studie fand einen deutlichen Zusammenhang zwischen Wohnhöhe und Sterblichkeit durch Herz- und Gefäßerkrankungen. Aus einem Zusammenhang in Beobachtungsdaten folgt aber noch nicht, was ihn verursacht. Menschen in höheren Lagen unterscheiden sich vermutlich auch in anderen Dingen, die den Effekt ganz oder teilweise erklären könnten; die Ursache bleibt offen. Dass dünne Luft die Ursache ist, bleibt eine Hypothese, die man gezielt prüfen müsste.","coreRule":"⚡ Auch ein gut gemessener Zusammenhang erklärt noch nicht, was ihn verursacht.","beleg":"Werkstück C.4.11 (Das Rennen der zwei Läufer); Fn. gl-c-hoehe (Faeh u. a. 2009, Circulation 120(6), S. 495–501)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Der Zusammenhang zwischen Wohnhöhe und Herztod ist bei dieser Datenmenge belegt, seine Ursache aber nicht. Wer „dünne Luft schützt“ sagt, macht aus „tritt zusammen auf“ eine Ursache, obwohl Höhenbewohner sich vermutlich auch in anderem unterscheiden.","prueffrage":"Worin könnten sich Menschen, die auf 1900 Metern wohnen, außer der Höhe noch von denen im Tal unterscheiden?","rueckmeldung":[{"option":1,"text":"Ein stufenweises Sinken spricht eher für einen echten Einfluss der Höhe. Dass gerade die dünne Luft wirkt, beweist es aber nicht, denn auch andere Unterschiede zwischen Höhen- und Tallagen können ein solches Gefälle erzeugen."},{"option":2,"text":"Die widersprüchlichen früheren Studien mahnen zur Vorsicht. Sie machen diesen Befund aber nicht zufällig: Bei 1,64 Millionen Menschen und einem klaren Gefälle ist der Zusammenhang selbst belegt, nur seine Ursache bleibt offen."},{"option":3,"text":"In den Daten ist das Risiko in höheren Lagen tatsächlich niedriger. Ob ein Umzug das eigene Risiko senken würde, kann eine reine Beobachtung aber nicht zeigen, denn die Bewohner unterscheiden sich vermutlich auch in anderem."}],"familie":"korrelation-und-ursache","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Faeh, Gutzwiller & Bopp 2009, Lower mortality from coronary heart disease and stroke at higher altitudes in Switzerland, Circulation 120(6) (PubMed-Abstract)","oeffentlich":true,"doi":"10.1161/CIRCULATIONAHA.108.819250","url":"https://pubmed.ncbi.nlm.nih.gov/19635973/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"25e151ebdfa461bf"}},{"id":"qx-c2-035","clusterId":"C","werkstueckRef":"C.5.1","stufe":1,"question":"Was ist an diesem Argument fehlerhaft?","options":["Der Politiker schließt aus einem einzelnen kalten Winter an einem Ort auf den langfristigen Temperaturtrend, obwohl dafür der Durchschnitt vieler Jahre entscheidend ist.","Der Politiker beruft sich auf die Zustimmung vieler Menschen im Land, obwohl die Zahl der Anhänger einer Aussage nichts über ihre Richtigkeit sagt.","Der Politiker verwechselt Korrelation und Kausalität, obwohl zwei Ereignisse, die gemeinsam auftreten, nicht in einem Ursache-Wirkung-Verhältnis stehen müssen.","Der Politiker greift die Klimaforscher persönlich an, obwohl die Eigenschaften einer Person nichts über die Richtigkeit ihrer Ergebnisse aussagen."],"correctIndex":0,"explanation":"Das Wetter ist von Natur aus variabel und chaotisch: wie ein Hund, der wild um seinen Besitzer herumläuft, während dieser stetig in eine Richtung geht. Das Klima ist der statistische Durchschnitt des Wetters samt der Häufigkeit von Extremen, typischerweise über rund 30 Jahre. Ein einzelner kalter Tag oder Winter an einem Ort sagt über diesen Trend deshalb ebenso wenig aus wie ein einzelner warmer. Zudem bedeutet Erwärmung nicht, dass es überall und jederzeit wärmer wird: Einzelne harte Kälteeinbrüche bleiben möglich. Wer aus ein paar Tagen auf den Trend schließt, schaut fünf Sekunden auf den Hund und übersieht den Spaziergänger.","coreRule":"⚡ Wetter ist der Hund, Klima ist der Spaziergänger: Ein einzelnes Ereignis widerlegt keinen Langzeittrend.","quote":"Sprechen wir hier gerade über den Hund (das Wetter) oder über den Spaziergänger (das Klima)? Ist diese kurzfristige Beobachtung repräsentativ für den langfristigen Trend?","quoteLabel":"Prüffrage:","beleg":"Werkstück C.5.1 (Kernidee; Kontext & Tiefe; Das Anti-Denkmuster)","status":"entwurf","scenario":"Nach dem kältesten Januar seit Jahrzehnten sagt ein Politiker vor laufender Kamera: „Es ist eiskalt, Schnee bis zum Knie. Die globale Erwärmung ist damit widerlegt!“","kurz":"Ein kalter Winter an einem Ort ist Wetter, kein Klima: Klima ist der Durchschnitt über rund 30 Jahre, und auch bei Erwärmung bleiben einzelne Kälteeinbrüche möglich. Wer aus ein paar Tagen auf den Trend schließt, übersieht den langen Verlauf.","prueffrage":"Wäre ein besonders heißer Januar an demselben Ort ein Beweis für die Erwärmung?","rueckmeldung":[{"option":1,"text":"Dass viele Menschen etwas glauben, beweist tatsächlich nichts. Der Politiker beruft sich hier aber gar nicht auf eine Mehrheit, sondern auf seine eigene Beobachtung von Kälte und Schnee. Der Fehler liegt im Schluss von dieser Beobachtung."},{"option":2,"text":"Dass gemeinsames Auftreten keine Ursache belegt, stimmt allgemein. Der Politiker behauptet aber keinen Zusammenhang zweier Ereignisse, sondern schließt von einem kalten Winter direkt auf den Trend. Es fehlt kein Ursachenbeweis, sondern eine ausreichende Datenbasis."},{"option":3,"text":"Ein persönlicher Angriff würde die Richtigkeit von Ergebnissen tatsächlich nicht widerlegen. Hier greift der Politiker aber niemanden an, er stützt sich nur auf das Wetter vor seiner Tür. Das Problem ist, dass diese Beobachtung für einen Trend nicht ausreicht."}],"familie":"trend-statt-einzelfall","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"NOAA National Centers for Environmental Information: WMO Climate Normals","oeffentlich":true,"url":"https://ncei.noaa.gov/products/wmo-climate-normals","abruf":"2026-10-12"},{"typ":"url","kurz":"IPCC (2021): Summary for Policymakers. In: Climate Change 2021: The Physical Science Basis, A.3.1","oeffentlich":true,"doi":"10.1017/9781009157896.001","url":"https://www.ipcc.ch/report/ar6/wg1/downloads/report/IPCC_AR6_WGI_SPM.pdf","seite":"8","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"243eaf39f4d2f9a7"}},{"id":"qx-c2-036","clusterId":"C","werkstueckRef":"C.5.1","stufe":2,"question":"Was ist an dieser Aussage richtig, und was blendet sie aus?","scenario":"Nach einer Hitzewelle sagt ein Bekannter: „Solche Hitzewellen hat es schon immer gegeben. Das ist kein Beweis für irgendeinen Klimawandel.“","options":["Sie stimmt, blendet aber aus, dass es bei Extremwetter nicht darum geht, ob es solche Ereignisse je gab, sondern ob sie häufiger und heftiger werden.","Sie stimmt, blendet aber aus, dass Hitzewellen für Gesundheit und Landwirtschaft gefährlich sind, weshalb sie unabhängig von ihrer Ursache Vorsorge verlangen.","Sie stimmt, blendet aber aus, dass frische Ereignisse im Gedächtnis überschätzt werden, sodass sich jede neue Hitzewelle häufiger anfühlt als frühere.","Sie stimmt, blendet aber aus, dass Hitzewellen je nach Land unterschiedlich definiert werden, weshalb Vergleiche über Ländergrenzen hinweg schwierig sind."],"correctIndex":0,"explanation":"Die Aussage ist richtig, aber sie beantwortet eine Frage, die niemand stellt. Die Klimawissenschaft behauptet nicht, Hitzewellen seien neu, sondern dass ihre Häufigkeit und Intensität zunehmen, weil dem System zusätzliche Energie zugeführt wird. Dass etwas früher vorkam, schließt nicht aus, dass es heute häufiger oder heftiger vorkommt. Zur Veranschaulichung: Auch Verkehrsunfälle gab es schon immer; entscheidend ist, ob ihre Zahl steigt. Für Hitzeextreme zeigt der IPCC-Bericht (2021) tatsächlich, dass Hitzewellen seit den 1950er-Jahren in den meisten Landregionen häufiger und heftiger geworden sind, Kälteextreme dagegen seltener und milder. Dabei lohnt Genauigkeit: Bei Hitzeextremen ist die Zunahme praktisch sicher, bei Dürren je nach Region und Dürretyp unterschiedlich gut belegt. Wer „gab es schon immer“ sagt, vergleicht also Existenz mit Häufigkeit und weicht damit der eigentlichen Frage aus.","coreRule":"⚡ „Gab es schon immer“ ist richtig, aber die Häufigkeit zählt.","beleg":"Werkstück C.5.1 (Die thermodynamische Grundlage; Anwendung & Relevanz); Fn. gl-c-ipcc-extreme (IPCC 2021, Summary for Policymakers, A.3.1 und A.3.2, S. 8)","status":"entwurf","kurz":"Dass es Hitzewellen schon immer gab, stimmt, beantwortet aber nicht die eigentliche Frage. Der Denkfehler: Existenz wird mit Häufigkeit verwechselt; entscheidend ist, ob solche Ereignisse heute öfter und heftiger auftreten als früher.","prueffrage":"Was müsste man zählen oder messen, um zu prüfen, ob sich bei Hitzewellen in den letzten Jahrzehnten etwas verändert hat?","rueckmeldung":[{"option":1,"text":"Dass Hitze gefährlich ist und Vorsorge verlangt, stimmt und ist wichtig. Es sagt aber nichts darüber, was die Aussage des Bekannten ausblendet; sein Satz sagt dazu schlicht nichts, und gefährlich war Hitze auch früher."},{"option":2,"text":"Frische Ereignisse bleiben tatsächlich stärker im Gedächtnis, das kann den Eindruck verzerren. Dieser Eindruck ist hier aber nicht der Punkt: Gemessene Daten zeigen die Zunahme unabhängig vom Gefühl."},{"option":3,"text":"Dass Hitzewellen je nach Land unterschiedlich definiert werden, stimmt und erschwert internationale Vergleiche. Die Frage, ob sie häufiger werden, lässt sich aber mit einheitlicher Definition auch für einen einzelnen Ort beantworten."}],"familie":"trend-statt-einzelfall","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"IPCC (2021): Summary for Policymakers. In: Climate Change 2021: The Physical Science Basis, A.3.1 und A.3.2","oeffentlich":true,"doi":"10.1017/9781009157896.001","url":"https://www.ipcc.ch/report/ar6/wg1/downloads/report/IPCC_AR6_WGI_SPM.pdf","seite":"8","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"128b9f419de8f876"}},{"id":"qx-c2-037","clusterId":"C","werkstueckRef":"C.5.1","stufe":3,"question":"Welche Entscheidung zeigt am deutlichsten, dass hier Wetter mit Klima verwechselt wird?","options":["Der Deichbau wird gestoppt, weil es in den letzten Wochen zufällig trocken war – ein kurzfristiger Eindruck ersetzt hier Langzeitdaten.","Der Deichbau wird verschoben, weil die Pegelmessungen der letzten Jahrzehnte erst noch genauer ausgewertet und geprüft werden sollen.","Der Deichbau wird beschlossen, weil die Messreihen zeigen, dass starke Hochwasser im Mittel häufiger und heftiger geworden sind.","Der Deichbau wird in der Gemeinde diskutiert, weil einzelne Anwohner von ihren Erfahrungen mit früheren Überschwemmungen berichtet haben."],"correctIndex":0,"explanation":"Entscheidungen von langer Reichweite müssen sich auf den langfristigen statistischen Trend stützen, nicht auf den Zustand der letzten Tage oder Wochen. Drei trockene Wochen sind Wetter; Klima ist der statistische Durchschnitt über Jahrzehnte (typischerweise 30 Jahre). Einen Deichbau zu stoppen, weil es heute gerade mal nicht regnet, ist ein Fehlschluss. Dasselbe Muster zeigt sich, wenn ein kalter Wintertag als Argument gegen die Erwärmung der Erde ins Feld geführt wird: Ein kurzfristiger Eindruck wird zur Grundlage einer Entscheidung mit langem Zeithorizont, während die Langzeitdaten übergangen werden. Die anderen Varianten stützen sich dagegen auf Messreihen oder diskutieren sie, statt sie durch einen Momenteindruck zu ersetzen.","coreRule":"⚡ Kippt, wenn ein kurzer Eindruck Entscheidungen über Jahrzehnte begründen soll.","beleg":"Werkstück C.5.1 (Der Kipppunkt; Red Flags)","status":"entwurf","scenario":"In einer Gemeinde wird über den Bau eines Deiches gegen Hochwasser beraten. Ein Gemeinderat sagt: „Die letzten drei Wochen war es trocken. Wir können das Geld für den Deich sparen.“ Eine Nachbargemeinde dagegen stützt ihre Entscheidung auf Pegelmessungen und Niederschlagsstatistiken der letzten Jahrzehnte.","quote":"","quoteLabel":"","kurz":"Der Deichbau soll Jahrzehnte schützen, also muss sich die Entscheidung auf den langfristigen Trend stützen. Drei trockene Wochen sind Wetter, Klima ist der Durchschnitt über viele Jahre. Wer aus dem Momenteindruck den Verzicht ableitet, übergeht die Langzeitdaten.","prueffrage":"Über welchen Zeitraum liegen die Daten oder Eindrücke vor, auf die sich die jeweilige Entscheidung stützt?","rueckmeldung":[{"option":1,"text":"Sorgfältiges Auswerten wirkt zunächst wie Zögern, und Verschieben kann man kritisieren. Mit dem Wetter-Klima-Fehler hat das aber nichts zu tun: Die Langzeitdaten bleiben die Grundlage und werden nicht durch einen Momenteindruck ersetzt."},{"option":2,"text":"Hier liegt gerade kein Fehler vor, sondern das Gegenbeispiel: Der Beschluss stützt sich auf Messreihen über viele Jahre. Genau so sollte eine Entscheidung mit langem Zeithorizont begründet werden, statt mit dem Zustand weniger Wochen."},{"option":3,"text":"Einzelne Erfahrungsberichte ersetzen zwar keine Messreihen. Hier wird aber nur diskutiert, nicht entschieden, und es wird kein kurzfristiges Wetter gegen Langzeitdaten ausgespielt. Die Verwechslung von Wetter und Klima liegt woanders."}],"familie":"trend-statt-einzelfall","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"NOAA National Centers for Environmental Information: WMO Climate Normals","oeffentlich":true,"url":"https://ncei.noaa.gov/products/wmo-climate-normals","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"ad5a5273a584a26b"}},{"id":"qx-c2-038","clusterId":"C","werkstueckRef":"C.5.1","stufe":4,"question":"Ein Bekannter sagt: „Wenn Wärme immer vom Wärmeren zum Kälteren fließt, müsste sich der Temperaturunterschied zwischen Tropen und Polen längst aufgelöst haben, und es gäbe gar kein wechselhaftes Wetter mehr.“ Was ist an diesem Schluss fehlerhaft?","options":["Er übersieht, dass die Sonne den Unterschied jeden Tag neu schafft, sodass der Ausgleich nie fertig wird und gerade dadurch Wind und Wetter entstehen.","Er übersieht, dass Wolken in den Tropen Sonnenlicht ins All zurückwerfen, sodass dort weniger Energie ankommt, als man allein aus der Einstrahlung erwartet.","Er übersieht, dass die Ozeane große Wärmemengen aus den Tropen speichern, sodass sie das Gefälle abpuffern und die Luftbewegung dadurch eher beruhigen.","Er übersieht, dass die Erdachse geneigt ist, sodass im Jahresverlauf mal der Norden, mal der Süden stärker bestrahlt wird und die Jahreszeiten entstehen."],"correctIndex":0,"explanation":"Der Schluss tut so, als gäbe es nur einen einmaligen Ausgleich. In Wirklichkeit heizt die Sonne die Tropen Tag für Tag stärker als die Pole und schafft den Unterschied immer wieder neu. Wärme fließt vom Wärmeren zum Kälteren, Winde tragen sie polwärts und bauen den Unterschied ab, doch bevor er verschwunden ist, ist er schon wieder da. Dieser nie vollendete Ausgleich hält die Luftbewegung am Laufen und ist der Antrieb des Wettergeschehens (Kleidon 2012). Ein System, das ständig Energie von außen bekommt, kommt nicht zur Ruhe.","coreRule":"⚡ Wo ein Unterschied ständig neu entsteht, läuft der Ausgleich ständig weiter – und dieser Dauerlauf ist der Motor des Wetters.","beleg":"Werkstück C.5.1 (Die thermodynamische Grundlage); Fn. gl-c-kleidon (Kleidon 2012, Physik in unserer Zeit 43(3), S. 138–140)","status":"entwurf","scenario":"Die Sonne strahlt auf die Tropen stärker ein als auf die Pole. Wärme fließt von selbst vom Wärmeren zum Kälteren, und Winde tragen sie polwärts.","kurz":"Der Schluss behandelt den Ausgleich als einmaligen Vorgang. Die Sonne heizt die Tropen aber täglich stärker als die Pole und schafft den Unterschied immer wieder neu; dieser nie vollendete Ausgleich treibt Wind und Wetter an.","prueffrage":"Was müsste geschehen, damit Tropen und Pole am Ende tatsächlich gleich warm wären?","rueckmeldung":[{"option":1,"text":"Wolken werfen tatsächlich einen Teil des Sonnenlichts zurück. Doch die Tropen bekommen trotzdem mehr Energie als die Pole, und der Einwand erklärt nicht, warum der Unterschied immer wieder neu entsteht."},{"option":2,"text":"Ozeane speichern viel Wärme und dämpfen Unterschiede, das stimmt. Sie liefern aber keine neue Energie, die das Gefälle erneuert; den Fehler im Schluss trifft das nicht."},{"option":3,"text":"Die Neigung der Erdachse erzeugt die Jahreszeiten, das trifft zu. Sie erklärt jedoch nicht, warum der Unterschied zwischen Tropen und Polen trotz des laufenden Ausgleichs bestehen bleibt."}],"familie":"systemisch-denken","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"NOAA: Global Atmospheric Circulations","oeffentlich":true,"url":"https://noaa.gov/node/10334","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Kleidon, A. (2012): Was leistet die Erde? Physik in unserer Zeit 43(3), 136–144 (doi 10.1002/piuz.201201294)","oeffentlich":false}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"63e1ee870faa0de8"}},{"id":"qx-c2-039","clusterId":"C","werkstueckRef":"C.5.2","stufe":1,"question":"Wie lässt sich am besten erklären, dass die Freundin ein Ungeheuer gesehen hat, obwohl es nur Otter waren?","scenario":"Eine Freundin schickt dir ein wackeliges, herangezoomtes Handyvideo von einem nebligen See: Ein dunkler, langer Schatten mit seltsamen Höckern bewegt sich durchs Wasser. Sie ist überzeugt: „Das ist ein Seeungeheuer, ich habe es mit eigenen Augen gesehen.“ Später stellt sich heraus, dass drei Otter hintereinander geschwommen sind.","options":["Das Auge hat unvollständige, verzerrte Daten geliefert, und das Gehirn hat die Lücken mit Erwartungen und Vorwissen gefüllt, hier mit einem Ungeheuer.","Die Erinnerung hat sich beim Erzählen verändert, sodass aus den drei Ottern nachträglich ein Ungeheuer wurde; beim Sehen selbst war noch alles richtig.","Die Freundin hat das Video bewusst zugespitzt, weil ein Seeungeheuer mehr Aufmerksamkeit bringt als drei Otter, und wollte andere damit beeindrucken.","Das Gehirn hat im Nebel ohne äußeren Reiz ein Bild erzeugt, wie bei einer Halluzination, und die Freundin hielt dieses innere Bild für die Wirklichkeit."],"correctIndex":0,"explanation":"Das Auge hat nicht gelogen, es hat Licht empfangen. Die Deutung kommt vom Gehirn, das unvollständige, verzerrte Daten mit Erwartungen und Vorwissen ergänzt; an einem nebligen See, um den sich Geschichten über Seeungeheuer ranken, kann daraus ein Monster werden. Dazu kommen Nebel, Wellenbewegung und die geringe Auflösung einer Zoom-Kamera, wodurch drei einzelne Tiere zu einer einzigen seltsamen Gestalt verschmelzen können. Die Behauptung „mit eigenen Augen gesehen“ beweist deshalb wenig: Was wir sehen, ist schon im Moment des Sehens eine Deutung der Daten, nicht erst in der Erinnerung. Dass Erinnerungen sich verändern, stimmt, doch hier geht es um das Sehen im Moment selbst, die Freundin war schon dabei überzeugt. Dass Menschen übertreiben, um aufzufallen, kommt vor, aber die Freundin ist überzeugt und nicht berechnend. Und es gab einen echten äußeren Reiz, nämlich die drei Otter, also keine Halluzination.","coreRule":"⚡ Sehen ist Interpretieren, nicht Aufzeichnen: Bei unklaren Daten füllt das Gehirn die Lücken mit der erwarteten Geschichte.","quote":"","quoteLabel":"","beleg":"Werkstück C.5.2 (Das Monster auf dem See; Kernidee)","status":"entwurf","kurz":"Das Auge hat Licht empfangen, die Deutung kommt vom Gehirn. Aus verzerrten, unvollständigen Daten hat es mit Vorwissen ein Ungeheuer gemacht. „Mit eigenen Augen gesehen“ ist daher schon im Moment des Sehens eine Deutung und beweist wenig.","prueffrage":"Wie gut waren Sicht, Entfernung und Bildqualität, und wie viel davon war tatsächlich zu erkennen?","rueckmeldung":[{"option":1,"text":"Erinnerungen verändern sich beim Erzählen tatsächlich, nur gehört das nicht hierher. Die Freundin war schon im Moment des Sehens überzeugt, die Deutung entstand also nicht erst nachträglich."},{"option":2,"text":"Übertreibung, um aufzufallen, kommt vor. Hier spricht aber nichts dafür: Die Freundin ist ehrlich überzeugt. Ihr Irrtum liegt in der Wahrnehmung selbst, nicht in einer Absicht, andere zu beeindrucken."},{"option":3,"text":"Eine Halluzination entsteht ohne äußeren Reiz. Hier war aber etwas da: drei echte Otter. Das Gehirn hat dieses unscharfe Bild falsch gedeutet und nicht aus dem Nichts eines erzeugt."}],"familie":"erinnerung-ist-rekonstruktion","fertigkeit":"F5","quellen":[{"typ":"doi","kurz":"Gregory, R. L. (1997): Knowledge in perception and illusion. Philosophical Transactions of the Royal Society B 352(1358), 1121–1127","oeffentlich":true,"doi":"10.1098/rstb.1997.0095","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC1692018/","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"73a301a874115ad3"}},{"id":"qx-c2-040","clusterId":"C","werkstueckRef":"C.5.2","stufe":2,"question":"Welche Erklärung dieser „Orbs“ ist die sparsamste und lässt sich mit einem einfachen Test am besten prüfen?","scenario":"Du fotografierst mit Blitz in einer staubigen Dachkammer und siehst auf dem Bild runde, leuchtende Kugeln, die du vorher nicht bemerkt hast. Jemand sagt: „Das sind Geister.“","options":["Das Blitzlicht wird von nahen Staubpartikeln zurückgeworfen; in staubfreier Luft oder ohne Blitz erscheinen dieselben Kugeln nicht.","In der Dachkammer entstehen bei wenig Licht helle Rauschpunkte im Sensor, die sich zu Kugeln verdichten; bei niedriger Empfindlichkeit fehlen sie.","Temperaturunterschiede in der Dachkammer lassen die Luft flimmern und brechen das Licht zu Kugeln; ohne solche Unterschiede erscheinen sie nicht.","Streulicht im Objektiv erzeugt runde Blendenflecke, sobald eine helle Lichtquelle ins Bild strahlt; mit aufgesetzter Streulichtblende fehlen sie."],"correctIndex":0,"explanation":"Die sparsamste Erklärung nutzt nur bekannte Optik und lässt sich einfach testen: Das Blitzlicht der Kamera wird von nahen, unscharfen Staub- oder Feuchtigkeitspartikeln reflektiert (Backscatter) und erscheint als helle Kugel. Wiederholst du dasselbe Foto in staubfreier Luft oder ohne Blitz, sollten die Kugeln verschwinden. Helle Rauschpunkte entstehen bei wenig Licht, hier aber hat der Blitz die Szene hell ausgeleuchtet. Luftflimmern durch Temperaturunterschiede verzerrt Bilder, erzeugt aber keine Kugeln vor der Linse. Blendenflecke im Objektiv brauchen eine helle Lichtquelle im Bild, die hier nicht vorkommt. „Geister“ dagegen setzt etwas Neues voraus, für das es hier keinen Beleg gibt. Ein einzelnes Foto beweist deshalb keine Geistererscheinung.","coreRule":"⚡ Wenn eine bekannte Ursache ein Bild vollständig erklärt und sich testen lässt, brauchst du keine übernatürliche Erklärung.","beleg":"Werkstück C.5.2 (Anwendung & Relevanz, Bei Geister-Fotografie)","status":"entwurf","kurz":"Der Blitz leuchtet nahe Staubteilchen an, die als unscharfe helle Kugeln erscheinen; ohne Blitz oder bei staubfreier Luft sollten sie verschwinden. „Geister“ wären eine neue Annahme ohne Beleg, wo bekannte Optik schon reicht.","prueffrage":"Was ändert sich auf einem zweiten Foto derselben Stelle, wenn du nur eine Bedingung der Aufnahme veränderst?","rueckmeldung":[{"option":1,"text":"Sensorrauschen ist ein reales Phänomen, tritt aber bei wenig Licht auf. Hier hat der Blitz die Kammer hell ausgeleuchtet, außerdem ergibt Rauschen eher kleine, unregelmäßige Punkte als runde leuchtende Kugeln."},{"option":2,"text":"Luftflimmern durch Temperaturunterschiede gibt es wirklich, und es kann Bilder verzerren. Leuchtende Kugeln vor der Linse erzeugt es aber nicht, es verformt nur, was ohnehin im Bild ist."},{"option":3,"text":"Blendenflecke im Objektiv sehen oft rund aus und lassen sich mit einer Streulichtblende prüfen. Sie brauchen aber eine helle Lichtquelle im Bild, und die kommt in der Dachkammer nicht vor."}],"familie":"bekannte-ursache-zuerst","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Society for Psychical Research, Psi Encyclopedia: Parsons, S.: Orbs (Light Anomalies)","oeffentlich":true,"url":"https://psi-encyclopedia.spr.ac.uk/articles/orbs-light-anomalies/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Schwartz, G. E.; Creath, K. (2005): Anomalous orbic „spirit“ photographs? A conventional optical explanation. Journal of Scientific Exploration 19(3), 343–358","oeffentlich":false}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"55f8b0811a3efa6d"}},{"id":"qx-c2-041","clusterId":"C","werkstueckRef":"C.5.2","stufe":3,"question":"Was ist an diesem Schluss fehlerhaft?","scenario":"Jemand zeigt dir ein unscharfes Nachtvideo eines leuchtenden Punkts, der sich am Himmel zu bewegen scheint, und sagt: „Ich kann mir nicht erklären, was das ist – also muss es außerirdisch sein.“","options":["Der Schluss dreht sich im Kreis: Das Video gilt als Beweis für Außerirdische, und die Außerirdischen gelten wiederum als Beweis dafür, dass das Video echt ist.","Der Schluss deutet in einen Punkt zu viel hinein: Er wird als Gesicht oder Gestalt gelesen, obwohl das Bild gar nichts Erkennbares zeigen kann.","Der Schluss überschätzt die Häufigkeit solcher Ereignisse: Wer gerade eine Dokumentation über Ufos gesehen hat, hält echte Sichtungen für alltäglicher, als sie sind.","Der Schluss macht aus einer Erklärungslücke einen Beleg: Aus „ich kann es nicht erklären“ wird „außerirdisch“, obwohl naheliegendere Erklärungen gar nicht geprüft wurden."],"correctIndex":3,"explanation":"Dass jemand etwas nicht erklären kann, sagt etwas über sein Wissen aus, nicht über das Objekt. Bei unscharfen Nachtaufnahmen gibt es viele alltägliche Erklärungen: Flugzeuge, Satelliten wie Starlink, Ballons oder Drohnen werden ohne Referenzobjekte leicht falsch eingeschätzt, Linsenreflexionen (Lens Flares) wirken wie eigenständige Lichter, und Luftturbulenzen lassen Lichtpunkte flackern oder wandern. Solange diese Möglichkeiten nicht ausgeschlossen sind, trägt der Sprung zur aufregendsten Erklärung nicht. Eine passende Prüffrage lautet: Welche bekannten Gesetze der Optik, der Perspektive oder der Kameratechnik könnten das Gesehene ebenfalls vollständig erklären?","coreRule":"⚡ Eine Erklärungslücke ist kein Beleg für die aufregendste Erklärung.","beleg":"Werkstück C.5.2 (Anwendung & Relevanz, Bei der Ufologie; Red Flags)","status":"entwurf","kurz":"Dass jemand etwas nicht erklären kann, sagt etwas über sein Wissen, nicht über das Objekt. Bei unscharfen Nachtaufnahmen kommen viele alltägliche Erklärungen infrage; solange sie nicht ausgeschlossen sind, trägt der Sprung zur spektakulärsten nicht.","prueffrage":"Was müsste man über Ort, Uhrzeit und Blickrichtung der Aufnahme wissen, um den Lichtpunkt bestimmen zu können?","rueckmeldung":[{"option":0,"text":"Ein Zirkelschluss setzt voraus, was er beweisen will, etwa wenn Video und Außerirdische sich gegenseitig stützen. Hier wird aber nur von „unerklärlich“ auf „außerirdisch“ gesprungen, also von einer Lücke zu einer Erklärung, nicht im Kreis."},{"option":1,"text":"Bei so wenig Bildinformation wird tatsächlich schnell etwas hineingedeutet. Hier ist aber von einem leuchtenden Punkt die Rede, nicht von einer erkannten Gestalt. Der Fehler liegt im Schluss von „unerklärt“ auf „außerirdisch“."},{"option":2,"text":"Medien können beeinflussen, wie häufig uns etwas erscheint. Davon ist hier aber keine Rede: Der Schluss stützt sich nicht auf eine Häufigkeitseinschätzung, sondern auf die eigene Ratlosigkeit."}],"familie":"unwissen-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Office of the Director of National Intelligence (2021): Preliminary Assessment: Unidentified Aerial Phenomena","oeffentlich":true,"url":"https://archive.dni.gov/files/ODNI/documents/assessments/Prelimary-Assessment-UAP-20210625.pdf","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"455238f8111a1b04"}},{"id":"qx-c2-042","clusterId":"C","werkstueckRef":"C.5.2","stufe":4,"question":"Welcher Einwand trifft den Schluss von Herrn K. am besten?","options":["Er geht von geradliniger Lichtausbreitung aus. Temperaturschichten, Wasserdampf und Turbulenzen brechen das Licht aber, sodass Objekte am Horizont höher erscheinen können, als sie sind.","Er zählt nur die Tage, an denen das Hochhaus sichtbar war, und blendet Tage ohne Sicht aus. Dieser Bestätigungsfehler lässt ihn jede Sichtung als Beweis gegen die Krümmung lesen.","Er bekämpft einen Strohmann: Mit dem Hochhaus widerlegt er die überzogene Behauptung, hinter dem Horizont sei nie etwas zu sehen, statt die Erdkrümmung selbst zu prüfen.","Er stützt sich auf die Autorität einer Fachperson, die das Hochhaus als sichtbar bestätigt haben soll, ohne deren Aussage zu prüfen. Autorität ersetzt aber keine eigene Messung."],"correctIndex":0,"explanation":"Sein Schluss hängt an einer stillschweigenden Annahme: dass Licht in der Luft schnurgerade verläuft. Tatsächlich brechen Temperaturschichten, Wasserdampf und Turbulenzen das Licht; schon bei gewöhnlicher Schichtung lässt diese Brechung (Refraktion) Objekte am Horizont etwas höher erscheinen und gleicht die Krümmung teilweise aus, und liegt warme Luft über kaltem Wasser, kann sie sogar Teile sichtbar machen, die nach geradliniger Rechnung ganz verdeckt wären. Das Flimmern und die Verschiebung in seiner Beobachtung passen zu solchen Verzerrungen, ähnlich wie bei einer Fata Morgana. Wer aus „Ich sehe mehr, als meine Rechnung erlaubt“ schließt, die Erde sei nicht gekrümmt, prüft also die eigene Rechnung nicht, die die Brechung außer Acht lässt. Die anderen Einwände nennen bekannte Denkfehler, die hier aber nicht vorliegen: Herr K. beschreibt einen klaren Tag und hat nachgerechnet, von einer Auswahl günstiger Tage ist keine Rede, also liegt kein Bestätigungsfehler vor. Er greift auch keine überzogene Gegenposition an, sondern zieht eine eigene Folgerung. Und eine Fachperson, auf deren Autorität er sich stützt, kommt im Szenario gar nicht vor.","coreRule":"⚡ Wer weit sieht, muss die Brechung der Luft mitrechnen: Eine Beobachtung widerlegt eine Theorie erst, wenn alle bekannten Störeinflüsse in der Rechnung berücksichtigt sind.","beleg":"Werkstück C.5.2 (Kontext & Tiefe, Atmosphärische Verzerrung; Anwendung & Relevanz, Bei der Flache-Erde-Theorie)","status":"entwurf","scenario":"Herr K. steht an einem klaren Tag an einer Küste und sieht ein Hochhaus, das 40 Kilometer entfernt am Horizont liegt. Er hat grob nachgerechnet: Bei einer gekrümmten Erde müsste der untere Teil des Gebäudes hinter dem Horizont verborgen sein. Er sieht aber mehr davon, als seine Rechnung erlaubt, wenn auch etwas flimmernd und leicht verschoben. Er schließt: „Die Erde ist nicht gekrümmt, sonst könnte ich das sehen.“","quote":"","quoteLabel":"","kurz":"Herr K. nimmt an, Licht verlaufe in der Luft schnurgerade. Temperaturschichten, Wasserdampf und Turbulenzen brechen es aber und heben Objekte am Horizont scheinbar an. Er prüft deshalb nicht seine Rechnung, sondern verwirft die Krümmung.","prueffrage":"Wie hoch steht Herr K. über dem Wasser, und wie viele Meter des Gebäudes müssten nach seiner Rechnung verdeckt sein?","rueckmeldung":[{"option":1,"text":"Eine einzelne Sichtung als Beweis zu lesen, wäre tatsächlich zu wenig. Das Szenario nennt aber nur einen klaren Tag und keine Auswahl günstiger Tage; die Schwäche steckt in seiner Rechnung."},{"option":2,"text":"Ein Strohmann setzt voraus, dass jemand eine übertriebene Gegenposition widerlegt. Herr K. widerlegt aber niemanden, sondern folgert aus seiner eigenen Beobachtung, und eine Gegenposition kommt im Szenario gar nicht vor."},{"option":3,"text":"Eigene Messungen statt bloßer Autorität zu fordern, ist ein guter Grundsatz. Hier passt er nur nicht, denn Herr K. beruft sich auf keine Fachperson, sondern auf das, was er selbst sieht und berechnet."}],"familie":"bekannte-ursache-zuerst","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Georgia State University, HyperPhysics: Atmospheric Refraction","oeffentlich":true,"url":"https://hyperphysics.gsu.edu/hbase/atmos/mirage.html","abruf":"2026-10-12"},{"typ":"url","kurz":"Young, A. T. (San Diego State University): Looming, Towering, Stooping, and Sinking","oeffentlich":true,"url":"https://aty.sdsu.edu/mirages/mirsims/loom/loom.html","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"790f64dc7fb13917"}},{"id":"qx-c2-043","clusterId":"C","werkstueckRef":"C.5.3","stufe":1,"question":"Ein Bekannter zeigt dir ein Foto eines langen Streifens hinter einem Flugzeug und sagt: „Das sind Chemikalien, die da versprüht werden. Aus Kerosin entsteht ja nichts, was einen weißen Streifen bilden könnte.“ Welche Überlegung prüft diese Behauptung am besten?","options":["Man fragt, was bei der Verbrennung von Kerosin entsteht: Kohlendioxid und heißer Wasserdampf, der in der eiskalten Höhenluft zu Eiskristallen gefriert, wie unser Atem an einem Wintertag.","Man fragt, wie lange der Streifen am Himmel bleibt: Hält er sich länger als wenige Minuten, kann er nicht aus Wasserdampf bestehen, der in der kalten Höhenluft gefriert.","Man fragt, wie viel Ruß das Triebwerk ausstößt: Ohne Rußpartikel als Kondensationskerne könnte in der eiskalten Höhenluft gar kein Streifen aus Eiskristallen entstehen.","Man fragt, wie viel Kerosin das Flugzeug in zehn Kilometern Höhe verbrennt: Aus der Treibstoffmenge lässt sich ablesen, ob ein so langer Streifen allein aus dem Abgas stammt."],"correctIndex":0,"explanation":"Wie in unserem Atem entstehen bei der Verbrennung vor allem Kohlendioxid und Wasser. In etwa zehn Kilometern Höhe ist es oft kälter als −40 °C: Der heiße Wasserdampf kondensiert zu winzigen Tröpfchen, die rasch zu Eiskristallen gefrieren. Die Behauptung „aus Kerosin entsteht nichts Sichtbares“ ist damit widerlegt, ganz ohne Zusatzstoffe. Rußpartikel aus dem Triebwerk können als Kondensationskerne dienen, nötig sind sie aber nicht, denn die Luft enthält ohnehin genug Partikel. Eine gute Prüffrage fragt nach der einfachsten Erklärung, die schon bekannte Zutaten und Bedingungen nutzt, bevor man ein geheimes Programm annimmt. Die anderen Fragen klingen sinnvoll, klären hier aber nichts: Wie lange ein Streifen bleibt, hängt von der Feuchte der Umgebungsluft ab und nicht davon, woraus er besteht. Ruß ist als Kondensationskern hilfreich, aber nicht nötig. Die Treibstoffmenge sagt etwas über die Menge des Abgases, nicht über dessen Zusammensetzung.","coreRule":"⚡ Bevor du einen Zusatzstoff annimmst: Prüfe, ob die bekannten Zutaten und Bedingungen das Phänomen schon erklären.","beleg":"Werkstück C.5.3 (Kontext & Tiefe: Die Zutaten, Die Bedingungen)","status":"entwurf","scenario":"Ein Flugzeug fliegt in etwa zehn Kilometern Höhe, wo es oft kälter als −40 °C ist. Hinter ihm bleibt ein weißer Streifen zurück.","kurz":"Bei der Verbrennung von Kerosin entstehen Kohlendioxid und heißer Wasserdampf, der in der eisigen Höhenluft zu Eiskristallen gefriert, wie dein Atem im Winter. Der Fehler: Man nimmt ein geheimes Programm an, bevor man die bekannten Zutaten geprüft hat.","prueffrage":"Welche Stoffe und welche Bedingungen sind in dieser Höhe ohnehin vorhanden, und reichen sie für den Streifen schon aus?","rueckmeldung":[{"option":1,"text":"Die Dauer ist zwar beobachtbar, verrät aber nichts über die Zusammensetzung. Auch lange bleibende Streifen bestehen aus Eiskristallen; wie lange sie sich halten, hängt vor allem von der Feuchte der Umgebungsluft ab."},{"option":2,"text":"Ruß kann als Kondensationskern helfen, nötig ist er aber nicht, denn die Luft enthält ohnehin genug Partikel. Wer Ruß zur Bedingung macht, hält eine Hilfe fälschlich für eine Voraussetzung."},{"option":3,"text":"Die Treibstoffmenge sagt, wie viel Abgas entsteht, aber nicht, woraus es besteht. Gerade die Zusammensetzung steht hier aber in Frage, deshalb klärt die Menge nichts."}],"familie":"bekannte-ursache-zuerst","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"U.S. EPA: Information on Contrails from Aircraft","oeffentlich":true,"url":"https://www.epa.gov/regulations-emissions-vehicles-and-engines/Contrails","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Schumann, U. (1996): On conditions for contrail formation from aircraft exhausts. Meteorologische Zeitschrift 5(1), 4–23 (doi 10.1127/metz/5/1996/4)","oeffentlich":false}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"921abdc76002795c"}},{"id":"qx-c2-044","clusterId":"C","werkstueckRef":"C.5.3","stufe":2,"question":"Was ist an diesem Schluss fehlerhaft?","scenario":"Jemand zeigt dir eine Regenwasserprobe, in der Aluminium und Barium nachgewiesen wurden: „Das ist der Beweis für Sprühaktionen.“","options":["Der Schluss ist fehlerhaft, weil er aus einem zeitlichen Nacheinander auf eine Ursache schließt; was nach einem Überflug im Regen auftaucht, muss nicht von ihm stammen.","Der Schluss ist fehlerhaft, weil er sich auf Autorität statt auf Messwerte stützt; ein Hinweis auf bekannte Namen ersetzt keine Analyse der Probe.","Der Schluss ist fehlerhaft, weil ein Nachweis allein nichts zeigt; beide Elemente kommen überall in der Erdkruste vor und sind auch ohne Sprühaktionen zu erwarten.","Der Schluss ist fehlerhaft, weil er einen Strohmann aufbaut; er widerlegt eine überzogene Version der Gegenposition statt ihrer tatsächlichen Aussage."],"correctIndex":2,"explanation":"Ein Messwert sagt erst etwas, wenn man ihn mit dem Wert vergleicht, der ohnehin zu erwarten ist. Aluminium und Barium kommen überall in der Erdkruste vor und gelangen etwa mit Staub ins Regenwasser; ihr Nachweis passt deshalb auch ohne Sprühaktionen und spricht nicht für sie. Entscheidend wäre, ob die Mengen deutlich über dem üblichen Gehalt liegen, und daran ändern auch weitere Proben mit bloßem Nachweis nichts. Das stützt auch ein Befund aus der Fachwelt: Shearer u. a. (2016) befragten 77 Fachleute für Kondensstreifen und Staubablagerung; 76 hatten nie einen Beleg für ein geheimes Sprühprogramm gesehen; die vorgelegten Messwerte hielt die große Mehrheit der befragten Ablagerungs-Fachleute für gewöhnlich erklärbar. Ein zeitliches Nacheinander, das man mit einer Ursache verwechseln könnte, wird im Szenario nicht behauptet. Der Schluss beruft sich auch nicht auf eine Autorität, sondern auf einen Messwert, dessen Erwartungswert nicht geprüft wurde. Und eine Gegenposition wird nicht verzerrt wiedergegeben, denn niemand wird hier widerlegt.","coreRule":"⚡ Ein Messwert ohne den Vergleich mit dem natürlichen Gehalt beweist nichts.","beleg":"Werkstück C.5.3 (Red Flags); Fn. gl-c-shearer (Shearer u. a. 2016, Environ. Res. Lett. 11(8), Art. 084011)","status":"entwurf","kurz":"Ein Nachweis sagt nur etwas, wenn man ihn mit dem ohnehin zu erwartenden Wert vergleicht. Aluminium und Barium kommen in der Erdkruste überall vor und gelangen etwa mit Staub ins Regenwasser, der Nachweis spricht also nicht für Sprühaktionen.","prueffrage":"Wie viel Aluminium und Barium enthielt die Probe genau, und mit welchem Wert wurde das verglichen?","rueckmeldung":[{"option":0,"text":"Dass etwas im Regen auftaucht, muss nicht von einem Überflug stammen. Hier ist aber von keinem Überflug und keiner zeitlichen Abfolge die Rede; der Mangel liegt darin, dass der gemessene Wert nicht mit dem üblichen verglichen wird."},{"option":1,"text":"Bekannte Namen ersetzen keine Analyse, das stimmt. Hier beruft sich die Person aber auf keine Autorität, sondern auf einen Messwert, dessen zu erwartende Höhe schlicht nicht geprüft wurde."},{"option":3,"text":"Ein Strohmann setzt voraus, dass eine Gegenposition verzerrt wiedergegeben und dann widerlegt wird. Hier wird niemand widerlegt; es wird eine eigene Behauptung mit einem Messwert gestützt, der ohne Vergleichswert nichts zeigt."}],"familie":"dosis-entscheidet","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Shearer, C.; West, M.; Caldeira, K.; Davis, S. J. (2016): Quantifying expert consensus against the existence of a secret, large-scale atmospheric spraying program. Environmental Research Letters 11(8), 084011","oeffentlich":true,"doi":"10.1088/1748-9326/11/8/084011","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v6","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"c15214414d4c6f08"}},{"id":"qx-c2-045","clusterId":"C","werkstueckRef":"C.5.3","stufe":3,"question":"Wie solltest du ihren Plan beurteilen?","options":["„Ungiftig“ sagt nichts über die Klimawirkung; laut der Übersicht wärmen die Schleierwolken nach bestem Schätzwert stärker als das CO₂, auch wenn ihr Wert unsicherer ist.","„Ungiftig“ sagt nichts über die Klimawirkung; weil der Wert für die Schleierwolken aber so unsicher ist, sollte sie ihn ganz weglassen und nur das CO₂ der Flüge zählen.","„Ungiftig“ sagt nichts über die Klimawirkung; weil Schleierwolken aber nur hinter manchen Flügen entstehen, CO₂ hinter jedem, wiegt das CO₂ insgesamt dennoch schwerer.","„Ungiftig“ sagt hier tatsächlich alles: Die 57 mW/m² der Schleierwolken beschreiben bloß Wetter, das sich wieder ausgleicht, und keine dauerhafte Wirkung auf die Erdwärme."],"correctIndex":0,"explanation":"Die Freundin schließt von „ungiftig“ auf „folgenlos“ – ein Fehlschluss, denn Harmlosigkeit für die Gesundheit sagt nichts über die Wirkung auf die Strahlungsbilanz. Langlebige Kondensstreifen gehen in Schleierbewölkung über und beeinflussen, wie viel Wärme die Atmosphäre hält. Nach einer großen Bilanz (Lee u. a. 2021) ist diese Schleierbewölkung nach bestem Schätzwert der größte einzelne Erwärmungsbeitrag des Luftverkehrs, noch vor dessen CO₂: Für 2018 entfielen rund 57 mW/m² auf Kondensstreifen-Zirren und 34 auf CO₂. Der Wert für die Zirren ist allerdings deutlich unsicherer als der für CO₂, deshalb gehört er mit diesem Vorbehalt in den Vortrag. Ein unsicherer Wert ist aber kein Wert null, ihn wegzulassen verzerrt die Bilanz. Dass Schleierwolken nur hinter manchen Flügen entstehen, ist in den Zahlen schon enthalten, weil beide den gesamten Luftverkehr betreffen. Und als bloßes Wetter lassen sich die Schleierwolken nicht abtun, weil die Zahl gerade ihren Beitrag zur Erwärmung beziffert.","coreRule":"⚡ „Kein Gift“ heißt nicht „keine Wirkung“: Prüfe, welche Eigenschaft einer Sache für die Frage zählt.","beleg":"Werkstück C.5.3 (Der Kipppunkt); Fn. gl-c-lee (Lee u. a. 2021, Atmos. Environ. 244, Art. 117834)","status":"entwurf","scenario":"Deine Freundin plant einen Vortrag über Flugreisen und Klima. Sie hat gelernt, dass Kondensstreifen aus Wasserdampf und Eiskristallen bestehen und kein Gift enthalten, und will deshalb nur das CO₂ der Flüge behandeln. Du zeigst ihr eine Übersicht über den Erwärmungsbeitrag des gesamten Luftverkehrs im Jahr 2018: Schleierwolken, die aus langlebigen Kondensstreifen entstehen, rund 57 mW/m², CO₂ rund 34 mW/m². Dazu steht dort, dass der Wert für die Schleierwolken deutlich unsicherer ist als der für CO₂.","kurz":"Dass Kondensstreifen ungiftig sind, sagt nichts über ihre Wärmewirkung: Die Schleierwolken daraus wärmen nach bestem Schätzwert stärker als das CO₂. Weil ihr Wert unsicherer ist, gehört er mit Vorbehalt in den Vortrag.","prueffrage":"Welche Größe gibt die Übersicht für die Schleierwolken an, und ist das eine Aussage über Gesundheit oder über etwas anderes?","rueckmeldung":[{"option":1,"text":"Dass der Wert unsicherer ist, stimmt, und er gehört auch in den Vortrag. Ein unsicherer Wert ist aber nicht null: Wer ihn weglässt, verzerrt die Bilanz, statt sie vorsichtiger zu machen. Besser ist, ihn mit dem Vorbehalt zu nennen."},{"option":2,"text":"Schleierwolken entstehen tatsächlich nicht hinter jedem Flug. Dieser Unterschied steckt aber schon in den Zahlen, denn beide Werte betreffen den gesamten Luftverkehr 2018. Und nach bestem Schätzwert liegen die Schleierwolken mit 57 vor dem CO₂ mit 34 mW/m²."},{"option":3,"text":"Die 57 mW/m² nennen gerade den Beitrag der Schleierwolken zur Erwärmung, sie beschreiben also eine Wirkung auf die Strahlungsbilanz und kein bloßes Wetter. Nur dass Kondensstreifen aus Wasserdampf und Eis bestehen, ist richtig, sagt aber nichts über das Klima."}],"familie":"schluss-pruefen","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Lee, D. S. u. a. (2021): The contribution of global aviation to anthropogenic climate forcing for 2000 to 2018. Atmospheric Environment 244, 117834","oeffentlich":true,"doi":"10.1016/j.atmosenv.2020.117834","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7468346/","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"26ee97bd8f1df268"}},{"id":"qx-c2-046","clusterId":"C","werkstueckRef":"C.5.3","stufe":4,"question":"Was ist an diesem Einwand verkürzt und trägt den Schluss deshalb nicht?","scenario":"In einer Diskussion über Streifen am Himmel sagt jemand: „Wolken werden doch seit Jahren mit Chemikalien besprüht, das nennt man Cloud Seeding! Also stimmt die Sprühtheorie.“","options":["Der Einwand ist verkürzt: Er greift Zweifler an der Sprühtheorie persönlich an, statt auf ihre Gründe einzugehen, und ein Angriff auf Personen widerlegt keine Sachaussage.","Der Einwand ist verkürzt: Dass es Wolkenimpfung gibt, stimmt, doch sie wirkt nur örtlich und begrenzt, und daraus folgt kein Sprühprogramm hinter Kondensstreifen.","Der Einwand ist verkürzt: Er verlangt von Zweiflern den Beweis, dass über den Streifen nichts versprüht wird; wer etwas behauptet, muss es selbst belegen.","Der Einwand ist verkürzt: Cloud Seeding wird seit Jahren nur als Forschungsversuch erprobt und nirgends tatsächlich eingesetzt, sodass schon seine Voraussetzung nicht stimmt."],"correctIndex":1,"explanation":"Cloud Seeding gibt es wirklich: Dabei werden Stoffe wie Silberiodid gezielt in Wolken eingebracht, um Regen oder Schnee anzuregen. Manche Länder setzen es regelmäßig ein, doch es wirkt nur örtlich, und sein Effekt ist begrenzt und oft schwer nachzuweisen. Der Einwand verwechselt damit zwei verschiedene Dinge: Dass ein bekanntes, örtlich begrenztes Verfahren existiert, sagt nichts darüber, was die langen Streifen hinter Flugzeugen sind. Dafür reicht die Physik: Heißer, feuchter Abgasdampf aus dem Triebwerk gefriert in der eiskalten Höhenluft zu Eiskristallen, und ob der Streifen kurz oder lange bleibt, hängt von der Feuchte der Umgebungsluft ab. Aus der Existenz eines realen, lokalen Verfahrens folgt kein globales Geheimprogramm. Ein persönlicher Angriff kommt im Einwand nicht vor, es wird niemand herabgesetzt. Eine Beweislast wird nicht umgekehrt, denn der Einwand fordert von niemandem einen Gegenbeweis. Und die Voraussetzung stimmt sogar, weil Cloud Seeding tatsächlich eingesetzt wird; verkürzt ist erst der Schluss auf die Streifen.","coreRule":"⚡ Ein reales, lokales Verfahren belegt kein globales Geheimprogramm.","beleg":"Werkstück C.5.3 (Verbindungen; Kontext & Tiefe)","status":"entwurf","kurz":"Cloud Seeding gibt es wirklich, wirkt aber nur örtlich und begrenzt. Dass ein solches Verfahren existiert, sagt nichts darüber, was die langen Streifen hinter Flugzeugen sind; aus „gibt es irgendwo“ folgt kein Sprühprogramm.","prueffrage":"Hinter welchen Flugzeugen entstehen die Streifen, und bei welchem Wetter bleiben sie lange am Himmel stehen?","rueckmeldung":[{"option":0,"text":"Im Einwand wird niemand angegriffen oder herabgesetzt; er stellt eine Sachbehauptung auf. Auch wenn ein Angriff auf Personen keine Aussage widerlegt, liegt das Problem hier woanders: im Sprung von einem bekannten Verfahren auf die Streifen."},{"option":2,"text":"Der Einwand verlangt von niemandem einen Gegenbeweis, es wird also keine Beweislast umgekehrt. Dass Behauptende belegen müssen, stimmt zwar, trifft aber hier nicht den Kern: Der Beleg, den er nennt, trägt die Folgerung nicht."},{"option":3,"text":"Cloud Seeding wird tatsächlich eingesetzt, manche Länder nutzen es regelmäßig. Die Voraussetzung des Einwands stimmt also. Verkürzt ist erst der Schluss: Das Verfahren wirkt nur örtlich und begrenzt und erklärt die Streifen nicht."}],"familie":"verschwoerung-pruefen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"World Meteorological Organization: WMO Statement on Weather Modification","oeffentlich":true,"url":"https://wmo.int/content/wmo-statement-weather-modification","abruf":"2026-10-12"},{"typ":"url","kurz":"U.S. EPA: Information on Contrails from Aircraft","oeffentlich":true,"url":"https://www.epa.gov/regulations-emissions-vehicles-and-engines/Contrails","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"98f279cdda0f6d3e"}},{"id":"qx-c2-047","clusterId":"C","werkstueckRef":"C.5.4","stufe":1,"question":"Der Bekannte sagt: „Dafür muss jedes Stockwerk einzeln gesprengt worden sein.“ Welche Überlegung zeigt am besten, was an diesem Schluss nicht trägt?","options":["Ein Gebäude trägt ein Mehrfaches seiner Last, weil Bauvorschriften Sicherheitsreserven verlangen; solche Reserven machen einen Einsturz ohne Fremdeinwirkung selten.","Ein aufprallender Block trägt weit mehr Energie, als das Element darunter aushält; so kann schon der Ausfall einer einzigen Stelle die ganze Kette auslösen.","Ein Verschwörungsglaube lässt sich kaum widerlegen, weil jeder Gegenbeleg als Teil des Plans gedeutet wird; seine Behauptung lässt sich deshalb nicht überprüfen.","Ein Zeitablauf von wenigen Sekunden lässt sich aus Aufnahmen nicht verlässlich ablesen, weil Perspektive und Bildrate die Dauer verfälschen können; die Angabe bleibt unsicher."],"correctIndex":1,"explanation":"Der Schluss „schnell und vollständig, also gesprengt“ übersieht eine einfachere Erklärung. Fällt ein Gebäudeteil auf die Struktur darunter, wird seine Lageenergie zu Bewegungsenergie, und beim Aufprall können Kräfte wirken, die ein Vielfaches der ruhenden Last betragen, für die das nächste Element ausgelegt ist. Übersteigt diese Belastung seine Tragreserve, versagt es, und der Block stürzt samt Trümmern mit noch mehr Masse weiter auf das nächste Element. So kann das Versagen an einer Stelle genügen, damit die Struktur nacheinander nachgibt, schnell und ohne weitere Eingriffe. Eine Sprengung ist dafür nicht nötig: Die vorhandene Physik erklärt das Ergebnis bereits (Ockhams Rasiermesser). Dass Gebäude Sicherheitsreserven haben, erklärt nicht, was geschieht, wenn eine solche Reserve überschritten wird. Dass sich ein Verschwörungsglaube schwer widerlegen lässt, sagt nichts über die Physik des Einsturzes. Und die Dauer von wenigen Sekunden steht im Szenario als gegeben fest.","coreRule":"⚡ Ein geschwächtes Element kann eine Kettenreaktion auslösen, die niemand mehr bremst: Tempo und Vollständigkeit eines Einsturzes sind noch kein Beleg für eine Sprengung.","beleg":"Werkstück C.5.4 (Der Stapel Bücher; Kernidee)","status":"entwurf","scenario":"Ein Bekannter sieht die Bilder vom Einsturz eines Hochhauses nach einem Brand. Der Einsturz dauerte nur wenige Sekunden und erfasste das ganze Gebäude, obwohl nur einige Stockwerke gebrannt hatten.","kurz":"Schnell und vollständig ist kein Beleg für eine Sprengung: Fällt ein Block auf die Struktur darunter, kann der Aufprall deren Tragreserve übersteigen, und die Kette setzt sich fort. Die Fehlschlussstelle ist, eine einfachere Erklärung zu übergehen.","prueffrage":"Wo begann der Einsturz auf den Bildern: in Höhe der brennenden Stockwerke oder an vielen Stellen zugleich?","rueckmeldung":[{"option":0,"text":"Sicherheitsreserven machen einen Einsturz ohne Fremdeinwirkung tatsächlich selten. Sie gelten aber für die ruhende Last und sagen nicht, was geschieht, wenn ein herabstürzender Block sie durch den Aufprall überschreitet."},{"option":2,"text":"Dass sich ein Verschwörungsglaube schwer widerlegen lässt, stimmt oft. Es sagt aber nichts darüber, ob ein Einsturz physikalisch auch ohne Sprengung ablaufen kann, und genau das müsste der Schluss des Bekannten entkräften."},{"option":3,"text":"Aufnahmen können Zeitangaben verfälschen, das kommt vor. Hier steht die Dauer von wenigen Sekunden aber als gegeben fest, und selbst eine andere Dauer würde nicht erklären, warum ein Versagen an einer Stelle zur Sprengung führen müsste."}],"familie":"bekannte-ursache-zuerst","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"NIST: FAQs – NIST WTC Towers Investigation","oeffentlich":true,"url":"https://www.nist.gov/world-trade-center-investigation/study-faqs/wtc-towers-investigation","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"af4368882d4bd4c2"}},{"id":"qx-c2-048","clusterId":"C","werkstueckRef":"C.5.4","stufe":2,"question":"Jemand sagt: „Das Hochhaus wurde von keinem Flugzeug getroffen und ist trotzdem komplett eingestürzt. Das kann nur eine Sprengung gewesen sein.“ Welche Überlegung prüft diese Behauptung am besten?","options":["Man prüft, ob Feuer allein genügt: Stundenlange Brände können Stahlträger ausdehnen und schwächen, bis eine kritische Stütze ihren Halt verliert und eine Einsturzkaskade auslöst. Ein Flugzeugeinschlag ist dafür nicht nötig.","Man prüft, ob sich die Behauptung überhaupt widerlegen ließe: Eine Aussage, die jeden Gegenbefund als Teil der Verschwörung umdeutet, taugt als Erklärung nicht, ganz gleich, wie plausibel sie wirkt.","Man prüft, wer vom Einsturz profitiert hätte: Wer ein Motiv für eine Tat hatte, ist verdächtig, und daraus lässt sich ableiten, ob eine Sprengung wahrscheinlicher ist als ein Brandschaden.","Man prüft, ob die Person selbst vom Fach ist: Nur wer Statik studiert hat, kann beurteilen, was ein Gebäude aushält, und deshalb entscheidet ihre Ausbildung über die Aussage."],"correctIndex":0,"explanation":"Die Behauptung tut so, als gäbe es nur Flugzeugeinschlag oder Sprengung. Stahl muss nicht schmelzen, um zu versagen: Bei 600 bis 800 °C verliert er über die Hälfte seiner Tragfähigkeit, und schon bei geringeren Temperaturen dehnt er sich deutlich aus. Nach der Untersuchung des NIST schoben sich ausdehnende Deckenträger einen Unterzug von seinem Auflager an einer tragenden Stütze; Decken brachen ein, die Stütze verlor ihre seitliche Halterung, knickte aus, und das Versagen pflanzte sich durch die Struktur fort. Weil die Sprinkler trocken blieben, wirkten die Brände stundenlang ungehindert; die Trümmerschäden spielten nach NIST für den Einsturz selbst kaum eine Rolle. Diese schon vorhandene Ursache erklärt den Einsturz ohne zusätzliche Sprengung. Nach NIST war es der erste bekannte Totaleinsturz eines Hochhauses vor allem durch Feuer, doch ungewöhnlich ist nicht dasselbe wie unerklärbar. Andere Prüfungen sind in anderer Lage nützlich, klären hier aber nichts: Ob die Behauptung widerlegbar ist, ist nachrangig, denn sie lässt sich anhand der Untersuchungsbefunde durchaus prüfen. Das Motiv möglicher Täter sagt nichts darüber, ob Feuer einen Stahlbau zum Einsturz bringen kann. Und die Ausbildung einer Person entscheidet nicht darüber, ob ihr Schluss trägt.","coreRule":"⚡ Hitze dehnt Stahl, und eine verrutschte Stütze genügt für die Kaskade.","beleg":"Werkstück C.5.4 (Kontext & Tiefe, Punkt 5 WTC 7); Fn. gl-c-nist (NIST NCSTAR 1A, 2008); Fn. gl-c-wtc7-freifall (NIST 2008, S. 45 und 48)","status":"entwurf","scenario":"Das Gebäude stand in der Nähe zweier Türme, die kurz zuvor eingestürzt waren. Es wurde von herabfallenden Trümmern getroffen, danach brannte es viele Stunden lang auf mehreren Etagen unkontrolliert. Die Sprinkler der unteren Stockwerke blieben trocken, weil die einstürzenden Türme die städtische Wasserleitung beschädigt hatten.","kurz":"Die Behauptung stellt nur Flugzeugeinschlag oder Sprengung zur Wahl, doch Stundenlanges Feuer ohne Löschwasser kann Stahl so schwächen und dehnen, dass die Struktur versagt. Dass der Einsturz ungewöhnlich war, heißt nicht, dass er unerklärbar ist.","prueffrage":"Welche Schäden hatte das Gebäude schon vor dem Einsturz, und welche davon wurden behoben, welche nicht?","rueckmeldung":[{"option":1,"text":"Widerlegbarkeit ist ein gutes Kriterium, wenn eine Aussage jeden Einwand wegerklärt. Hier lässt sich die Behauptung aber an den Untersuchungsbefunden prüfen, und genau das klärt, ob eine Sprengung nötig war."},{"option":2,"text":"Ein Motiv kann Ermittlungen lenken, wirkt deshalb aber auch aussagekräftig. Es sagt jedoch nichts darüber, was Feuer mit einem Stahlbau anrichten kann, und genau das ist hier die Frage."},{"option":3,"text":"Fachwissen kann beim Beurteilen von Statik helfen. Ob ein Schluss trägt, hängt aber nicht an der Ausbildung der Person, sondern daran, ob die Gründe und Belege ihn stützen, und die lassen sich prüfen."}],"familie":"bekannte-ursache-zuerst","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"NIST: FAQs – NIST WTC 7 Investigation","oeffentlich":true,"url":"https://www.nist.gov/world-trade-center-investigation/study-faqs/wtc-7-investigation","abruf":"2026-10-12"},{"typ":"url","kurz":"NIST: FAQs – NIST WTC Towers Investigation (Festigkeitsverlust von Stahl)","oeffentlich":true,"url":"https://www.nist.gov/world-trade-center-investigation/study-faqs/wtc-towers-investigation","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"6b199cb9b852d4b8"}},{"id":"qx-c2-049","clusterId":"C","werkstueckRef":"C.5.4","stufe":3,"question":"Jemand sagt: „Das Dach von WTC 7 ist beim Einsturz im freien Fall gefallen. Das geht nur mit Sprengstoff, weil sonst jedes Stockwerk Widerstand geleistet hätte.“ Welche Prüfung klärt, ob das den Schluss auf eine Sprengung trägt?","options":["Du prüfst, ob der Freifall den ganzen Einsturz betraf oder nur einen Teilabschnitt, und ob dieser Abschnitt auch ohne Sprengstoff erklärbar ist.","Du prüfst, ob der Clip, der das Dach im Fall zeigt, unbearbeitet ist, weil nur ungeschnittenes Material eine verlässliche Aussage über den Ablauf erlaubt.","Du prüfst, wem die Sprengungsthese nützen würde, weil das Motiv der Person verrät, ob ihre Aussage über den Freifall der Stützen zutrifft.","Du prüfst, ob die Person den Einsturz selbst miterlebt hat, weil nur Augenzeugen beurteilen können, ob die Stützen vorher gesprengt wurden."],"correctIndex":0,"explanation":"Der Schluss „Freifall, also Sprengung“ setzt voraus, dass der Freifall den ganzen Einsturz betraf und nur durch Sprengstoff möglich ist. Beides lässt sich prüfen. Gemessen wurde: Die Dachlinie brauchte für 18 Stockwerke rund 5,4 Sekunden, im freien Fall wären es 3,9 Sekunden gewesen, also rund 40 Prozent länger. Nur die Nordfassade fiel etwa 2,25 Sekunden lang über rund acht Stockwerke mit Erdbeschleunigung. In dieser Phase trugen die zuvor ausgeknickten Außenstützen sie praktisch nicht mehr, es gab also kaum Widerstand. Ein kurzer Freifall-Abschnitt folgt damit schon aus einem Einsturz durch Feuer und beweist keinen Sprengstoff. Wer den Teilabschnitt zum ganzen Einsturz verallgemeinert und die einfachere Erklärung nicht prüft, schließt zu weit.","coreRule":"⚡ Ein kurzer Freifall-Abschnitt ist kein Fingerabdruck für Sprengstoff: Prüfe, wie lange und woran er galt, bevor du auf die Ursache schließt.","beleg":"Werkstück C.5.4 (Kontext & Tiefe, Punkt 5); Fn. gl-c-wtc7-freifall (NIST 2008, NCSTAR 1A, S. 45 und 48)","status":"entwurf","scenario":"In einer Diskussion über den Einsturz von WTC 7 wird ein Videoclip gezeigt, in dem das Gebäude in wenigen Sekunden in sich zusammenfällt. Die Person behauptet, jeder Fall mit Erdbeschleunigung beweise, dass die Stützen vorher gezielt gesprengt wurden.","kurz":"Der Schluss „Freifall, also Sprengung“ trägt nur, wenn der Freifall den ganzen Einsturz betraf und nur Sprengstoff ihn erklärt. Gemessen fiel aber nur ein Teilabschnitt so schnell, und für ihn gibt es eine Erklärung ohne Sprengstoff.","prueffrage":"Wie lange dauerte der Einsturz der Dachlinie von WTC 7 laut Messung, und wie lange hätte ein freier Fall aus derselben Höhe gedauert?","rueckmeldung":[{"option":1,"text":"Dass ein Clip echt und ungeschnitten ist, ist eine sinnvolle Grundfrage bei jedem Video. Hier hilft sie aber nicht weiter: Auch unbearbeitetes Material sagt nicht, ob ein Freifall-Abschnitt Sprengstoff belegt."},{"option":2,"text":"Wem eine These nützt, kann Anlass sein, genauer hinzusehen. Das Motiv sagt aber nichts über den Ablauf des Einsturzes und lässt offen, ob die Messwerte und der Schluss daraus stimmen. Das lässt sich nur am Geschehen selbst klären."},{"option":3,"text":"Wer dabei war, kann viel erzählen, doch ob aus einem kurzen Freifall-Abschnitt auf Sprengstoff geschlossen werden darf, ist eine Frage von Messung und Schlusslogik. Auch Augenzeugen sehen keine Sekundenbruchteile und Stockwerke im Detail."}],"familie":"bekannte-ursache-zuerst","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"NIST: FAQs – NIST WTC 7 Investigation","oeffentlich":true,"url":"https://www.nist.gov/world-trade-center-investigation/study-faqs/wtc-7-investigation","abruf":"2026-10-12"},{"typ":"doi","kurz":"NIST (2008): Final Report on the Collapse of World Trade Center Building 7 (NCSTAR 1A)","oeffentlich":true,"doi":"10.6028/NIST.NCSTAR.1a","seite":"45, 48"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"fc89921572c64620"}},{"id":"qx-c2-050","clusterId":"C","werkstueckRef":"C.5.5","stufe":1,"question":"In einer Doku heißt es: „Die Wikinger in Grönland starben aus, weil sie dekadent und weniger anpassungsfähig waren als die Inuit.“ Du kennst folgende Fakten: Die Siedlungen bestanden fast 500 Jahre, ihre Energiebilanz war von Anfang an knapp, ab dem späten 13. Jahrhundert wurde das Klima unberechenbarer, der Meeresspiegel stieg und überflutete Weideland, das Walrosselfenbein verlor seinen Markt und die Schiffe aus Norwegen blieben aus. Welche Beurteilung wird dem am besten gerecht?","options":["Die Erklärung ist unvollständig: Sie führt das Ende auf Charakter zurück, obwohl mehrere harte Umstände zugleich wirkten.","Die Erklärung lässt sich nicht beurteilen: Ob ein Volk dekadent war, zeigen ohne eigene Aufzeichnungen weder Funde noch Quellen.","Die Erklärung ist überholt: Der Verlust des Elfenbeinmarktes allein erklärt das Ende, ein Charakterzug ist dafür nicht nötig.","Die Erklärung stimmt im Kern: Die Inuit überlebten im selben Land und erwiesen sich damit als anpassungsfähiger, was Dekadenz bestätigt."],"correctIndex":0,"explanation":"Der Vorwurf der Dekadenz erklärt das Ende durch einen vermuteten Charakterzug, ohne die Umstände zu prüfen. Dabei lagen mehrere harte Faktoren gleichzeitig vor: Von Anfang an war die Energiebilanz knapp, das Vieh allein konnte die Höfe nicht ernähren. Ab dem späten 13. Jahrhundert wurde das Klima unberechenbarer (nach neueren Seesedimenten vor allem trockener; ob auch kälter, ist umstritten), der Meeresspiegel stieg, der Markt für Walrosselfenbein brach weg und die Schiffe blieben aus. Gegen eine Charakterschwäche spricht schon die Dauer: Fast 500 Jahre hielten die Siedlungen durch. Als viele Belastungen zugleich zuschlugen, reichten die Reserven einer kleinen, isolierten Gemeinschaft nicht mehr. Auch lückenhafte Quellen heißen nicht, dass man nichts beurteilen kann: Man kann Erklärungen danach beurteilen, wie gut sie zu den bekannten Fakten passen. Und dass die Inuit überlebten, beweist keine Dekadenz der Wikinger: Sie übernahmen etwa die Eisjagd der Inuit nie, blieben europäische Viehzüchter und waren schließlich verwundbar.","coreRule":"⚡ Wer ein Scheitern mit einem Charakterfehler erklärt, ohne Umstände wie Energie, Klima und Handel zu prüfen, erklärt zu wenig.","beleg":"Werkstück C.5.5 (Die Wikinger in Grönland); Fn. gl-c-wikinger (Dugmore u. a. 2012, PNAS 109(10), S. 3658–3663); Fn. gl-c-davis (Janes in Hakluyt, Davis' erste Reise 1585)","status":"entwurf","scenario":"","kurz":"Die Doku erklärt das Ende durch einen vermuteten Charakterzug und prüft die Umstände nicht. Dabei wirkten Klima, Meeresspiegel, Marktverlust und ausbleibende Schiffe zugleich, und fast 500 Jahre Bestand sprechen gegen eine Charakterschwäche.","prueffrage":"Was müsste man über Menschen wissen, um sie dekadent zu nennen, und welche der bekannten Tatsachen sagen überhaupt etwas über ihr Verhalten?","rueckmeldung":[{"option":1,"text":"Direkte Zeugnisse über den Charakter fehlen tatsächlich. Lückenhafte Quellen heißen aber nicht, dass nichts zu beurteilen ist: Man kann Erklärungen danach prüfen, wie gut sie zu den bekannten Fakten passen, und die Dekadenz-These passt schlecht dazu."},{"option":2,"text":"Der Verlust des Elfenbeinmarktes belastete die Siedlungen wirklich. Er war aber nur einer von mehreren Faktoren; ihn allein zur Ursache zu machen, ersetzt nur eine einfache Erklärung durch die nächste."},{"option":3,"text":"Dass die Inuit im selben Land überlebten, stimmt. Daraus folgt aber keine Dekadenz der Wikinger: Sie blieben europäische Viehzüchter und übernahmen etwa die Eisjagd nie. Und fast 500 Jahre Bestand sprechen gegen eine Charakterschwäche."}],"familie":"umstaende-vor-absicht","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Dugmore, A. J. u. a. (2012): Cultural adaptation, compounding vulnerabilities and conjunctures in Norse Greenland. PNAS 109(10), 3658–3663","oeffentlich":true,"doi":"10.1073/pnas.1115292109","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3309771/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Zhao, B. u. a. (2022): Prolonged drying trend coincident with the demise of Norse settlement in southern Greenland. Science Advances 8(12), eabm4346","oeffentlich":true,"doi":"10.1126/sciadv.abm4346","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8942370/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Borreggine, M. u. a. (2023): Sea-level rise in Southwest Greenland as a contributor to Viking abandonment. PNAS 120(17), e2209615120","oeffentlich":true,"doi":"10.1073/pnas.2209615120","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC10151458/","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"023ed68ee65abfcf"}},{"id":"qx-c2-051","clusterId":"C","werkstueckRef":"C.5.5","stufe":2,"question":"Wie lässt sich am besten erklären, dass die Wikinger in Grönland nach fast 500 Jahren verschwanden, die Inuit aber überlebten?","options":["Sie passten sich nur teilweise an: Die Winterjagd der Nachbarn übernahmen sie nicht, daher fehlten ihnen bei mehreren Belastungen zugleich die Reserven.","Sie gerieten durch Klima und Meeresspiegel an eine Grenze: Gegen überflutete Küstenweiden hilft keine Anpassung, daher war ihr Ende unausweichlich.","Sie hingen vom Handel ab: Als ihr wichtigstes Handelsgut den Markt verlor und die Schiffe ausblieben, fehlte der Nachschub, daher brach die Siedlung zusammen.","Sie blieben zu europäisch: Statt ganz auf Robbenjagd umzustellen, hielten sie an Vieh und Höfen fest, daher hätte sie allein ein früherer Verzicht gerettet."],"correctIndex":0,"explanation":"Die Siedler waren keine Verlierer durch Dekadenz oder Unfähigkeit. Sie haben sich durchaus angepasst: Sie stellten auf gemeinschaftliche Robbenjagd um, und der Meeresanteil in ihren Knochen stieg im Lauf der Jahrhunderte von rund 40 auf rund 80 Prozent. Zugleich blieben sie Viehzüchter mit Höfen, Ställen und Steinkirchen, und die Eisjagd der Nachbarn, die Robben auch im Winter erreichbar machte, übernahmen sie nie. Ihre Energiebilanz war von Anfang an knapp. Als ab dem späten 13. Jahrhundert Klima, Meeresspiegel und Handel zugleich gegen sie liefen, reichten die Reserven einer kleinen, isolierten Gemeinschaft nicht mehr. Die Geografie setzte die Grenzen, aber die Kultur entschied mit, welche Anpassung die Siedler vollzogen und welche nicht. Wer nur die Umwelt oder nur den Charakter als Ursache nimmt, übersieht dieses Zusammenspiel.","coreRule":"⚡ Die Umwelt setzt die Grenzen, aber die Kultur entscheidet mit, welche Anpassung gelingt.","beleg":"Werkstück C.5.5 (Die Wikinger in Grönland; Der Kipppunkt); Fn. gl-c-wikinger (Dugmore u. a. 2012, PNAS 109(10), S. 3659–3662)","status":"entwurf","scenario":"Eine Siedlergemeinschaft aus Europa lebt rund 500 Jahre in der Arktis. Sie hält Vieh, baut Höfe und Steinkirchen und ist auf Heu angewiesen. Sie stellt auf gemeinschaftliche Robbenjagd um, bleibt dabei aber europäische Viehzüchterin. Als das Klima unberechenbarer wird, Küstenweiden überflutet werden, ihr wichtigstes Handelsgut seinen Markt verliert und die Schiffe ausbleiben, bricht die Siedlung zusammen. Ein Volk, das die Robben auch im Winter an Atemlöchern und Eiskanten jagt, lebt im selben Land weiter.","kurz":"Die Siedler stellten durchaus um, nahmen aber die Winterjagd der Nachbarn nie an. Als Klima, Meeresspiegel und Handel zugleich kippten, fehlten Reserven. Der Denkfehler wäre, nur die Umwelt oder nur den Charakter als Ursache zu sehen.","prueffrage":"Was änderten die Siedler im Lauf der Zeit an ihrer Nahrungssuche, und hielten sie danach weiter Vieh?","rueckmeldung":[{"option":1,"text":"Klima und Meeresspiegel setzten tatsächlich harte Grenzen. Aber im selben Land lebte ein Volk weiter, und die Siedler selbst passten sich zum Teil an. Die Umwelt allein macht ein Ende also nicht unausweichlich."},{"option":2,"text":"Der Handelsverlust gehört zu den Belastungen, aber er war nicht allein im Spiel: Auch Klima und überflutete Weiden setzten zu. Er erklärt zudem nicht, warum Nachbarn ohne diese Abhängigkeit weiterlebten."},{"option":3,"text":"Dass die Siedler Viehzüchter blieben, stimmt. Sie stellten aber durchaus um: Der Meeresanteil in ihren Knochen stieg von rund 40 auf rund 80 Prozent. Und mit Klima, Meeresspiegel und Handel wirkten mehrere Ursachen zusammen, nicht allein ihre Haltung."}],"familie":"monokausal-erkennen","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Dugmore, A. J. u. a. (2012): Cultural adaptation, compounding vulnerabilities and conjunctures in Norse Greenland. PNAS 109(10), 3658–3663","oeffentlich":true,"doi":"10.1073/pnas.1115292109","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3309771/","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v7","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"cecf43529f67426b"}},{"id":"qx-c2-052","clusterId":"C","werkstueckRef":"C.5.5","stufe":3,"question":"Ein Artikel behauptet: „Die Menschheit hat Holz durch Kohle, Kohle durch Öl und Öl nun durch Sonne und Wind ersetzt. Jede Stufe ist dichter und leistungsfähiger als die vorige.“ Was ist an dieser Behauptung fehlerhaft?","options":["Sie unterstellt, dass neue Energieträger die alten abgelöst haben, und sie übersieht, dass Sonne und Wind eine weit geringere Energiedichte haben als Kohle oder Öl.","Sie unterstellt, dass der Energieverbrauch überall gleich stark gewachsen ist, und sie übersieht die großen Unterschiede zwischen reichen und armen Ländern.","Sie unterstellt, dass jeder Energieträger das Klima gleich stark belastet, und sie übersieht, dass Kohle und Öl weit mehr CO₂ freisetzen als Wind und Sonne.","Sie unterstellt, dass die Vorräte an Energieträgern unbegrenzt sind, und sie übersieht, dass Kohle und Öl nur in endlicher Menge in der Erde lagern."],"correctIndex":0,"explanation":"Zwei Denkfehler stecken in der Behauptung. Erstens: Neue Energieträger sind meist hinzugekommen, statt alte zu ersetzen; Biomasse dominierte bis weit ins 19. Jahrhundert, und Kohle, Öl und Gas wurden dazugenommen, nicht eingetauscht. Zweitens: Die Reihe „immer dichter“ bricht beim letzten Glied, denn Sonnenstrahlung und Wind haben eine viel geringere Energiedichte als Kohle oder Öl. Die übrigen Gedanken sind für sich richtig, treffen aber nicht diese Behauptung: Über die regionale Verteilung des Verbrauchs sagt der Artikel nichts. Zur Klimawirkung der Träger äußert er sich nicht. Und von der Endlichkeit der Vorräte ist ebenfalls nicht die Rede.","coreRule":"⚡ Energiestufen addieren sich, sie ersetzen sich nicht – und nicht jedes Glied einer Reihe passt ins Muster.","beleg":"Werkstück C.5.5 (Kontext & Tiefe, Energie ist die Währung des Fortschritts); Fn. gl-c-energiestufen (Schabbach/Wesselak 2012, S. 56, 69 und 113–114)","status":"entwurf","scenario":"","quote":"","quoteLabel":"","kurz":"Neue Energieträger kamen meist hinzu, statt alte zu ersetzen, und die Reihe „immer dichter“ bricht bei Sonne und Wind, deren Energiedichte viel geringer ist. Der Fehler liegt in der Abfolge selbst, nicht in Verbrauch, Klima oder Vorräten.","prueffrage":"Welche Aussagen macht der Artikel wörtlich, und welche davon ließen sich mit Verbrauchszahlen oder Messwerten nachprüfen?","rueckmeldung":[{"option":1,"text":"Dass Verbrauch und Wohlstand weltweit sehr ungleich verteilt sind, stimmt. Der Artikel sagt dazu aber nichts, weder zum Wachstum noch zu Regionen. Geprüft werden muss, was er behauptet: die Abfolge der Träger und die steigende Dichte."},{"option":2,"text":"Dass Kohle und Öl mehr CO₂ freisetzen als Wind und Sonne, ist richtig. Davon handelt der Artikel jedoch gar nicht: Er behandelt weder Klimawirkung noch Belastung, sondern nur die Abfolge der Träger und ihre Dichte."},{"option":3,"text":"Kohle und Öl lagern tatsächlich nur in endlicher Menge in der Erde. Vorräte kommen im Artikel aber nicht vor, und seine Behauptung hängt nicht davon ab. Sie scheitert an der Ersetzungsreihe und an der Dichte."}],"familie":"schluss-pruefen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Our World in Data: Ritchie, H. (2021): How have the world’s energy sources changed over the last two centuries?","oeffentlich":true,"url":"https://ourworldindata.org/global-energy-200-years","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Schabbach, T.; Wesselak, V. (2012): Energie. Die Zukunft wird erneuerbar. Berlin/Heidelberg: Springer","oeffentlich":false}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"de71af5714c85446"}},{"id":"qx-c2-053","clusterId":"C","werkstueckRef":"C.5.5","stufe":4,"question":"Jemand sagt: „Die Geografie erklärt, warum manche Länder heute reich und andere arm sind. Eurasien hatte Weizen, Rinder und Pferde, Amerika hatte das nicht.“ Als Gegenargument wird angeführt: Zur Zeit der Eroberung verdiente ein Spanier wahrscheinlich weniger als das Doppelte eines Bewohners des Inkareichs, heute ist der durchschnittliche Spanier über sechsmal so reich wie der durchschnittliche Peruaner. Was folgt aus diesem Zahlenvergleich?","options":["Die Geografie erklärt auch die auf das Sechsfache gewachsene Kluft, weil der Vorsprung Eurasiens weiterwirkte; weitere Faktoren sind dafür kaum nötig.","Kulturelle Unterschiede erklären die Kluft besser als die Geografie, weil Institutionen aus den Wertvorstellungen einer Gesellschaft folgen.","Weil der Spanier anfangs nicht einmal das Doppelte verdiente, erklärt die Geografie schon den frühen Vorsprung nicht; sie spielt auch am Anfang kaum eine Rolle.","Die Geografie erklärt den frühen Vorsprung, nicht aber die später wachsende Kluft; dafür braucht es weitere Faktoren wie Institutionen."],"correctIndex":3,"explanation":"Der Abstand wuchs von weniger als dem Doppelten auf über das Sechsfache. Laut Acemoglu und Robinson liefert Diamonds Geografie-These einen plausiblen Ansatz für den Vorsprung Eurasiens zu Beginn der Neuzeit, erklärt aber nicht, warum sich der Abstand später immer weiter öffnete. Daraus folgt nicht, dass die Geografie keine Rolle spielt: Sie kann den Start erklären, etwa durch domestizierbare Pflanzen und Tiere in Eurasien. Der spätere Abstand verlangt zusätzliche Faktoren. Acemoglu und Robinson sehen sie in Institutionen, also Regeln, die Eigentum sichern, Neuerungen belohnen und die Mehrheit am Wirtschaftsleben beteiligen, oder solchen, mit denen Herrschende auf Kosten der Übrigen Gewinn ziehen. Diese Regeln entstehen in politischen Prozessen und sind kein vorherbestimmtes Ergebnis der Geografie; sie folgen auch nicht einfach aus den Wertvorstellungen einer Gesellschaft. Ein Vorsprung, der nur weiterwirkt, ließe den Abstand gleich bleiben, statt ihn zu vergrößern. Eine rein kulturelle Erklärung wird durch den Zahlenvergleich nicht belegt. Und ein anfangs kleinerer Abstand heißt nicht, dass es keinen Vorsprung gab; erst die Entwicklung danach lässt sich mit der Geografie nicht erklären.","coreRule":"⚡ Ein Faktor, der gleich bleibt, erklärt keine wachsende Kluft allein: Geografie erklärt oft den Start, Institutionen und andere Entscheidungen den späteren Abstand.","beleg":"Werkstück C.5.5 (Der Kipppunkt); Fn. gl-c-acemoglu (Acemoglu/Robinson 2013, Kap. 2, Abschnitt „Die Geographie-Hypothese“)","status":"entwurf","scenario":"","kurz":"Die Geografie erklärt den frühen Vorsprung Eurasiens plausibel, aber ein bloß weiterwirkender Vorsprung hielte den Abstand gleich. Er wuchs jedoch auf das Sechsfache. Daher verlangt die spätere Kluft zusätzliche Faktoren wie Institutionen.","prueffrage":"Was zeigt der Zahlenvergleich über den Abstand zwischen beiden Gruppen zu den zwei Zeitpunkten, und was zeigt er nicht?","rueckmeldung":[{"option":0,"text":"Ein Vorsprung, der einfach weiterwirkt, wirkt als Erklärung schlüssig. Dann bliebe der Abstand aber ungefähr gleich, statt von unter dem Doppelten auf über das Sechsfache zu wachsen. Für diese Öffnung braucht es weitere Faktoren."},{"option":1,"text":"Der Zahlenvergleich spricht gegen eine reine Geografie-Erklärung, belegt aber nicht, dass Kultur die bessere ist. Dass Institutionen einfach aus Wertvorstellungen folgen, stimmt so nicht: Sie entstehen in politischen Prozessen."},{"option":2,"text":"Dass der Abstand anfangs klein war, heißt nicht, dass es keinen Vorsprung gab. Die Geografie kann den Start erklären, etwa durch Weizen, Rinder und Pferde in Eurasien. Nur die spätere Kluft lässt sich damit nicht erklären."}],"familie":"monokausal-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Nobel Prize Outreach: Popular information – The Prize in Economic Sciences 2024","oeffentlich":true,"url":"https://www.nobelprize.org/prizes/economic-sciences/2024/popular-information/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Acemoglu, D.; Robinson, J. A. (2013): Warum Nationen scheitern. Frankfurt a. M.: S. Fischer, Kap. 2 „Die Geographie-Hypothese“","oeffentlich":false}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"3e386748bbef5b70"}},{"id":"qx-c2-054","clusterId":"C","werkstueckRef":"C.5.6","stufe":1,"question":"Eine Dokumentation zeigt: Eine ältere Frau ist in ihrem Wohnzimmer fast vollständig verbrannt, der Sessel ist zerstört, der Rest des Raumes kaum beschädigt. Im Film heißt es: „Es gab keine erkennbare Zündquelle, also muss sich die Frau von selbst entzündet haben.“ Welche Prüfung ist als Erstes sinnvoll?","options":["Prüfen, ob in Reichweite der Frau eine alltägliche Zündquelle wie Zigarette, Kerze oder Kamin stand und ob sie nur eingeschränkt beweglich war.","Prüfen, ob es weitere Fälle mit verbranntem Opfer und kaum beschädigtem Raum gibt, denn eine Häufung deutet auf eine noch unbekannte Ursache hin.","Prüfen, ob die Frau Alkohol oder Medikamente im Blut hatte, denn das könnte erklären, wie sich ihr Körper von selbst entzünden konnte.","Prüfen, ob der zerstörte Sessel leicht entflammbar war, denn das würde erklären, warum ohne erkennbare Zündquelle ein so heftiger Brand entstehen konnte."],"correctIndex":0,"explanation":"Aus „Ich sehe keine offensichtliche Ursache“ folgt nicht „Es gab keine Ursache“. Ein umgekippter Aschenbecher oder eine heruntergefallene Kerze reicht bereits. Die geringe Zerstörung der Umgebung spricht auch nicht gegen ein gewöhnliches Feuer: Wenn eine äußere Flamme die Haut einige Minuten erhitzt, brennt das schmelzende Unterhautfett im verkohlten Gerüst aus Haut und Kleidung wie bei einer umgedrehten Kerze über Stunden mit kleinen Flammen weiter. So wird der Körper stark zerstört, der Raum kaum. Ein Versuch von DeHaan und Nurbakhsh (2001) mit einem rund 95 Kilogramm schweren Schweinekadaver in einer Baumwolldecke zeigte genau das: Das Feuer hielt sich über 6,5 Stunden selbst am Leben. Erst die systematische Prüfung von Zündquelle, Brennstoff (Unterhautfett) und Beweglichkeit der Person zeigt, ob der Fall zum bekannten Dochteffekt-Muster passt, bevor man eine übernatürliche Erklärung erwägt. Weitere Fälle mit verbranntem Opfer und kaum beschädigtem Raum zeigen nur, dass das Muster wiederkehrt; der Dochteffekt erklärt es ohne eine neue, unbekannte Ursache. Alkohol oder Medikamente im Blut machen einen Körper nicht entzündlich und setzten die Selbstentzündung schon als gegeben voraus. Dass der Sessel leicht brennt, ersetzt keine Zündquelle und erklärt nicht, warum der Raum kaum beschädigt ist.","coreRule":"⚡ „Keine offensichtliche Zündquelle“ heißt nicht „keine Zündquelle“: Erst suchen, dann „unerklärlich“ sagen.","beleg":"Werkstück C.5.6 (Kontext & Tiefe; Anwendung & Relevanz, Bei „spontaner menschlicher Selbstentzündung“)","status":"entwurf","scenario":"Ein Bekannter erzählt dir von einer Dokumentation und hält den Fall für ein Beispiel „spontaner Selbstentzündung“.","kurz":"Dass keine Zündquelle zu sehen ist, heißt nicht, dass es keine gab: Eine Zigarette, eine Kerze, dazu eine kaum bewegliche Person, und der Dochteffekt erklärt die starke Zerstörung bei kaum beschädigtem Raum.","prueffrage":"Was zeigen die Aufnahmen vom Tisch und vom Boden neben dem Sessel, und was weiß man über die Gewohnheiten der Frau?","rueckmeldung":[{"option":1,"text":"Weitere Fälle zeigen nur, dass sich das Muster wiederholt, nicht, wodurch es entsteht. Und der Dochteffekt erklärt gerade dieses Muster aus bekannten Ursachen, also braucht es dafür keine neue, unbekannte."},{"option":2,"text":"Alkohol oder Medikamente können einschränken, wie schnell sich jemand in Sicherheit bringt, machen den Körper aber nicht entzündlich. Die Prüfung nimmt die Selbstentzündung zudem schon als gegeben an."},{"option":3,"text":"Ein leicht brennbarer Sessel kann ein Feuer befeuern, ersetzt aber keine Zündquelle: Ohne Funken oder Flamme fängt auch er nicht an. Warum der Raum kaum beschädigt ist, erklärt das ebenfalls nicht."}],"familie":"bekannte-ursache-zuerst","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"DeHaan, J. D.; Nurbakhsh, S. (2001): Sustained Combustion of an Animal Carcass … J Forensic Sci 46(5):1076–1081 – PubMed-Abstract","oeffentlich":true,"url":"https://pubmed.ncbi.nlm.nih.gov/11569545/","abruf":"2026-10-12"},{"typ":"doi","kurz":"DeHaan, J. D.; Nurbakhsh, S. (2001): Sustained Combustion of an Animal Carcass … J Forensic Sci 46(5) (Volltext kostenpflichtig)","oeffentlich":false,"doi":"10.1520/JFS15101J"},{"typ":"url","kurz":"Christensen, A. M. (2000): Debunking the Spontaneous Human Combustion Myth. Masterarbeit, University of Tennessee (TRACE)","oeffentlich":true,"url":"https://trace.tennessee.edu/utk_gradthes/4133","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"4794bb39250b6b8c"}},{"id":"qx-c2-055","clusterId":"C","werkstueckRef":"C.5.6","stufe":2,"question":"Welche Erklärung ist die sparsamste, und was würdest du zuerst prüfen?","scenario":"Nach einem Wohnungsbrand sagt ein Gutachter: Der Rumpf der Person sei fast vollständig verbrannt, Arme, Beine und Kopf dagegen vergleichsweise unversehrt. Im Raum selbst gibt es nur mäßige Brandschäden. Ein Bekannter meint: „Wenn der Körper so ungleichmäßig brennt, muss ein besonderer Brandbeschleuniger im Spiel gewesen sein.“","options":["Der Rumpf enthält viel Unterhautfett, das schmilzt, von der Kleidung aufgesaugt wird und langsam weiterbrennt. Prüfen: Zündquelle, Kleidung, Fettanteil.","Ein Brandbeschleuniger wurde am Rumpf ausgebracht, sodass dieser in kurzer Zeit weit stärker brannte als der Rest. Prüfen: Rückstände, Kleidungsreste, Brandmuster.","Der Rumpf lag dem Brandherd am nächsten und war der Strahlungshitze länger ausgesetzt als Arme, Beine und Kopf. Prüfen: Lage des Körpers, Brandherd, Wärmestrahlung.","Unter dem Rumpf schwelte ein Polster, etwa von Sofa oder Matratze, und erhitzte ihn über Stunden von unten. Prüfen: Polstermöbel, Schwelspuren, Liegeposition."],"correctIndex":0,"explanation":"Ungleichmäßige Zerstörung ist kein Beweis für einen Brandbeschleuniger. Sie ist genau das, was die bekannte Verbrennungsphysik vorhersagt: Brennstoff ist das Unterhautfett, das durch Hitze schmilzt und von verkohlter Haut und Kleidung wie von einem Docht aufgesogen wird. So brennt es langsam mit niedrigen Flammen, ähnlich einer Öllampe, und die Umgebung bleibt vergleichsweise geschont. Arme, Beine und Kopf haben meist weniger Fett als der Rumpf und liefern diesem Docht-Feuer deshalb weniger Brennstoff. Experimente an einem rund 95 Kilogramm schweren Schweinekadaver in einer Baumwolldecke zeigten, dass sich ein solches Feuer über mehr als 6,5 Stunden selbst am Leben hielt, bis die Forscher es löschten, nachdem eine äußere Flamme es einmal entzündet hatte. Die sparsamste Erklärung ist daher die, die ohne zusätzliche Annahme auskommt, und sie lässt sich an Zündquelle, Kleidung und Fettverteilung überprüfen. Ein Brandbeschleuniger wäre eine zusätzliche Annahme, die erst Rückstände belegen müssten. Dass der Rumpf dem Brandherd am nächsten lag, erklärt nicht, warum Arme und Beine am selben Körper kaum betroffen sind und der Raum nur mäßig geschädigt ist. Ein schwelendes Polster setzt Möbel voraus, von denen im Szenario keine Rede ist. Dass ein Brandbeschleuniger hier nichts erklärt, heißt nicht, dass er ausgeschlossen ist: Würden Spuren davon gefunden, änderte das die Lage.","coreRule":"⚡ Wo das Fett sitzt, brennt der Docht weiter.","beleg":"Werkstück C.5.6 (Anwendung & Relevanz, In der Forensik allgemein)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Ungleichmäßiges Verbrennen belegt keinen Brandbeschleuniger: Schmelzendes Unterhautfett wird von Kleidung wie von einem Docht aufgesogen und brennt langsam weiter. Der Denkfehler wäre, für etwas Erklärbares eine Zusatzannahme zu bemühen.","prueffrage":"Welche Körperteile sind stark verbrannt, welche kaum, und worin unterscheiden sie sich außer in ihrer Lage?","rueckmeldung":[{"option":1,"text":"Der ungleichmäßige Brand wirkt wie eine Spur von außen, und Brandbeschleuniger sind prüfbar. Die Erklärung ist aber eine zusätzliche Annahme, die erst Rückstände belegen müssten. Fänden sich welche, änderte das die Lage; bisher erklärt Verbrennungsphysik das Muster auch ohne."},{"option":2,"text":"Nähe zum Brandherd verstärkt die Wirkung der Hitze tatsächlich. Sie erklärt aber nicht, warum Arme und Beine am selben Körper kaum betroffen sind und der Raum nur mäßig geschädigt ist. Dafür braucht es einen Mechanismus, der auf den Rumpf selbst zielt."},{"option":3,"text":"Ein schwelendes Polster könnte einen Körper von unten lange erhitzen. Im Szenario ist aber von Möbeln keine Rede; die Erklärung setzt also etwas voraus, das nicht genannt ist. Sparsamer ist eine Erklärung, die ohne solche Zusatzannahmen auskommt."}],"familie":"bekannte-ursache-zuerst","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"DeHaan, J. D.; Nurbakhsh, S. (2001): Sustained Combustion of an Animal Carcass … J Forensic Sci 46(5):1076–1081 – PubMed-Abstract","oeffentlich":true,"url":"https://pubmed.ncbi.nlm.nih.gov/11569545/","abruf":"2026-10-12"},{"typ":"doi","kurz":"DeHaan, J. D.; Nurbakhsh, S. (2001): Sustained Combustion of an Animal Carcass … J Forensic Sci 46(5) (Volltext kostenpflichtig)","oeffentlich":false,"doi":"10.1520/JFS15101J"},{"typ":"url","kurz":"Christensen, A. M. (2000): Debunking the Spontaneous Human Combustion Myth. Masterarbeit, University of Tennessee (TRACE)","oeffentlich":true,"url":"https://trace.tennessee.edu/utk_gradthes/4133","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"1ffba5fbfe8fa189"}},{"id":"qx-c2-056","clusterId":"C","werkstueckRef":"C.5.6","stufe":3,"question":"Welche Folge ist bei diesem Vorgehen am wahrscheinlichsten und warum problematisch?","scenario":"Bei den Ermittlungen zu einem Brandtod liegt ein fast völlig verbrannter Körper in einem kaum beschädigten Zimmer. Ein Ermittler sieht keine offensichtliche Zündquelle und schreibt „unerklärlich“ in den Bericht.","options":["Der Fall kann als Beleg für Selbstentzündung gelten, weil ein einzelnes ungeklärtes Ereignis zur allgemeinen Gesetzmäßigkeit erhoben wird.","Eine echte Brandursache, etwa ein Unfall oder eine Tat, kann unentdeckt bleiben, weil aus „nicht gefunden“ vorschnell „nicht vorhanden“ wird.","Die Aussagen von Nachbarn über den Brand können überschätzt werden, weil ihr selbstsicheres Auftreten mit Richtigkeit verwechselt wird.","Der Tod der Person kann rückblickend als absehbar gelten, weil man den Ausgang kennt und frühere Warnzeichen überschätzt."],"correctIndex":1,"explanation":"Der Schluss „Ich sehe keine offensichtliche Ursache, also gab es keine“ ist ein Fehlschluss: Dass etwas nicht sofort erkennbar ist, heißt nicht, dass es nicht existiert. Zudem ist die Unversehrtheit der Umgebung kein Beweis gegen ein gewöhnliches Feuer. Brandversuche (DeHaan und Nurbakhsh, 2001) zeigten, dass ein in eine Baumwolldecke gewickelter Schweinekadaver, gewählt als Ersatz für einen menschlichen Körper, sich über mehr als 6,5 Stunden selbst am Leben erhaltend verbrannte, mit der Decke als Docht und dem Körperfett als Brennstoff. Wer vorschnell „unerklärlich“ schreibt, prüft nicht mehr, ob in Reichweite eine Zigarette, Kerze oder ein Kamin stand und ob der Körper genug Fett als Brennstoff hatte. So kann ein Unfall oder eine Tat übersehen werden. Ein Einzelfall wird nur zur Regel, wenn jemand ihn verallgemeinert; der Ermittler schreibt aber nur „unerklärlich“ und sagt nichts über andere Fälle. Nachbarn oder andere Zeugen kommen im Szenario nicht vor, daher geht es nicht um die Überschätzung ihrer Aussagen. Warnzeichen vor dem Tod nennt das Szenario ebenfalls nicht, der Bericht beschreibt nur den Fund und das Fehlen einer sichtbaren Zündquelle.","coreRule":"⚡ „Keine offensichtliche Zündquelle“ ist nicht „keine Zündquelle“.","quote":"","quoteLabel":"","beleg":"Werkstück C.5.6 (Anwendung & Relevanz; Red Flags; Der Kipppunkt; Das Anti-Denkmuster)","status":"entwurf","kurz":"Wer „keine Ursache gesehen“ mit „keine Ursache vorhanden“ gleichsetzt, hört auf zu suchen. Dann bleibt unentdeckt, ob eine Zigarette, Kerze oder ein Kamin in der Nähe war. Auch ein gewöhnliches Feuer kann einen Körper verbrennen und das Zimmer kaum beschädigen.","prueffrage":"Welche alltäglichen Zündquellen kämen in einem Wohnzimmer infrage, und welche davon hinterlassen nach einem Brand kaum Spuren?","rueckmeldung":[{"option":0,"text":"Ein ungeklärter Fall kann später tatsächlich als Beleg für Selbstentzündung herhalten. Der Ermittler schreibt aber nur „unerklärlich“ und sagt nichts über andere Fälle. Das Problem liegt davor: Er hört auf zu suchen."},{"option":2,"text":"Selbstsicheres Auftreten mit Richtigkeit zu verwechseln, ist ein bekannter Fehler. Im Szenario kommen aber gar keine Nachbarn oder anderen Zeugen vor, über deren Aussagen man urteilen müsste."},{"option":3,"text":"Im Rückblick überschätzt man oft frühere Warnzeichen, weil man den Ausgang kennt. Das Szenario nennt aber keine Warnzeichen, es beschreibt nur den Fund und das Fehlen einer sichtbaren Zündquelle. Dieser Denkfehler hat hier keinen Anhaltspunkt."}],"familie":"bekannte-ursache-zuerst","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"DeHaan, J. D.; Nurbakhsh, S. (2001): Sustained Combustion of an Animal Carcass … J Forensic Sci 46(5):1076–1081 – PubMed-Abstract","oeffentlich":true,"url":"https://pubmed.ncbi.nlm.nih.gov/11569545/","abruf":"2026-10-12"},{"typ":"doi","kurz":"DeHaan, J. D.; Nurbakhsh, S. (2001): Sustained Combustion of an Animal Carcass … J Forensic Sci 46(5) (Volltext kostenpflichtig)","oeffentlich":false,"doi":"10.1520/JFS15101J"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"16649706e8bcaecc"}}]`);export{t as n,n as t};